        Verse(book = "Jòb", chapter = 1, verseNumber = 13, text = "Yon jou, pitit gason ak pitit fi Jòb yo te nan gwo resepsyon kay pi gran frè a. Yo t'ap manje, yo t'ap bwè diven.", bookId = 18),
        Verse(book = "Jòb", chapter = 1, verseNumber = 14, text = "Yon mesaje kouri vin jwenn Jòb, li di l' konsa: -Nou t'ap raboure tè ak bèf yo, fenmèl bourik yo t'ap manje toupre,", bookId = 18),
        Verse(book = "Jòb", chapter = 1, verseNumber = 15, text = "lè yon bann moun Seba tonbe sou nou, yo pran tout bèt yo, yo touye tout moun ou yo. Se renk mwen menm ki resi chape vin di ou sa.", bookId = 18),
        Verse(book = "Jòb", chapter = 1, verseNumber = 16, text = "Msye pa t' ankò fin pale lè yon lòt moun kouri vini. Li di konsa: -Loraj tonbe sou mouton yo, li boule ni bèt yo ni gadò yo. Se renk mwen menm ki resi chape vin fè ou konn sa.", bookId = 18),
        Verse(book = "Jòb", chapter = 1, verseNumber = 17, text = "Msye pa t' ankò fin pale lè yon lòt moun rive, li di konsa: -Twa bann moun Kalde tonbe sou chamo ou yo, yo pran yo, y' ale ak yo. Yo touye tout moun ou yo. Se renk mwen menm ki resi chape vin di ou sa.", bookId = 18),
        Verse(book = "Jòb", chapter = 1, verseNumber = 18, text = "Msye t'ap pale toujou lè yon lòt moun vin rive, li di konsa: -Pitit gason ak pitit fi ou yo t'ap manje, yo t'ap bwè diven lakay premye pitit gason ou lan,", bookId = 18),
        Verse(book = "Jòb", chapter = 1, verseNumber = 19, text = "lè yon sèl gwo van tanpèt leve soti nan dezè a. Li kraze kay la, li touye tout moun. Se renk mwen menm ki resi chape vin di ou sa.", bookId = 18),
        Verse(book = "Jòb", chapter = 1, verseNumber = 20, text = "Lè Jòb tande sa, li leve. Yon sèl lapenn pran l', li chire rad sou li, li koupe tout cheve nan tèt li, li lage kò l' atè, li bese tèt li.", bookId = 18),
        Verse(book = "Jòb", chapter = 1, verseNumber = 21, text = "Epi li di: -San anyen m' soti nan vant manman m'. San anyen m'ap tounen anba tè. Seyè a bay! Seyè a pran! Lwanj pou Seyè a!", bookId = 18),
        Verse(book = "Jòb", chapter = 1, verseNumber = 22, text = "Malgre tout malè sa yo ki te rive l', Jòb pa t' fè ankenn peche, ni li pa janm di sa li pa t' dwe di sou Bondye.", bookId = 18),
        Verse(book = "Jòb", chapter = 2, verseNumber = 1, text = "Yon jou tout zanj Bondye yo te reyini devan Seyè a, Satan vini tou nan mitan yo.", bookId = 18),
