        Verse(book = "Jòb", chapter = 2, verseNumber = 3, text = "Seyè a di Satan konsa: -Eske ou te wè Jòb, sèvitè m' lan? Pa gen tankou l' sou tout latè. Se yon nonm san repwòch ki mache dwat nan tou sa l'ap fè. Li gen krentif pou Bondye, li toujou ap chache fè sa ki byen. Se koulye a li kenbe m'. Ou wè se pou gremesi ou t'ap pouse m' pou m' te fini avè l'.", bookId = 18),
        Verse(book = "Jòb", chapter = 2, verseNumber = 4, text = "Satan reponn li: -Lavi miyò pase byen! Yon moun va bay tou sa li genyen pou l' pa mouri.", bookId = 18),
        Verse(book = "Jòb", chapter = 2, verseNumber = 5, text = "Men, si ou manyen kò pa l' menm, ou mèt sèten fwa sa a, l'ap di sa li pa t' dwe di sou ou nan figi ou.", bookId = 18),
