        Verse(book = "Jòb", chapter = 2, verseNumber = 7, text = "Lamenm, Satan vire do l', li ale. Li fè gwo bouton pete sou tout kò Jòb, depi anba pla pye l' jouk nan po tèt li.", bookId = 18),
        Verse(book = "Jòb", chapter = 2, verseNumber = 8, text = "Lè sa a, Jòb soti, li al chita nan pil sann kote yo boule fatra. Li pran yon moso krich kraze pou grate kò l'.", bookId = 18),
        Verse(book = "Jòb", chapter = 2, verseNumber = 9, text = "Madanm li di l' konsa: -Ou nan kenbe pye Bondye fèm toujou? Joure l' byen joure, epi mouri mouri ou kont fini!", bookId = 18),
        Verse(book = "Jòb", chapter = 2, verseNumber = 10, text = "Jòb di li: -Pe bouch ou la, madanm! W'ap pale tankou moun fou! Lè Bondye ban nou benediksyon, nou kontan. Atò poukisa pou nou plenyen lè li voye malè sou nou? Malgre tou sa ki te rive l', Jòb pa t' kite ankenn move pawòl soti nan bouch li pou li fè peche kont Bondye.", bookId = 18),
        Verse(book = "Jòb", chapter = 2, verseNumber = 11, text = "Twa nan zanmi Jòb yo vin konnen tout malè ki te tonbe sou li. Yo kite peyi yo, yo vin wè Job. Se te Elifaz, moun Teman, Bildad, moun Chwak, epi Sofa, moun Naama. Yo fè lide vin ansanm pou plenn sò li epi pou ba li kouraj.", bookId = 18),
        Verse(book = "Jòb", chapter = 2, verseNumber = 12, text = "Yo te yon bèl ti distans toujou lè yo wè Jòb. Yo pa t' rekonèt li. Lè yo rekonèt li, dlo vin nan je yo, yo konmanse rele, yo kriye. Yo chire rad sou yo, yo voye pousyè tè sou tèt yo tèlman sa te fè yo lapenn.", bookId = 18),
        Verse(book = "Jòb", chapter = 2, verseNumber = 13, text = "Apre sa, yo chita atè a bò kot Jòb pandan sèt jou sèt nwit san di yon mo, paske yo te wè jan l'ap soufri.", bookId = 18),
        Verse(book = "Jòb", chapter = 3, verseNumber = 1, text = "Bout pou bout, Jòb louvri bouch li, li pran madichonnen jou l' te fèt la.", bookId = 18),
        Verse(book = "Jòb", chapter = 3, verseNumber = 2, text = "Li di konsa:", bookId = 18),
        Verse(book = "Jòb", chapter = 3, verseNumber = 3, text = "-Se pou Bondye efase jou m' te fèt la. Se pou l' efase jou lannwit m' te konmanse devlope nan vant manman m' lan.", bookId = 18),
        Verse(book = "Jòb", chapter = 3, verseNumber = 4, text = "Fè jou sa a tounen fènwa, Bondye! Kote ou chita anwo a, pa janm chonje jou sa a ankò. Pa janm kite limyè solèy klere l'.", bookId = 18),
        Verse(book = "Jòb", chapter = 3, verseNumber = 5, text = "Se pou fènwa anvayi jou sa a. Se pou nwaj kouvri l' nèt. Se pou lonbraj lanmò bouche l' nèt.", bookId = 18),
        Verse(book = "Jòb", chapter = 3, verseNumber = 6, text = "Jou lannwit sa a, se pou fènwa pran l' pou li nèt. Se pou l' disparèt nèt nan lanne a pou yo pa janm konte l' nan almanak ankò.", bookId = 18),
        Verse(book = "Jòb", chapter = 3, verseNumber = 7, text = "Se pou jou lannwit sa a fè cheve nan tèt moun kanpe, pou yo pa tande pèsonn ap ri!", bookId = 18),
        Verse(book = "Jòb", chapter = 3, verseNumber = 8, text = "Se pou chòche yo bay jou lannwit sa a madichon, yo menm ki konn ki jan pou yo eksite levyatan an!", bookId = 18),
        Verse(book = "Jòb", chapter = 3, verseNumber = 9, text = "Pa kite gwo zetwal devanjou a klere jou sa a. Pa janm fè bajou kase pou li, pou l' pa janm wè solèy leve.", bookId = 18),
        Verse(book = "Jòb", chapter = 3, verseNumber = 10, text = "Paske li pa t' enpoze m' soti nan vant manman m', li pa t' egzante m' tout soufrans sa yo.", bookId = 18),
        Verse(book = "Jòb", chapter = 3, verseNumber = 11, text = "Poukisa mwen pa t' mouri depi nan vant manman m'? Poukisa mwen pa t' tou mouri nan pasaj kite sa?", bookId = 18),
        Verse(book = "Jòb", chapter = 3, verseNumber = 12, text = "Poukisa mwen te jwenn yon manman ki pran m' sou jenou li epi ki ban m' tete?", bookId = 18),
        Verse(book = "Jòb", chapter = 3, verseNumber = 13, text = "Si m' te mouri, atò konsa mwen pa ta nan tout lapenn sa a. Mwen ta kouche yon kote ap dòmi ak kè poze,", bookId = 18),
        Verse(book = "Jòb", chapter = 3, verseNumber = 14, text = "ansanm ak wa yo ak gwo chèf yo, ki fè bati gwo tonm pou yo nan mitan dezè.", bookId = 18),
        Verse(book = "Jòb", chapter = 3, verseNumber = 15, text = "Mwen ta kouche ap dòmi ansanm ak chèf ki te gen kay yo plen lò ak ajan.", bookId = 18),
        Verse(book = "Jòb", chapter = 3, verseNumber = 16, text = "Ou ankò, mwen ta tankou yon timoun ki fèt anvan tèm, tankou timoun ki fèt tou mouri.", bookId = 18),
        Verse(book = "Jòb", chapter = 3, verseNumber = 17, text = "Kote yo ye anba tè a, mechan yo sispann bay kò yo mouvman. Anba tè a, sa ki bouke travay ap poze kò yo.", bookId = 18),
        Verse(book = "Jòb", chapter = 3, verseNumber = 18, text = "Anba tè a, tout prizonye gen kè poze. Yo p'ap tande vwa majò prizon an nan zòrèy yo.", bookId = 18),
        Verse(book = "Jòb", chapter = 3, verseNumber = 19, text = "Anba tè a, se menm bagay pou grannèg kou malere. Ata esklav pa gen mèt ankò!", bookId = 18),
        Verse(book = "Jòb", chapter = 3, verseNumber = 20, text = "Poukisa, Bondye, ou kite moun ki nan mizè ap viv? Poukisa ou bay moun ki nan gwo lapenn lavi?", bookId = 18),
        Verse(book = "Jòb", chapter = 3, verseNumber = 21, text = "Y'ap tann lanmò konsa. Men, lanmò pa vini! Yo ta pito lanmò pase nenpòt gwo richès!", bookId = 18),
        Verse(book = "Jòb", chapter = 3, verseNumber = 22, text = "Yo pa gen kè kontan toutotan yo pa mouri, toutotan yo pa ale anba tè.", bookId = 18),
        Verse(book = "Jòb", chapter = 3, verseNumber = 23, text = "Yo pa konn sa pou yo fè. Bondye sènen yo kote yo pase.", bookId = 18),
        Verse(book = "Jòb", chapter = 3, verseNumber = 24, text = "Mwen pa ka manje. Se plenn m'ap plenn. M'ap soufri, dlo nan je m' tankou larivyè k'ap koule.", bookId = 18),
        Verse(book = "Jòb", chapter = 3, verseNumber = 25, text = "Sa m' pè rive m' lan, se li k'ap rive m'. Sa m' pa ta vle wè a, se li ki tonbe sou mwen.", bookId = 18),
        Verse(book = "Jòb", chapter = 3, verseNumber = 26, text = "Kè m' pa poze. Tèt mwen pa la. Mwen pa ka dòmi. Se soti nan ka tonbe nan ka.", bookId = 18),
        Verse(book = "Jòb", chapter = 4, verseNumber = 1, text = "Elifaz, moun Teman an, pran lapawòl, li di konsa:", bookId = 18),
        Verse(book = "Jòb", chapter = 4, verseNumber = 2, text = "-Jòb, si m' pale avè ou, ou p'ap fache, vye frè? Mwen pa ka pa pale.", bookId = 18),
        Verse(book = "Jòb", chapter = 4, verseNumber = 3, text = "Yon lè, se ou ki te konn moutre moun anpil bagay, se ou ki te konn bay moun fòs lè yo fèb.", bookId = 18),
        Verse(book = "Jòb", chapter = 4, verseNumber = 4, text = "Pawòl nan bouch ou te yon ankourajman pou moun ki te dekouraje. Ou te ede yo kanpe sou de pye yo ankò.", bookId = 18),
        Verse(book = "Jòb", chapter = 4, verseNumber = 5, text = "Koulye a, paske se tou pa ou, ou pèdi tèt ou. Malè tonbe sou ou, w'ap depale.", bookId = 18),
        Verse(book = "Jòb", chapter = 4, verseNumber = 6, text = "W'ap sèvi Bondye, ou fèt pou genyen l' konfyans. Ou mennen bak ou byen, ou pa fèt pou dekouraje.", bookId = 18),
        Verse(book = "Jòb", chapter = 4, verseNumber = 7, text = "Repase tèt ou byen. Ou janm konnen yon inonsan ki mouri mal? Ou janm wè yo touye yon moun ki mache dwat?", bookId = 18),
        Verse(book = "Jòb", chapter = 4, verseNumber = 8, text = "M'ap di sa m' wè ak je m': Moun ki kouve mechanste nan kè yo epi k'ap mache bay moun lapenn, se mechanste ak lapenn yo rekòlte.", bookId = 18),
        Verse(book = "Jòb", chapter = 4, verseNumber = 9, text = "Lè Bondye fache, li soufle sou yo, yo mouri. Lè van tanpèt Bondye a leve, yo disparèt.", bookId = 18),
        Verse(book = "Jòb", chapter = 4, verseNumber = 10, text = "Mechan yo rele kou lyon, yo gwonde kou bèt sovaj. Men, Bondye fèmen bouch yo, li kase dan nan bouch yo.", bookId = 18),
        Verse(book = "Jòb", chapter = 4, verseNumber = 11, text = "Yo mouri tankou lyon ki pa jwenn bèt pou yo manje. Tout pitit yo gaye nan bwa.", bookId = 18),
        Verse(book = "Jòb", chapter = 4, verseNumber = 12, text = "Yon lè, mwen tande Bondye t'ap pale tou dousman nan zòrèy mwen. Mwen pa t' fin tande nèt sa li t'ap di.", bookId = 18),
        Verse(book = "Jòb", chapter = 4, verseNumber = 13, text = "Tankou yon move rèv nan mitan lannwit, li mete yon bann vye lide nan tèt mwen. M' pa ka dòmi tèlman mwen pè.", bookId = 18),
        Verse(book = "Jòb", chapter = 4, verseNumber = 14, text = "Mwen pran tranble, mwen santi yon frison mache nan tout kò m'. Tout zo nan kò m' ap krake.", bookId = 18),
        Verse(book = "Jòb", chapter = 4, verseNumber = 15, text = "Yon souf pase bò figi m', tout cheve nan tèt mwen kanpe.", bookId = 18),
        Verse(book = "Jòb", chapter = 4, verseNumber = 16, text = "Mwen rete konsa mwen wè yon moun kanpe devan m'. Mwen pa t' rekonèt ki moun li ye. Men, fòm moun lan te la devan je m'. Mwen pa tande yon ti bri menm. Apre sa, mwen tande yon vwa ki t'ap pale tou dousman, li t'ap di:", bookId = 18),
        Verse(book = "Jòb", chapter = 4, verseNumber = 17, text = "Ki moun ki ka di li mache dwat devan Bondye? Ki moun ki san repwòch devan Bondye ki kreye l' la?", bookId = 18),
        Verse(book = "Jòb", chapter = 4, verseNumber = 18, text = "Bondye pa janm fin fye sèvitè l' yo nèt. Ata zanj li yo, li jwenn bagay pou l' repwoche yo.", bookId = 18),
        Verse(book = "Jòb", chapter = 4, verseNumber = 19, text = "Ale wè atò pou moun ki fèt ak labou, pou moun ki soti nan pousyè tè, pou moun yo kapab kraze tankou poudbwa!", bookId = 18),
        Verse(book = "Jòb", chapter = 4, verseNumber = 20, text = "Yon sèl jou kont pou yo tounen pousyè, yo disparèt nèt. Pesonn pa wè sa.", bookId = 18),
        Verse(book = "Jòb", chapter = 4, verseNumber = 21, text = "Yo rete konsa yo kase kòd. Yo mouri san yo pa janm rive fin gen bon konprann.", bookId = 18),
        Verse(book = "Jòb", chapter = 5, verseNumber = 1, text = "Rele non, Jòb! W'a wè si gen moun k'ap reponn ou! Ak kilès nan zanj Bondye yo ou ta vle pale?", bookId = 18),
        Verse(book = "Jòb", chapter = 5, verseNumber = 2, text = "Se moun fou ki kite chagren ap minen yo. Se moun sòt ki kite move san touye yo.", bookId = 18),
        Verse(book = "Jòb", chapter = 5, verseNumber = 3, text = "Mwen menm, mwen wè moun fou ki te kwè zafè yo bon. M' rete konsa, mwen wè madichon tonbe sou kay yo.", bookId = 18),
        Verse(book = "Jòb", chapter = 5, verseNumber = 4, text = "Pitit yo pa ka jwenn yon moun pou pwoteje yo. Pa gen pesonn pou pran defans yo nan tribinal.", bookId = 18),
        Verse(book = "Jòb", chapter = 5, verseNumber = 5, text = "Se moun grangou ki pral manje rekòt jaden yo. Yo pral pran ata sa ki donnen nan raje pikan. Se moun akrèk ki pral mete men sou tout byen yo.", bookId = 18),
        Verse(book = "Jòb", chapter = 5, verseNumber = 6, text = "Non. Lafliksyon pa tonbe sou moun konsa konsa. Ni moun pa rete konsa pou l' tonbe anba soufrans.", bookId = 18),
        Verse(book = "Jòb", chapter = 5, verseNumber = 7, text = "Menm jan tensèl dife fèt pou vole, konsa tou, moun fèt pou soufri.", bookId = 18),
        Verse(book = "Jòb", chapter = 5, verseNumber = 8, text = "Si m' te nan plas ou, Job, se Bondye m' ta rele. Mwen ta mete sitiyasyon an devan l'.", bookId = 18),
        Verse(book = "Jòb", chapter = 5, verseNumber = 9, text = "Se li menm ki fè yon bann bèl bagay nou pa ka fin konprann, yon dal mèvèy nou pa ka fin konte.", bookId = 18),
        Verse(book = "Jòb", chapter = 5, verseNumber = 10, text = "Li voye lapli sou latè, li wouze tout jaden.", bookId = 18),
        Verse(book = "Jòb", chapter = 5, verseNumber = 11, text = "Moun ki t'ap mache tèt bese yo, se li menm ki fè yo leve tèt yo. Se li menm ki konsole moun ki te nan lapenn yo.", bookId = 18),
        Verse(book = "Jòb", chapter = 5, verseNumber = 12, text = "Li gate mannigèt bakoulou yo. Li pa janm kite yo rive fè sa yo te mete nan tèt yo.", bookId = 18),
        Verse(book = "Jòb", chapter = 5, verseNumber = 13, text = "Li pran moun entelijan yo nan pèlen yo te tann. Li pa kite mètdam yo reyalize plan yo te fè.", bookId = 18),
        Verse(book = "Jòb", chapter = 5, verseNumber = 14, text = "Gwo lajounen y'ap bite tankou nan fènwa. Gwo midi, y'ap tatonnen tankou nan mitan lannwit.", bookId = 18),
        Verse(book = "Jòb", chapter = 5, verseNumber = 15, text = "Men, Bondye sove pòv la anba dan yo. Li delivre malere anba ponyèt grannèg k'ap peze yo.", bookId = 18),
        Verse(book = "Jòb", chapter = 5, verseNumber = 16, text = "Li bay pòv yo espwa. Li fèmen bouch mechan yo.", bookId = 18),
        Verse(book = "Jòb", chapter = 5, verseNumber = 17, text = "Ala bon sa bon pou yon moun lè Bondye ap korije l'! Lè Bondye ki gen tout pouvwa a ap pini ou, pa pran sa an jwèt!", bookId = 18),
        Verse(book = "Jòb", chapter = 5, verseNumber = 18, text = "Lè li blese ou, se li menm ankò k'ap mete renmèd pou ou. Lè li frape ou, se li menm ankò k'ap geri ou.", bookId = 18),
        Verse(book = "Jòb", chapter = 5, verseNumber = 19, text = "Lapo delivre ou nan tout move pa. Ankenn malè p'ap tonbe sou ou.", bookId = 18),
        Verse(book = "Jòb", chapter = 5, verseNumber = 20, text = "Nan grangou, li p'ap kite ou mouri. Nan lagè, li p'ap kite yo touye ou.", bookId = 18),
        Verse(book = "Jòb", chapter = 5, verseNumber = 21, text = "L'a pwoteje ou anba kout lang. Ou p'ap bezwen pè lè w'a wè gwo malè ap pwoche.", bookId = 18),
        Verse(book = "Jòb", chapter = 5, verseNumber = 22, text = "W'a pase ni malè ni grangou nan rizib. Ou p'ap pè bèt nan bwa.", bookId = 18),
        Verse(book = "Jòb", chapter = 5, verseNumber = 23, text = "Jaden w'ap travay yo p'ap gen wòch ladan yo. Bèt nan bwa p'ap janm atake ou.", bookId = 18),
        Verse(book = "Jòb", chapter = 5, verseNumber = 24, text = "Lè sa a, w'a viv ak kè poze lakay ou. Lè w'a vizite pak zannimo ou yo, w'a kontan.", bookId = 18),
        Verse(book = "Jòb", chapter = 5, verseNumber = 25, text = "W'a gen anpil pitit. Y'a pouse tankou plant nan jaden.", bookId = 18),
        Verse(book = "Jòb", chapter = 5, verseNumber = 26, text = "Menm jan se lè mayi fin mi yo kase l', konsa tou se lè ou fin vye granmoun, w'a mouri.", bookId = 18),
        Verse(book = "Jòb", chapter = 5, verseNumber = 27, text = "Jòb monchè, nou te kalkile sou bagay sa yo anpil. Se konsa sa ye, tande. Pa fè tèt di. Asepte verite a.", bookId = 18),
        Verse(book = "Jòb", chapter = 6, verseNumber = 1, text = "Jòb pran lapawòl, li di konsa:", bookId = 18),
        Verse(book = "Jòb", chapter = 6, verseNumber = 2, text = "-Si yo te ka pran pèz lapenn mwen, si yo te ka peze tout malè mwen yo nan balans,", bookId = 18),
        Verse(book = "Jòb", chapter = 6, verseNumber = 3, text = "yo ta jwenn yo pi lou pase tout sab ki bò lanmè. Lè sa a, nou pa ta sezi tande m' pale jan m'ap pale a.", bookId = 18),
        Verse(book = "Jòb", chapter = 6, verseNumber = 4, text = "Bondye ki gen tout pouvwa a plante flèch li yo sou mwen. Pwazon yo a anvayi tout kò m'. Bondye voye sou mwen tout kalite malè pou fè kè m' kase.", bookId = 18),
        Verse(book = "Jòb", chapter = 6, verseNumber = 5, text = "Bourik mawon pa ranni lè li gen zèb pou l' manje. Ni bèf pa rele lè li gen manje devan l'.", bookId = 18),
        Verse(book = "Jòb", chapter = 6, verseNumber = 6, text = "Moun pa manje manje ki san gou, manje ki san sèl. Blan ze pa gen bon gou nan bouch.", bookId = 18),
        Verse(book = "Jòb", chapter = 6, verseNumber = 7, text = "Mwen pa menm gen apeti pou bagay konsa. Tou sa mwen manje fè kè m' tounen.", bookId = 18),
        Verse(book = "Jòb", chapter = 6, verseNumber = 8, text = "Si Bondye te ka ban mwen sa m' mande l' la! Si li te ka fè m' jwenn sa m'ap tann lan!", bookId = 18),
        Verse(book = "Jòb", chapter = 6, verseNumber = 9, text = "Si sèlman sa ta fè l' plezi pou l' touye m'! Si li ta vle lonje men l' pou l' disparèt mwen!", bookId = 18),
        Verse(book = "Jòb", chapter = 6, verseNumber = 10, text = "Se ta va yon gwo konsolasyon pou mwen. Malgre tout soufrans mwen yo, mwen ta danse, mwen ta fè fèt, paske mwen konnen mwen pa janm dezobeyi lòd Bondye ki apa a bay.", bookId = 18),
        Verse(book = "Jòb", chapter = 6, verseNumber = 11, text = "Mwen pa gen fòs pou m' tann ankò. Pa gen ankenn espwa pou mwen. Sa m' bezwen viv toujou fè?", bookId = 18),
        Verse(book = "Jòb", chapter = 6, verseNumber = 12, text = "Se pa wòch mwen ye. Se pa bout fè kò m' ye.", bookId = 18),
        Verse(book = "Jòb", chapter = 6, verseNumber = 13, text = "Mwen pa gen fòs ankò pou m' kenbe. Kote m' vire, mwen pa jwenn sekou.", bookId = 18),
        Verse(book = "Jòb", chapter = 6, verseNumber = 14, text = "Nan tray m'ap pase koulye a, mwen bezwen bon zanmi ki pou soutni m', menm si mwen ta vire do bay Bondye.", bookId = 18),
        Verse(book = "Jòb", chapter = 6, verseNumber = 15, text = "Men, frè m' yo, nou p'ap di m' anyen la a. Nou tankou ravin chèch ki pa gen dlo depi lapli pa tonbe.", bookId = 18),
        Verse(book = "Jòb", chapter = 6, verseNumber = 16, text = "Nan sezon fredi, lè lanèj ap fonn, yo plen dlo sal ki frèt kou glas.", bookId = 18),
        Verse(book = "Jòb", chapter = 6, verseNumber = 17, text = "Men, nan sezon lesèk, pa yon gout dlo! Chalè solèy la cheche yo nèt.", bookId = 18),
        Verse(book = "Jòb", chapter = 6, verseNumber = 18, text = "Bann vwayajè yo kite chemen yo pou y' al dèyè dlo. Yo pèdi nan dezè a. Yo mouri.", bookId = 18),
        Verse(book = "Jòb", chapter = 6, verseNumber = 19, text = "Vwayajè ki soti nan peyi Cheba ak nan peyi Saba ap touye tèt yo chache dlo.", bookId = 18),
        Verse(book = "Jòb", chapter = 6, verseNumber = 20, text = "Yo pa ka jwenn. Rive devan ravin lan, yo pa konn sa pou yo fè.", bookId = 18),
        Verse(book = "Jòb", chapter = 6, verseNumber = 21, text = "Wi, mezanmi. Nou tankou yon ravin chèch pou mwen. Nou wè nan ki eta mwen ye, nou pè, n'ap renka kò nou dèyè.", bookId = 18),
        Verse(book = "Jòb", chapter = 6, verseNumber = 22, text = "Eske m' te mande nou pou nou fè m' kado kichòy? Osinon pou nou fè yon moun kado pou mwen nan sa nou genyen?", bookId = 18),
        Verse(book = "Jòb", chapter = 6, verseNumber = 23, text = "Eske mwen te mande nou pou nou vin wete m' anba grif yon lènmi, osinon pou nou delivre m' anba men yon moun k'ap fè m' soufri?", bookId = 18),
        Verse(book = "Jòb", chapter = 6, verseNumber = 24, text = "Bon. Pale avè m'. Si m' antò, fè m' wè kote m' antò a. Lè sa a, m'a pe bouch mwen. M'a koute nou.", bookId = 18),
        Verse(book = "Jòb", chapter = 6, verseNumber = 25, text = "Pawòl ki pale verite bon pou tande. Men, m' pa wè sa nou vle di m' la a.", bookId = 18),
        Verse(book = "Jòb", chapter = 6, verseNumber = 26, text = "Ou di mwen fin dekouraje. Se depale m'ap depale. Poukisa atò w'ap kritike pawòl mwen yo konsa?", bookId = 18),
        Verse(book = "Jòb", chapter = 6, verseNumber = 27, text = "Konsa tou, ou ta rive jwe lajan sou tèt timoun san papa. Ou ta fè lajan sou tèt bon zanmi ou.", bookId = 18),
        Verse(book = "Jòb", chapter = 6, verseNumber = 28, text = "Koulye a, monchè, tanpri, gade m' nan je. Mwen p'ap ba ou manti.", bookId = 18),
        Verse(book = "Jòb", chapter = 6, verseNumber = 29, text = "Tounen non! Pa fè m' lenjistis sa a! Tounen, mwen di ou. Se kòz mwen m'ap defann.", bookId = 18),
        Verse(book = "Jòb", chapter = 6, verseNumber = 30, text = "Eske se manti m'ap bay? Dapre nou, mwen pa konnen sa ki byen ak sa ki mal?", bookId = 18),
        Verse(book = "Jòb", chapter = 7, verseNumber = 1, text = "Lavi yon nonm sou latè, se tankou sèvis militè l'ap fè. Li tankou moun k'ap vann jounen!", bookId = 18),
        Verse(book = "Jòb", chapter = 7, verseNumber = 2, text = "Li tankou yon esklav k'ap tann lannwit pou l' poze, tankou yon travayè k'ap tann kòb jounen travay li.", bookId = 18),
        Verse(book = "Jòb", chapter = 7, verseNumber = 3, text = "Depi kèk mwa, m' pa wè poukisa m'ap viv. Tout lannwit se soufri m'ap soufri.", bookId = 18),
        Verse(book = "Jòb", chapter = 7, verseNumber = 4, text = "M' poko kouche nan kabann mwen, m'ap mande kilè pou l' jou. Nwit la long. M' pa ka dòmi, yon bann vye lide ap pase nan tèt mwen jouk solèy leve.", bookId = 18),
        Verse(book = "Jòb", chapter = 7, verseNumber = 5, text = "Tout kò m' plen vè ak gwo plak bouton toupatou. Po m' fann fann, l'ap bay postim.", bookId = 18),
        Verse(book = "Jòb", chapter = 7, verseNumber = 6, text = "Jou m' yo pase pi vit pase zegwi nan men moun k'ap maye senn. Yo disparèt, pa gen anyen m'ap tann ankò.", bookId = 18),
        Verse(book = "Jòb", chapter = 7, verseNumber = 7, text = "Bondye o! Pa bliye, lavi m' tankou yon nwaj k'ap pase. Lè m'a fèmen je m', mwen p'ap janm kapab jwi lavi a ankò.", bookId = 18),
        Verse(book = "Jòb", chapter = 7, verseNumber = 8, text = "Ou wè m' koulye a, men ou p'ap janm wè m' ankò. W'a chache m', ou p'ap jwenn mwen.", bookId = 18),
        Verse(book = "Jòb", chapter = 7, verseNumber = 9, text = "Tankou yon nwaj ki ale nèt, ki disparèt, lè yon moun mouri, pa gen leve pou li ankò.", bookId = 18),
        Verse(book = "Jòb", chapter = 7, verseNumber = 10, text = "Li p'ap janm tounen lakay li. Moun lakay li tou bliye l'.", bookId = 18),
        Verse(book = "Jòb", chapter = 7, verseNumber = 11, text = "Se poutèt sa, m' pa ka pa pale. Kè m' sere. Kite m' pale pale m'. Lapenn kaye nan kè m'. Kite m' plenyen plenyen m'.", bookId = 18),
        Verse(book = "Jòb", chapter = 7, verseNumber = 12, text = "Poukisa ou mete moun veye m' konsa? M' pa lanmè. M' pa gwo bèt lanmè.", bookId = 18),
        Verse(book = "Jòb", chapter = 7, verseNumber = 13, text = "M' te di nan kè m': M' pral lage kò m' yon kote. M'a pran yon ti kanpo. Si m' dòmi, m'a jwenn yon ti soulajman!", bookId = 18),
        Verse(book = "Jòb", chapter = 7, verseNumber = 14, text = "Men, ou fè m' fè yon bann vye rèv k'ap fè m' pè. M'ap fè yon bann vye vizyon k'ap fè m' tranble.", bookId = 18),
        Verse(book = "Jòb", chapter = 7, verseNumber = 15, text = "Lè konsa, pito moun te trangle m'. Pito m' te mouri pase pou m' soufri tout doulè sa yo.", bookId = 18),
        Verse(book = "Jòb", chapter = 7, verseNumber = 16, text = "Se fini m'ap fini. Fòk mwen mouri yon jou! Kite m' pou kont mwen. Lavi m' prèt pou bout!", bookId = 18),
        Verse(book = "Jòb", chapter = 7, verseNumber = 17, text = "Kisa lèzòm ye pou ou pran ka yo konsa? Kisa yo ye menm pou w'ap okipe yo konsa?", bookId = 18),
        Verse(book = "Jòb", chapter = 7, verseNumber = 18, text = "Chak maten ou pase wè jan yo ye. Chak lè, w'ap gade nan fon kè yo, w'ap sonde yo.", bookId = 18),
        Verse(book = "Jòb", chapter = 7, verseNumber = 19, text = "Kilè w'a sispann gade m'? Ban m' yon ti souf non kont pou m' vale krache m'!", bookId = 18),
        Verse(book = "Jòb", chapter = 7, verseNumber = 20, text = "Si m' fè peche, kisa m' fè ou? Di m' non, ou menm k'ap veye tou sa moun ap fè? Poukisa w'ap plante tout flèch ou yo nan kò m' konsa? Poukisa ou fè m' tounen yon chay pou ou?", bookId = 18),
        Verse(book = "Jòb", chapter = 7, verseNumber = 21, text = "Se sipòte ou pa ka sipòte ankò sa mwen fè ki mal? Se padonnen ou pa ka padonnen peche m' yo? Talè konsa mwen pral anba tè. W'a chache m', ou p'ap jwenn mwen ankò.", bookId = 18),
        Verse(book = "Jòb", chapter = 8, verseNumber = 1, text = "Lè sa a, Bildad, moun peyi Chwa a, pran lapawòl, li di konsa:", bookId = 18),
        Verse(book = "Jòb", chapter = 8, verseNumber = 2, text = "-Kilè w'a sispann pale jan w'ap pale a? Se bri ase w'ap fè tankou kalbas gran bouch!", bookId = 18),
        Verse(book = "Jòb", chapter = 8, verseNumber = 3, text = "Bondye pa nan lenjistis. Bondye ki gen tout pouvwa a ap toujou fè sa ki dwat.", bookId = 18),
        Verse(book = "Jòb", chapter = 8, verseNumber = 4, text = "Si pitit ou yo te dezobeyi lòd li yo, li fè yo peye sa yo fè a.", bookId = 18),
        Verse(book = "Jòb", chapter = 8, verseNumber = 5, text = "Ou menm menm, rele Bondye. Lapriyè nan pye Bondye ki gen tout pouvwa a.", bookId = 18),
        Verse(book = "Jòb", chapter = 8, verseNumber = 6, text = "Si li pa gen anyen pou l' repwoche ou, si ou toujou mache dwat devan li, lè sa a, ou mèt sèten, l'a fè kichòy pou ou, l'ap renmèt ou tou sa ou te genyen.", bookId = 18),
        Verse(book = "Jòb", chapter = 8, verseNumber = 7, text = "Tou sa ou te gen anvan an p'ap anyen devan sa Bondye pral ba ou a.", bookId = 18),
        Verse(book = "Jòb", chapter = 8, verseNumber = 8, text = "Chache konnen sa ki te pase nan tan lontan. Gade sa ki te rive zansèt nou yo.", bookId = 18),
        Verse(book = "Jòb", chapter = 8, verseNumber = 9, text = "Nou menm, nou se moun ayè. Nou pa konn anyen. Se pase n'ap pase sou tè a.", bookId = 18),
        Verse(book = "Jòb", chapter = 8, verseNumber = 10, text = "Men, granmoun tan lontan yo va moutre ou anpil bagay. Y'a pale avè ou. Tande sa y'ap di ou.", bookId = 18),
        Verse(book = "Jòb", chapter = 8, verseNumber = 11, text = "Se nan marekay ou jwenn jon. Wozo pa pouse kote ki pa gen dlo.", bookId = 18),
        Verse(book = "Jòb", chapter = 8, verseNumber = 12, text = "Nan tan chechrès, li te mèt tou piti, tou vèt, lè lesèk tonbe, anvan menm yo koupe l', premye zèb ki fennen se li menm.", bookId = 18),
        Verse(book = "Jòb", chapter = 8, verseNumber = 13, text = "Se menm bagay la tou pou moun ki bliye si gen Bondye. Moun ki vire do bay Bondye p'ap jwenn sa y'ap tann lan.", bookId = 18),
        Verse(book = "Jòb", chapter = 8, verseNumber = 14, text = "Konfyans yo pa chita sou anyen. Se tankou si y'ap apiye sou bwa pouri.", bookId = 18),
        Verse(book = "Jòb", chapter = 8, verseNumber = 15, text = "Si yo panche sou li, li ale. Si yo kenbe l' fò, y'ap blayi atè ansanm avè l'.", bookId = 18),
        Verse(book = "Jòb", chapter = 8, verseNumber = 16, text = "Mechan yo pouse tankou move zèb nan solèy. Yo pran tout jaden an pou yo.", bookId = 18),
        Verse(book = "Jòb", chapter = 8, verseNumber = 17, text = "Rasin yo mache nan mitan tout fant wòch yo. Se la yo jwenn sa yo bezwen pou yo viv.", bookId = 18),
        Verse(book = "Jòb", chapter = 8, verseNumber = 18, text = "Rache ou rache yo pa gen moun ki pou konnen kote yo te ye a.", bookId = 18),
        Verse(book = "Jòb", chapter = 8, verseNumber = 19, text = "Talè konsa, l'ap pouri bò chemen an. Se lòt k'ap pouse nan plas li.", bookId = 18),
        Verse(book = "Jòb", chapter = 8, verseNumber = 20, text = "Non, monchè! Bondye pa janm lage moun ki kenbe pye l' fèm. Ni li pa janm lonje men l' pou l' soutni mechan yo.", bookId = 18),
        Verse(book = "Jòb", chapter = 8, verseNumber = 21, text = "L'a fè kè ou kontan ankò, bouch ou pral chante bèl chante pou li.", bookId = 18),
        Verse(book = "Jòb", chapter = 8, verseNumber = 22, text = "Men, l'ap fè moun ki pa vle wè ou yo wont. Fanmi mechan yo va disparèt.", bookId = 18),
        Verse(book = "Jòb", chapter = 9, verseNumber = 1, text = "Lè sa a, Jòb pran lapawòl, li di konsa:", bookId = 18),
        Verse(book = "Jòb", chapter = 9, verseNumber = 2, text = "-Wi, mwen konnen se konsa sa ye. Men, ki jan pou yon moun ka gen rezon devan Bondye?", bookId = 18),
        Verse(book = "Jòb", chapter = 9, verseNumber = 3, text = "Si li vle plede ak Bondye, Bondye ap mande l' venmil keksyon, li p'ap ka reponn yonn menm.", bookId = 18),
        Verse(book = "Jòb", chapter = 9, verseNumber = 4, text = "Bondye sitèlman gen bon konprann, li sitèlman gen fòs, pa gen moun ki ka kenbe tèt avè l' pou yo pa peye sa.", bookId = 18),
        Verse(book = "Jòb", chapter = 9, verseNumber = 5, text = "Li deplase mòn yo lè lide l' di l'. Lè li an kòlè, li voye yo jete byen lwen.", bookId = 18),
        Verse(book = "Jòb", chapter = 9, verseNumber = 6, text = "Bondye fè tè a tranble kote l' chita a. Li souke poto ki soutni l' yo.", bookId = 18),
        Verse(book = "Jòb", chapter = 9, verseNumber = 7, text = "Li annik bay yon lòd, epi solèy la pa leve. Li fè zetwal yo pa klere lannwit.", bookId = 18),
        Verse(book = "Jòb", chapter = 9, verseNumber = 8, text = "Li te pou kont li lè li t'ap louvri syèl la anwo tè a. Li mache sou lanmè a jan li vle.", bookId = 18),
        Verse(book = "Jòb", chapter = 9, verseNumber = 9, text = "Se li ki fè zetwal yo: Gwo Kabwèt la, Oryon, Lapousiyè ak zetwal Sid yo.", bookId = 18),
        Verse(book = "Jòb", chapter = 9, verseNumber = 10, text = "Se li menm ki fè yon bann bèl bagay nou pa ka fin konprann, yon dal mèvèy nou pa ka fin konte.", bookId = 18),
        Verse(book = "Jòb", chapter = 9, verseNumber = 11, text = "Bondye te mèt ap pase toupre m', mwen pa ka wè l'. Li glise kò l', li ale.", bookId = 18),
        Verse(book = "Jòb", chapter = 9, verseNumber = 12, text = "Li pran sa l' bezwen. Pa gen moun ki pou enpoze l' fè l'. Pa gen moun ki ka penmèt yo mande l': Sa w'ap fè la a?", bookId = 18),
        Verse(book = "Jòb", chapter = 9, verseNumber = 13, text = "Bondye pa ka kenbe kòlè l' ankò! Li fè tout patizan Raab yo bese tèt devan li.", bookId = 18),
        Verse(book = "Jòb", chapter = 9, verseNumber = 14, text = "Se mwen menm atò ki pou ta kenbe tèt avè l'? Se mwen menm atò ki pou ta plede avè l'?", bookId = 18),
        Verse(book = "Jòb", chapter = 9, verseNumber = 15, text = "Menm si m' te gen rezon, sa m' bezwen defann tèt mwen fè? Se li k'ap jije m', se padon ase pou m' mande l'.", bookId = 18),
        Verse(book = "Jòb", chapter = 9, verseNumber = 16, text = "Menm si li ta reponn mwen lè m' rele l', mwen pa kwè li ta koute sa m'ap di l'.", bookId = 18),
        Verse(book = "Jòb", chapter = 9, verseNumber = 17, text = "Li rete konsa li kraze m' pou anyen. Li blese m' nan tout kò m', san m' pa fè anyen.", bookId = 18),
        Verse(book = "Jòb", chapter = 9, verseNumber = 18, text = "Li pa ban m' tan pou m' pran yon ti souf menm. Li voye malè sou mwen yonn apre lòt.", bookId = 18),
        Verse(book = "Jòb", chapter = 9, verseNumber = 19, text = "Mwen ta seye fè fòs avè l'? Fòs, se nan men l' sa ye. Mwen ta rele l' tribinal? Ki jij ki va voye manda ba li?", bookId = 18),
        Verse(book = "Jòb", chapter = 9, verseNumber = 20, text = "M' te mèt gen rezon, pawòl nan bouch mwen ap kondannen m'. M' te mèt inonsan, tou sa m'ap di ap ban m' tò.", bookId = 18),
        Verse(book = "Jòb", chapter = 9, verseNumber = 21, text = "Eske m' inonsan? M' pa menm ka di sa. Lavi pa di m' anyen ankò!", bookId = 18),
        Verse(book = "Jòb", chapter = 9, verseNumber = 22, text = "Si gen yon bagay m' ka di: inonsan ou koupab, se menm bagay. Bondye ap toujou detwi nou.", bookId = 18),
        Verse(book = "Jòb", chapter = 9, verseNumber = 23, text = "Si yon malè konmanse ap simen lanmò, inonsan te mèt ap rele, Bondye ri sa.", bookId = 18),
        Verse(book = "Jòb", chapter = 9, verseNumber = 24, text = "Lè yon peyi tonbe anba men moun ki mechan, Bondye bouche je tout jij yo. Si se pa li ki fè sa, ki moun ki pou fè l'?", bookId = 18),
        Verse(book = "Jòb", chapter = 9, verseNumber = 25, text = "Jou yo pase pou mwen pi vit pase dlo larivyè. Pa gen yonn ki ban m' kè kontan.", bookId = 18),
        Verse(book = "Jòb", chapter = 9, verseNumber = 26, text = "Yo kouri tankou bwa fouye sou larivyè, tankou malfini k'ap plonje sou ti poul.", bookId = 18),
        Verse(book = "Jòb", chapter = 9, verseNumber = 27, text = "Si mwen di: Bon. M' p'ap plenyen ankò. M'ap chanje figi m', m'ap fè yon ti ri,", bookId = 18),
        Verse(book = "Jòb", chapter = 9, verseNumber = 28, text = "soufrans yo vin pi rèd sou mwen. Mwen pè, paske mwen konnen pou Bondye mwen pa inonsan.", bookId = 18),
        Verse(book = "Jòb", chapter = 9, verseNumber = 29, text = "Si m' antò, sa m' bezwen bat kò m' pou gremesi fè?", bookId = 18),
        Verse(book = "Jòb", chapter = 9, verseNumber = 30, text = "Pa gen dlo ki ka lave m'. Pa gen savon ki ka blanchi m'.", bookId = 18),
        Verse(book = "Jòb", chapter = 9, verseNumber = 31, text = "Bondye voye m' jete nan yon pil fatra. Ata rad m' pa ka mete sou mwen.", bookId = 18),
        Verse(book = "Jòb", chapter = 9, verseNumber = 32, text = "Men, Bondye pa yon moun tankou m'. M' pa ka diskite avè l'. Nou pa ka al lajistis.", bookId = 18),
        Verse(book = "Jòb", chapter = 9, verseNumber = 33, text = "Pa gen moun ki ka mete ola nan koze a. Pa gen moun ki ka jije m' ansanm avè l'.", bookId = 18),
        Verse(book = "Jòb", chapter = 9, verseNumber = 34, text = "Pa gen moun ki ka kenbe men l' pou li sispann fè m' pè.", bookId = 18),
        Verse(book = "Jòb", chapter = 9, verseNumber = 35, text = "Men, mwen pa pè l'. M'ap pale, paske se mwen ki konnen sa ki nan kè m'.", bookId = 18),
        Verse(book = "Jòb", chapter = 10, verseNumber = 1, text = "M' degoute ak lavi a. M' pa ka kenbe ankò. Kite m' plenn sò mwen! Kite m' di tout lapenn ki nan kè mwen!", bookId = 18),
        Verse(book = "Jòb", chapter = 10, verseNumber = 2, text = "M'a di Bondye: Tanpri, pa kondannen m'. Fè m' konnen poukisa ou leve dèyè m' konsa.", bookId = 18),
        Verse(book = "Jòb", chapter = 10, verseNumber = 3, text = "Eske ou gen rezon pou ou fè m' tou sa w'ap fè m' lan, pou ou meprize sa ou fè ak men ou, pou ou ri lè mechan yo ap fè konfyolo yo?", bookId = 18),
        Verse(book = "Jòb", chapter = 10, verseNumber = 4, text = "Eske ou wè sa k'ap fèt sou latè tankou nou menm moun nou wè l' la?", bookId = 18),
        Verse(book = "Jòb", chapter = 10, verseNumber = 5, text = "Lavi ou pa tankou lavi pa nou. Nou gen pou nou mouri, ou menm w'ap toujou la.", bookId = 18),
        Verse(book = "Jòb", chapter = 10, verseNumber = 6, text = "W'ap chache dènye ti peche moun fè. Ou dèyè pou ou konnen tou sa mwen fè ki mal.", bookId = 18),
        Verse(book = "Jòb", chapter = 10, verseNumber = 7, text = "Ou konnen m' pa antò. Pa gen moun ki ka sove m' anba men ou!", bookId = 18),
        Verse(book = "Jòb", chapter = 10, verseNumber = 8, text = "Se ak men ou ou te fè m'. Se avè l' ou te ban m' fòm mwen. Epi se ak menm men sa yo ou vle detwi m' ankò?", bookId = 18),
        Verse(book = "Jòb", chapter = 10, verseNumber = 9, text = "Chonje se ou menm ki fè m' ak labou tè wouj. Koulye a, ou pral kraze m' fè m' tounen pousyè?", bookId = 18),
        Verse(book = "Jòb", chapter = 10, verseNumber = 10, text = "Se ou menm ki bay papa m' fòs pou li fè m'. Ou fè m' devlope nan vant manman mwen.", bookId = 18),
        Verse(book = "Jòb", chapter = 10, verseNumber = 11, text = "Ou fè tout zo ak tout venn nan kò m'. Ou kouvri yo ak vyann epi ak po.", bookId = 18),
        Verse(book = "Jòb", chapter = 10, verseNumber = 12, text = "Lèfini, ou fè m' kado lavi. Ou veye avèk prekosyon pou m' pa mouri.", bookId = 18),
        Verse(book = "Jòb", chapter = 10, verseNumber = 13, text = "Men, ou te gen yon lòt lide dèyè tèt ou. Koulye a, mwen konnen ou te pare yon lòt bagay pou mwen.", bookId = 18),
        Verse(book = "Jòb", chapter = 10, verseNumber = 14, text = "Ou t'ap veye m' pou wè si m' t'ap fè sa m' pa t' dwe fè. Ou pa t'ap kite anyen pase pou mwen.", bookId = 18),
        Verse(book = "Jòb", chapter = 10, verseNumber = 15, text = "Si m' antò, zafè m' pa bon! Mwen te mèt inonsan, m' pa ka leve tèt devan ou. Mwen wont, se yon pòv malere mwen ye devan ou.", bookId = 18),
        Verse(book = "Jòb", chapter = 10, verseNumber = 16, text = "Si m' leve tèt mwen, ou fann dèyè m' tankou yon lyon dèyè bèt pou l' manje. Ou rive fè mirak pou ou ka fè m' lapenn.", bookId = 18),
        Verse(book = "Jòb", chapter = 10, verseNumber = 17, text = "Ou toujou pare pou fè yon atak sou mwen. Chak jou w'ap vin pi ankòlè. Se san pran souf w'ap voye lafliksyon sou mwen yonn apre lòt.", bookId = 18),
        Verse(book = "Jòb", chapter = 10, verseNumber = 18, text = "Bondye, poukisa ou te kite m' soti nan vant manman m'? Mwen ta mouri anvan pesonn ta wè m'.", bookId = 18),
        Verse(book = "Jòb", chapter = 10, verseNumber = 19, text = "Soti nan vant, ale nan simityè, se tankou si m' pa t' janm fèt.", bookId = 18),
        Verse(book = "Jòb", chapter = 10, verseNumber = 20, text = "Mwen pa rete lontan pou m' viv ankò. Kite m' pou kont mwen! Ban m' yon ti kanpo. Kite m' jwi de twa jou ki rete m' yo non!", bookId = 18),
        Verse(book = "Jòb", chapter = 10, verseNumber = 21, text = "Talè konsa mwen prale pou m' pa janm tounen. Mwen prale nan peyi kote ki fè nwa a, kote moun pè a,", bookId = 18),
        Verse(book = "Jòb", chapter = 10, verseNumber = 22, text = "nan peyi kote se fènwa ak dezòd ase ki gen toutan, kote menm gwo lajounen fè nwa tankou lannwit!", bookId = 18),
        Verse(book = "Jòb", chapter = 11, verseNumber = 1, text = "Lè sa a, Sofa, moun Naama a, pran lapawòl, li di konsa:", bookId = 18),
        Verse(book = "Jòb", chapter = 11, verseNumber = 2, text = "-Atò pesonn p'ap reponn gwo paladò sa a? Pale anpil pa ka bay moun rezon.", bookId = 18),
        Verse(book = "Jòb", chapter = 11, verseNumber = 3, text = "Pa konprann pale anpil ou a ka enpoze moun louvri bouch yo reponn ou. Paske w'ap pase moun nan betiz la, atò yo pa ka fè ou wont?", bookId = 18),
        Verse(book = "Jòb", chapter = 11, verseNumber = 4, text = "Ou pretann sa ou di a se verite. Pou ou, ou san repwòch devan Bondye!", bookId = 18),
        Verse(book = "Jòb", chapter = 11, verseNumber = 5, text = "Pa pito Bondye ta pale pou l' reponn ou!", bookId = 18),
        Verse(book = "Jòb", chapter = 11, verseNumber = 6, text = "Li ta fè ou wè gen anpil lòt bagay ou poko konnen, bagay moun pa ka konprann. Lè sa a, ou ta wè Bondye pa fè ou peye pou tou sa ou fè.", bookId = 18),
        Verse(book = "Jòb", chapter = 11, verseNumber = 7, text = "Ou konprann ou ka konnen sa ki nan kè Bondye, ou ka konnen tout bagay nèt sou Bondye ki gen tout pouvwa a?", bookId = 18),
        Verse(book = "Jòb", chapter = 11, verseNumber = 8, text = "Li pi wo pase syèl la. Sa ou ka fè pou sa? Li pi fon pase peyi kote mò yo ye a. Sa ou ka konnen la?", bookId = 18),
        Verse(book = "Jòb", chapter = 11, verseNumber = 9, text = "Li pi long pase longè tout tè a. Li pi laj pase lanmè a.", bookId = 18),
        Verse(book = "Jòb", chapter = 11, verseNumber = 10, text = "Si Bondye arete ou, li mete ou nan prizon, li trennen ou nan tribinal, ki moun ki ka di l' non?", bookId = 18),
        Verse(book = "Jòb", chapter = 11, verseNumber = 11, text = "Bondye konnen tout moun k'ap bay manti. Je l' byen louvri, li wè tout mechanste moun ap fè.", bookId = 18),
        Verse(book = "Jòb", chapter = 11, verseNumber = 12, text = "Konsa, moun fou va konmanse gen konprann. Bourik sovaj yo va donte.", bookId = 18),
        Verse(book = "Jòb", chapter = 11, verseNumber = 13, text = "Annou wè, monchè! Pran tèt ou! Louvri bra ou devan Bondye.", bookId = 18),
        Verse(book = "Jòb", chapter = 11, verseNumber = 14, text = "Sispann fè vye bagay k'ap sal men ou yo. Pa kite mechanste chita lakay ou.", bookId = 18),
        Verse(book = "Jòb", chapter = 11, verseNumber = 15, text = "Lè sa a, w'a leve tèt ou pou gade moun nan je. W'a byen fèm, ou p'ap pè anyen.", bookId = 18),
        Verse(book = "Jòb", chapter = 11, verseNumber = 16, text = "W'a bliye lapenn ou yo. Tankou yon inondasyon ki fin pase, ou p'ap chonje yo ankò.", bookId = 18),
        Verse(book = "Jòb", chapter = 11, verseNumber = 17, text = "Lavi ou pral klere pi bèl pase gwo solèy midi. Move pa yo pral tankou yon douvan jou.", bookId = 18),
        Verse(book = "Jòb", chapter = 11, verseNumber = 18, text = "Ou pral viv san kè sote. Ou p'ap dekouraje. Bondye va pwoteje ou, l'a ba ou kè poze.", bookId = 18),
        Verse(book = "Jòb", chapter = 11, verseNumber = 19, text = "Lè w'ap dòmi, pesonn p'ap deranje ou. Anpil moun va vin achte figi ou.", bookId = 18),
        Verse(book = "Jòb", chapter = 11, verseNumber = 20, text = "Men, mechan yo ap voye je yo bouske toupatou, yo p'ap jwenn kote pou yo chape kò yo. Sèl espwa yo, se lanmò y'ap tann.", bookId = 18),
        Verse(book = "Jòb", chapter = 12, verseNumber = 1, text = "Jòb pran lapawòl, li di:", bookId = 18),
        Verse(book = "Jòb", chapter = 12, verseNumber = 2, text = "-Apa nou k'ap pale pou pèp la! Mouri nou mouri, bon konprann kaba!", bookId = 18),
        Verse(book = "Jòb", chapter = 12, verseNumber = 3, text = "Men, mwen menm tou, mwen gen lespri menm jan avè nou. Mwen pa pi mal pase nou. Sa nou sot di la a, tout moun konnen l'.", bookId = 18),
        Verse(book = "Jòb", chapter = 12, verseNumber = 4, text = "Koulye a, menm zanmi m' ap pase m' nan rizib. Y'ap ri m', mwen menm yon moun Bondye pa gen anyen pou l' repwoche, yon moun Bondye te konn reponn lè m' rele l'.", bookId = 18),
        Verse(book = "Jòb", chapter = 12, verseNumber = 5, text = "Se konsa, moun ki pa nan pwoblèm meprize moun ki nan lafliksyon. Yo wè yon moun k'ap tonbe, yo ba l' bourad fè l' tonbe pi vit.", bookId = 18),
        Verse(book = "Jòb", chapter = 12, verseNumber = 6, text = "Piyajè yo byen trankil lakay yo. Moun k'ap fè Bondye fache yo ap viv alèz. Bondye yo se fòs ponyèt yo.", bookId = 18),
        Verse(book = "Jòb", chapter = 12, verseNumber = 7, text = "Manyè fè ti koze ak zannimo yo, ak zwezo yo. Yo gen anpil bagay pou yo moutre nou.", bookId = 18),
        Verse(book = "Jòb", chapter = 12, verseNumber = 8, text = "Bèt k'ap trennen sou vant va ban nou leson, pwason nan lanmè va di nou sa yo konnen.", bookId = 18),
        Verse(book = "Jòb", chapter = 12, verseNumber = 9, text = "Pa gen yonn ladan yo ki pa konnen se Bondye ki fè tout bagay ak men li.", bookId = 18),
        Verse(book = "Jòb", chapter = 12, verseNumber = 10, text = "Bondye gen nanm tout sa ki vivan nan men li. Wi, lavi tout moun nan men li.", bookId = 18),
        Verse(book = "Jòb", chapter = 12, verseNumber = 11, text = "Bèl pawòl fè plezi zòrèy menm jan bon manje gou nan bouch.", bookId = 18),
        Verse(book = "Jòb", chapter = 12, verseNumber = 12, text = "Yo di se vye granmoun ki gen konesans, se laj ki bay bon konprann.", bookId = 18),
        Verse(book = "Jòb", chapter = 12, verseNumber = 13, text = "Men, Bondye gen konesans, lèfini li gen pouvwa. Li gen bon konprann, lèfini li fè sa li vle.", bookId = 18),
        Verse(book = "Jòb", chapter = 12, verseNumber = 14, text = "Lè Bondye kraze yon bagay, pesonn pa ka refè l'. Lè li mete yon moun nan prizon, pesonn pa ka lage l'.", bookId = 18),
        Verse(book = "Jòb", chapter = 12, verseNumber = 15, text = "Lè li pa bay lapli, sèk tonbe sou latè. Lè li bay lapli, dlo fè dega toupatou.", bookId = 18),
        Verse(book = "Jòb", chapter = 12, verseNumber = 16, text = "Bondye gen fòs, li konn sa l'ap fè. Ni moun k'ap bay manti, ni moun k'ap pran manti, se anba ponyèt li yo ye.", bookId = 18),
        Verse(book = "Jòb", chapter = 12, verseNumber = 17, text = "Li fè moun k'ap bay konsèy yo pèdi tèt yo. Li fè chèf yo aji tankou moun fou.", bookId = 18),
        Verse(book = "Jòb", chapter = 12, verseNumber = 18, text = "Li wete tout pouvwa nan men wa yo. Li mare yon tanga nan ren yo jete yo nan prizon.", bookId = 18),
        Verse(book = "Jòb", chapter = 12, verseNumber = 19, text = "Li fè prèt yo mache pye atè. Li mete gwo zotobre atè!", bookId = 18),
        Verse(book = "Jòb", chapter = 12, verseNumber = 20, text = "Li fèmen bouch moun k'ap bay bon konsèy. Li fè granmoun yo depale.", bookId = 18),
        Verse(book = "Jòb", chapter = 12, verseNumber = 21, text = "Li fè pase grannèg yo nan betiz. Li wete pouvwa gwo chèf yo nan men yo.", bookId = 18),
        Verse(book = "Jòb", chapter = 12, verseNumber = 22, text = "Li klere twou fon kote ki fè nwa a, li mete twou lanmò a aklè.", bookId = 18),
        Verse(book = "Jòb", chapter = 12, verseNumber = 23, text = "Li fè nasyon yo fè pwogrè, lèfini, li fè yo deperi. Li fè yon pèp pran elan, lèfini, li fè l' disparèt.", bookId = 18),
        Verse(book = "Jòb", chapter = 12, verseNumber = 24, text = "Li fè chèf pèp yo pèdi tèt yo, li fè yo moute desann nan dezè, san yo pa konn kote yo prale.", bookId = 18),
        Verse(book = "Jòb", chapter = 12, verseNumber = 25, text = "Y'ap tatonnen nan fènwa, y'ap titibe tankou moun sou.", bookId = 18),
        Verse(book = "Jòb", chapter = 13, verseNumber = 1, text = "Wi, mwen wè tou sa ak de je m'. Mwen tande tou sa ak de zòrèy mwen epi mwen konprann.", bookId = 18),
        Verse(book = "Jòb", chapter = 13, verseNumber = 2, text = "Sa nou konnen an, mwen konnen l' tou. M' pa pi sòt pase nou.", bookId = 18),
        Verse(book = "Jòb", chapter = 13, verseNumber = 3, text = "Men, mwen menm, se ak Bondye ki gen tout pouvwa m' annafè. Se avè l' mwen vle pale pou m' defann kòz mwen.", bookId = 18),
        Verse(book = "Jòb", chapter = 13, verseNumber = 4, text = "Nou menm, kote nou pa konnen nou bay manti. Nou tankou dòktè ki pa janm geri pyès moun.", bookId = 18),
        Verse(book = "Jòb", chapter = 13, verseNumber = 5, text = "Pito nou pe bouch nou! Lè sa a, n'a pase pou moun ki gen bon konprann.", bookId = 18),
        Verse(book = "Jòb", chapter = 13, verseNumber = 6, text = "Koute sa mwen gen sou kè m'. Louvri zòrèy nou pou n' tande jan m' pral plede kòz mwen.", bookId = 18),
        Verse(book = "Jòb", chapter = 13, verseNumber = 7, text = "Se defann nou vle defann Bondye kifè n'ap bay tout manti sa yo, kifè n'ap pale kwochi konsa?", bookId = 18),
        Verse(book = "Jòb", chapter = 13, verseNumber = 8, text = "Se pou li n'ap pran? Se kòz li nou ranmase?", bookId = 18),
        Verse(book = "Jòb", chapter = 13, verseNumber = 9, text = "Pou li, li ta bon pou nou si li t'ap chache konnen sa nou gen nan fon kè nou! Pa konprann nou ka woule Bondye tankou nou woule moun!", bookId = 18),
        Verse(book = "Jòb", chapter = 13, verseNumber = 10, text = "Li ta regle nou byen regle, paske li ta tou wè se figi l' n'ap achte anba chal.", bookId = 18),
        Verse(book = "Jòb", chapter = 13, verseNumber = 11, text = "Nou pa pè gwo pouvwa Bondye a? Nou pa pè li kraze nou?", bookId = 18),
        Verse(book = "Jòb", chapter = 13, verseNumber = 12, text = "Bèl pawòl nou yo pa gen plis valè pase pousyè tè. Repons n'ap ban mwen yo pa kenbe, yo tankou miray sab.", bookId = 18),
        Verse(book = "Jòb", chapter = 13, verseNumber = 13, text = "Koulye a, pe bouch nou! Ban m' yon chans pou m' pale. Sa ki pou rive a te mèt rive!", bookId = 18),
        Verse(book = "Jòb", chapter = 13, verseNumber = 14, text = "Mwen mèt mouri! Zafè! M' mare ren m', m' sere dan m'!", bookId = 18),
        Verse(book = "Jòb", chapter = 13, verseNumber = 15, text = "Bondye te mèt touye m'. Sèl chans mwen se pou m' esplike avè l'.", bookId = 18),
        Verse(book = "Jòb", chapter = 13, verseNumber = 16, text = "Nou pa janm konnen, se sa ki ka sove m', paske moun ki fè mal pa ka parèt devan Bondye.", bookId = 18),
        Verse(book = "Jòb", chapter = 13, verseNumber = 17, text = "Koute byen sa m' pral di la a. Louvri zòrèy nou pou n' tande deklarasyon mwen.", bookId = 18),
        Verse(book = "Jòb", chapter = 13, verseNumber = 18, text = "M' pare pou m' defann kòz mwen, paske mwen konnen mwen nan dwa m'.", bookId = 18),
        Verse(book = "Jòb", chapter = 13, verseNumber = 19, text = "Bondye, èske se ou ki pral plede avè m'? M' tou pare pou m' pe bouch mwen, pou m' asepte lanmò m'.", bookId = 18),
        Verse(book = "Jòb", chapter = 13, verseNumber = 20, text = "De sèl ti chans ase m'ap mande ou. Apre sa, m' p'ap kache pou ou ankò.", bookId = 18),
        Verse(book = "Jòb", chapter = 13, verseNumber = 21, text = "Sispann leve men ou sou mwen. Sispann fè m' pè tout pè sa a.", bookId = 18),
        Verse(book = "Jòb", chapter = 13, verseNumber = 22, text = "Ou mèt pale anvan, m'a reponn ou. Osinon, kite m' pale anvan, w'a reponn mwen.", bookId = 18),
        Verse(book = "Jòb", chapter = 13, verseNumber = 23, text = "Konbe peche, konbe bagay mal mwen fè? Kisa m' fè mwen pa t' dwe fè? Kisa m' fè ki mal?", bookId = 18),
        Verse(book = "Jòb", chapter = 13, verseNumber = 24, text = "Poukisa w'ap kache pou mwen konsa? Poukisa ou fè tankou si se lènmi ou mwen ye?", bookId = 18),
        Verse(book = "Jòb", chapter = 13, verseNumber = 25, text = "Poukisa w'ap chache fè m' pè? Poukisa ou leve dèyè m' konsa? M' tou fini, m' tankou fèy bwa, tankou pay chèch van ap pote ale.", bookId = 18),
        Verse(book = "Jòb", chapter = 13, verseNumber = 26, text = "W'ap akize m' yon bann bagay k'ap fè m' mal. W'ap fè m' peye tou sa m' te fè lè m' te jenn gason.", bookId = 18),
        Verse(book = "Jòb", chapter = 13, verseNumber = 27, text = "Ou mete pye m' nan sèp. Ou veye tout vire tounen m'. Ou gade tout kote m'ap mete pye m'.", bookId = 18),
        Verse(book = "Jòb", chapter = 13, verseNumber = 28, text = "M'ap dekale tankou bwa pouri, tankou rad sizo ap manje.", bookId = 18),
        Verse(book = "Jòb", chapter = 14, verseNumber = 1, text = "Nou menm moun, se nan vant fanm nou soti. Lavi nou kout, men li pa manke traka!", bookId = 18),
        Verse(book = "Jòb", chapter = 14, verseNumber = 2, text = "Nou parèt tankou yon flè. Epi lamenm nou fennen. Nou disparèt tankou yon nwaj k'ap pase.", bookId = 18),
        Verse(book = "Jòb", chapter = 14, verseNumber = 3, text = "Epi, Bondye, se sa w'ap louvri je ou gade. Se sa w'ap fè kanpe devan ou pou jije l'?", bookId = 18),
        Verse(book = "Jòb", chapter = 14, verseNumber = 4, text = "Ki moun ki ka fè dlo pwòp soti nan yon sous sal? Pesonn moun.", bookId = 18),
        Verse(book = "Jòb", chapter = 14, verseNumber = 5, text = "Tan chak moun gen pou l' viv la fikse deja depi lontan. Kantite mwa li gen pou l' viv la, se nan men ou sa rete. Anyen pa ka chanje.", bookId = 18),
        Verse(book = "Jòb", chapter = 14, verseNumber = 6, text = "Tanpri, wete je ou sou mwen. Kite m' pran yon ti souf. Tankou moun ki fin pase yon jounen ap travay di, kite m' pran yon ti kanpo.", bookId = 18),
        Verse(book = "Jòb", chapter = 14, verseNumber = 7, text = "Toujou gen yon ti espwa pou yon pyebwa. Yo te mèt koupe l', l'ap toujou pouse ankò, li p'ap mouri.", bookId = 18),
        Verse(book = "Jòb", chapter = 14, verseNumber = 8, text = "Rasin li yo te mèt fin vye nan tè a, bout chouk la te mèt fin chèch,", bookId = 18),
        Verse(book = "Jòb", chapter = 14, verseNumber = 9, text = "depi li jwenn dlo, l'ap boujonnen, l'ap pouse kreyòl.", bookId = 18),
        Verse(book = "Jòb", chapter = 14, verseNumber = 10, text = "Men moun, depi yo mouri, yo tounen kadav. Lè yo kase kòd, ou pa wè kote yo fè.", bookId = 18),
        Verse(book = "Jòb", chapter = 14, verseNumber = 11, text = "Letan ka cheche, larivyè ka sispann koule.", bookId = 18),
        Verse(book = "Jòb", chapter = 14, verseNumber = 12, text = "Men, kote yon moun mouri kouche a, pa gen leve pou li ankò. Poul va fè dan anvan y'a leve vivan ankò, anvan y'a leve soti nan dòmi yo a.", bookId = 18),
        Verse(book = "Jòb", chapter = 14, verseNumber = 13, text = "Si sèlman ou ta vle kache m' nan peyi kote mò yo ye a? Si ou te ka kite m' la jouk kòlè ou la fin pase? Apre sa, ou ta fikse yon dat pou chonje m' ankò.", bookId = 18),
        Verse(book = "Jòb", chapter = 14, verseNumber = 14, text = "Men, sa m'ap di la a? Eske moun mouri ka leve? Sa pa fè anyen. Mwen ta tann move tan sa a fin pase, jouk sa ta bon pou mwen ankò.", bookId = 18),
        Verse(book = "Jòb", chapter = 14, verseNumber = 15, text = "Lè sa a, ou ta rele m', mwen ta reponn ou. Ou ta kontan wè sa ou te fè ak men ou lan.", bookId = 18),
        Verse(book = "Jòb", chapter = 14, verseNumber = 16, text = "Lè sa a, ou ta gade jan m'ap mache a, men, ou pa ta chonje sa m' te konn fè ki mal.", bookId = 18),
        Verse(book = "Jòb", chapter = 14, verseNumber = 17, text = "Ou ta padonnen m' peche m' yo, ou ta mare yo tout fè yon pakèt voye jete.", bookId = 18),
        Verse(book = "Jòb", chapter = 14, verseNumber = 18, text = "Rive yon lè se pou mòn yo anfale, se pou wòch yo woule desann.", bookId = 18),
        Verse(book = "Jòb", chapter = 14, verseNumber = 19, text = "Rive yon lè dlo ap fin manje wòch yo, lapli ap fin bwote tout tè a desann. Konsa tou, rive yon lè ou wete tout espwa nan kè moun.", bookId = 18),
        Verse(book = "Jòb", chapter = 14, verseNumber = 20, text = "Ou kraze yo nèt anba men ou, epi yo mouri. Ou fè moun pa ka rekonèt yo, epi ou voye yo ale.", bookId = 18),
        Verse(book = "Jòb", chapter = 14, verseNumber = 21, text = "Moun fè lwanj pitit mò yo, men mò yo menm yo pa konn anyen. Moun pase yo nan betiz, men yo menm, sa pa di yo anyen.", bookId = 18),
        Verse(book = "Jòb", chapter = 14, verseNumber = 22, text = "Yon sèl soufrans yo santi se sa k'ap manje yo nan tout kò yo a. Se pou tèt pa yo ase y'ap plenyen!", bookId = 18),
        Verse(book = "Jòb", chapter = 15, verseNumber = 1, text = "Fwa sa a, Elifaz, moun lavil Teman an, pran lapawòl ankò, li di konsa:", bookId = 18),
        Verse(book = "Jòb", chapter = 15, verseNumber = 2, text = "-Lè yon moun gen bon konprann, se pa avèk pawòl anlè pou li reponn. Li p'ap chita ap fè jazè.", bookId = 18),
        Verse(book = "Jòb", chapter = 15, verseNumber = 3, text = "Li p'ap rete ap defann tèt li ak mo ki pa vle di anyen, ak bèl diskou ki pa sèvi anyen.", bookId = 18),
        Verse(book = "Jòb", chapter = 15, verseNumber = 4, text = "Ou menm menm, ou al pi lwen. Dapre sa ou di la a, moun pa bezwen gen krentif pou Bondye ankò. Pa gen nesesite pou moun lapriyè Bondye.", bookId = 18),
        Verse(book = "Jòb", chapter = 15, verseNumber = 5, text = "Jan ou pale a, yo wè ou se yon moun ki mechan nan fon kè ou. Ou pale tankou moun k'ap kache yon bagay.", bookId = 18),
        Verse(book = "Jòb", chapter = 15, verseNumber = 6, text = "Se bouch ou menm k'ap kondannen ou. Se pa mwen. Se pawòl nan bouch ou menm k'ap fini avè ou.", bookId = 18),
        Verse(book = "Jòb", chapter = 15, verseNumber = 7, text = "Manyè di m' non: Eske se ou menm premye moun Bondye te fè? Eske ou te fèt anvan tout mòn yo?", bookId = 18),
        Verse(book = "Jòb", chapter = 15, verseNumber = 8, text = "Eske ou te la lè Bondye t'ap fè plan travay li, kifè ou konnen pase tout moun?", bookId = 18),
        Verse(book = "Jòb", chapter = 15, verseNumber = 9, text = "Kisa ou konnen nou menm nou pa konnen? Kisa ou konprann nou menm nou pa ka konprann?", bookId = 18),
        Verse(book = "Jòb", chapter = 15, verseNumber = 10, text = "Se nan bouch granmoun lontan, granmoun cheve blan ki pi gran pase papa ou nou pran tout konesans pa nou.", bookId = 18),
        Verse(book = "Jòb", chapter = 15, verseNumber = 11, text = "Poukisa ou pa asepte ankourajman Bondye voye ba ou a? Poukisa ou pa koute nou? N'ap pale byen dousman avè ou la a.", bookId = 18),
        Verse(book = "Jòb", chapter = 15, verseNumber = 12, text = "Men, gade jan ou move! W'ap louvri je ou sou nou!", bookId = 18),
        Verse(book = "Jòb", chapter = 15, verseNumber = 13, text = "W'ap pase kòlè ou sou Bondye. W'ap plede joure l'.", bookId = 18),
        Verse(book = "Jòb", chapter = 15, verseNumber = 14, text = "Ki jan ou ta vle pou moun san repwòch devan Bondye? Pou moun ki soti nan vant fanm gen rezon devan Bondye?", bookId = 18),
        Verse(book = "Jòb", chapter = 15, verseNumber = 15, text = "Ata zanj li yo, Bondye pa fè yo konfyans. Yo menm tou yo pa fin bon nèt nan je l'.", bookId = 18),
        Verse(book = "Jòb", chapter = 15, verseNumber = 16, text = "Ale wè atò pou moun, ki pèvèti, ki pa vo anyen, ki fè mechanste tankou yo bwè dlo!", bookId = 18),
        Verse(book = "Jòb", chapter = 15, verseNumber = 17, text = "Koulye a, Jòb, koute m'. Kite m' esplike avè ou! Mwen pral di ou sa mwen menm mwen wè.", bookId = 18),
        Verse(book = "Jòb", chapter = 15, verseNumber = 18, text = "Moun ki gen bon konprann moutre m' anpil verite. Yo pa t' kache m' anyen. Yo menm, se nan bouch granmoun lontan yo te pran l'.", bookId = 18),
        Verse(book = "Jòb", chapter = 15, verseNumber = 19, text = "Granmoun sa yo t'ap viv nan peyi Bondye te ba yo pou yo menm ase, san ankenn moun lòt nasyon pa t' mele ak yo.", bookId = 18),
        Verse(book = "Jòb", chapter = 15, verseNumber = 20, text = "Mechan yo pase tout lavi yo nan tèt chaje. Moun k'ap plede maltrete parèy yo p'ap viv lontan.", bookId = 18),
        Verse(book = "Jòb", chapter = 15, verseNumber = 21, text = "Rèl moun k'ap soufri yo ap kònen nan zòrèy yo. Lè zafè yo pi bon, se lè sa a vòlè tonbe sou yo.", bookId = 18),
        Verse(book = "Jòb", chapter = 15, verseNumber = 22, text = "Yo pa gen espwa chape nan fènwa a, paske manchèt pare ap tann yo.", bookId = 18),
        Verse(book = "Jòb", chapter = 15, verseNumber = 23, text = "Y'ap kouri adwat agoch, y'ap chache manje. Yo konnen wè pa wè y'ap pran yo.", bookId = 18),
        Verse(book = "Jòb", chapter = 15, verseNumber = 24, text = "Lanmò fè yo pè. Malè ak lafliksyon ap tonbe sou yo tankou yon wa ki tou pare pou batay.", bookId = 18),
        Verse(book = "Jòb", chapter = 15, verseNumber = 25, text = "Men sa k'ap tann moun k'ap lonje men nan figi Bondye, moun ki pa pè kenbe tèt ak Bondye.", bookId = 18),
        Verse(book = "Jòb", chapter = 15, verseNumber = 26, text = "Yo kache dèyè pwotèj anfe yo epi yo fonse sou Bondye.", bookId = 18),
        Verse(book = "Jòb", chapter = 15, verseNumber = 27, text = "Figi yo gra kou chat. Men gwosè vant yo ak grès!", bookId = 18),
        Verse(book = "Jòb", chapter = 15, verseNumber = 28, text = "Yo rete nan lavil ki fin kraze, nan kay moun kouri kite, kay ki fin tounen mazi.", bookId = 18),
        Verse(book = "Jòb", chapter = 15, verseNumber = 29, text = "Yo p'ap janm rich toutan. Sa yo genyen an la pou yon tan. Menm lonbray yo ap disparèt.", bookId = 18),
        Verse(book = "Jòb", chapter = 15, verseNumber = 30, text = "Yo p'ap ka kouri pou fènwa a. Y'ap tankou yon pyebwa dife boule tout branch li yo epi van bwote tout flè l' yo ale.", bookId = 18),
        Verse(book = "Jòb", chapter = 15, verseNumber = 31, text = "Yo pa bezwen konte sou pozisyon yo. Nou konnen sa p'ap sèvi yo anyen.", bookId = 18),
        Verse(book = "Jòb", chapter = 15, verseNumber = 32, text = "Anvan yo donnen, branch yo ap fennen. boujon yo p'ap pouse fèy ankò.", bookId = 18),
        Verse(book = "Jòb", chapter = 15, verseNumber = 33, text = "Y'ap tankou yon pye rezen ki pèdi tout grap rezen vèt yo, tankou yon pye oliv ki pèdi tout flè l'.", bookId = 18),
        Verse(book = "Jòb", chapter = 15, verseNumber = 34, text = "Wi, mechan yo p'ap gen pitit. Dife ap boule tout kay yo bati ak lajan yo volè.", bookId = 18),
        Verse(book = "Jòb", chapter = 15, verseNumber = 35, text = "Lè yon moun ap chache fè moun mal, se sou li malè a tonbe. Se pwòp tèt li l'ap twonpe.", bookId = 18),
        Verse(book = "Jòb", chapter = 16, verseNumber = 1, text = "Jòb pran lapawòl ankò, li di konsa:", bookId = 18),
        Verse(book = "Jòb", chapter = 16, verseNumber = 2, text = "-Mwen bouke tande pawòl sa yo! Pase nou konsole moun, se plis lapenn n'ap ba yo.", bookId = 18),
        Verse(book = "Jòb", chapter = 16, verseNumber = 3, text = "Kilè n'a sispann tout pale anpil sa a? Sa k'ap pouse nou konsa? Nou toujou pare pou reponn moun!", bookId = 18),
        Verse(book = "Jòb", chapter = 16, verseNumber = 4, text = "Si m' te nan plas nou, epi nou menm nan plas mwen, m' ta ka pale jan nou pale a tou, m' ta pase nou nan yon wonn tenten, m' ta vide bèl diskou sou nou.", bookId = 18),
        Verse(book = "Jòb", chapter = 16, verseNumber = 5, text = "M' ta remoute kouraj nou ak konsèy, m' ta pale ak nou jouk nou ta soulaje.", bookId = 18),
        Verse(book = "Jòb", chapter = 16, verseNumber = 6, text = "Men, lè mwen pale, doulè a la pi rèd pou mwen. Lè mwen pa pale, se pa sa k'ap fè l' ban m' yon ti louga.", bookId = 18),
        Verse(book = "Jòb", chapter = 16, verseNumber = 7, text = "Koulye a, Bondye, se fini ou fini avè m'. Ou kite yo touye tout fanmi m'.", bookId = 18),
        Verse(book = "Jòb", chapter = 16, verseNumber = 8, text = "Ou mete men sou mwen, ou pa vle wè m' ankò. Mwen tounen zo ak po. Yo di se paske mwen antò ki fè sa rive m'.", bookId = 18),
        Verse(book = "Jòb", chapter = 16, verseNumber = 9, text = "Nan kòlè li, Bondye ap dechire m' moso pa moso. L'ap devore m' anba dan l'. L'ap louvri je l' sou mwen, li pa vle wè m'!", bookId = 18),
        Verse(book = "Jòb", chapter = 16, verseNumber = 10, text = "Moun prèt pou manje m'. Yo kouri sou mwen, y'ap joure m', y'ap touye m' anba souflèt.", bookId = 18),
        Verse(book = "Jòb", chapter = 16, verseNumber = 11, text = "Bondye lage m' nan men mechan yo. Li jete m' anba grif san manman yo.", bookId = 18),
        Verse(book = "Jòb", chapter = 16, verseNumber = 12, text = "Mwen t'ap viv tou dousman, li bouskile m'. Li pran m' dèyè nwa kou, li kraze m', li fè m' tounen jwèt li.", bookId = 18),
        Verse(book = "Jòb", chapter = 16, verseNumber = 13, text = "L'ap voye flèch li sou mwen kote m' vire. Li pèse tout kò m', li san pitye pou mwen, li mete san m' deyò.", bookId = 18),
        Verse(book = "Jòb", chapter = 16, verseNumber = 14, text = "Kote m' vire li blese m', li vare sou mwen tankou yon sòlda nan lagè.", bookId = 18),
        Verse(book = "Jòb", chapter = 16, verseNumber = 15, text = "Mwen fè rad sak mete sou mwen, mwen woule kò m' nan pousyè tèlman mwen te nan lapenn.", bookId = 18),
        Verse(book = "Jòb", chapter = 16, verseNumber = 16, text = "Je m' vin wouj afòs mwen kriye. Tout anba je m' gonfle vin tou nwa.", bookId = 18),
        Verse(book = "Jòb", chapter = 16, verseNumber = 17, text = "Men, mwen konnen mwen pa fè ankenn moun mechanste. Mwen lapriyè Bondye ak tout kè m'.", bookId = 18),
        Verse(book = "Jòb", chapter = 16, verseNumber = 18, text = "Ou menm latè, pa kache mizè mwen. Pa kite yo fèmen bouch mwen lè m'ap rele nan pye Bondye!", bookId = 18),
        Verse(book = "Jòb", chapter = 16, verseNumber = 19, text = "Paske mwen konnen gen yon moun nan syèl la k'ap kanpe pou mwen, gen yon moun anwo a k'ap pran defans mwen.", bookId = 18),
        Verse(book = "Jòb", chapter = 16, verseNumber = 20, text = "Zanmi m' yo ap pase m' nan betiz, men, m'ap kriye nan pye Bondye.", bookId = 18),
        Verse(book = "Jòb", chapter = 16, verseNumber = 21, text = "Mwen bezwen moun pou plede kòz mwen ak Bondye a, menm jan yon moun plede kòz zanmi l'.", bookId = 18),
        Verse(book = "Jòb", chapter = 16, verseNumber = 22, text = "M' pa lontan mouri. Mwen pral pran chemen kote moun pa janm tounen an.", bookId = 18),
        Verse(book = "Jòb", chapter = 17, verseNumber = 1, text = "Souf mwen prèt pou koupe. Mwen pa lwen mouri. Se pou simityè ase mwen bon.", bookId = 18),
        Verse(book = "Jòb", chapter = 17, verseNumber = 2, text = "Kote m' vire, se moun k'ap pase m' nan betiz. Vye pawòl jouman yo enpoze m' dòmi.", bookId = 18),
        Verse(book = "Jòb", chapter = 17, verseNumber = 3, text = "Ou mèt kwè m', Bondye! Se ou menm ankò ki pou bay garanti pou mwen. M' pa gen pesonn lòt ki ka tope ak yo.", bookId = 18),
        Verse(book = "Jòb", chapter = 17, verseNumber = 4, text = "Ou fèmen lespri yo pou yo pa konprann. Pa kite yo gen rezon sou mwen.", bookId = 18),
        Verse(book = "Jòb", chapter = 17, verseNumber = 5, text = "Pawòl la di: Yon moun ap fè gwo fèt pou zanmi l', epi pitit li yo ap mouri grangou anndan lakay li.", bookId = 18),
        Verse(book = "Jòb", chapter = 17, verseNumber = 6, text = "Yo fè koze sou mwen nan pèp la. Yo vin krache nan figi m'!", bookId = 18),
        Verse(book = "Jòb", chapter = 17, verseNumber = 7, text = "Mwen sitèlman nan lapenn, m' pa ka louvri je m'. Mwen fin tounen zo ak po. Ata lonbraj mwen pa fè!", bookId = 18),
        Verse(book = "Jòb", chapter = 17, verseNumber = 8, text = "Moun k'ap mache dwat yo sezi lè yo wè sa. Inonsan yo fin debòde sou mechan an ki vire do bay Bondye.", bookId = 18),
        Verse(book = "Jòb", chapter = 17, verseNumber = 9, text = "Moun k'ap mennen yon vi dwat, se yo ki gen rezon. Sa ki pa mete men yo nan ankenn move zafè kanpe pi rèd sou pozisyon yo.", bookId = 18),
        Verse(book = "Jòb", chapter = 17, verseNumber = 10, text = "Nou tout mèt vin kanpe devan m', mwen p'ap jwenn yonn ladan nou ki gen bon konprann.", bookId = 18),
        Verse(book = "Jòb", chapter = 17, verseNumber = 11, text = "Mwen fin viv! Tout plan m' te gen nan tèt mwen kraze. Mwen pa gen ankenn espwa ankò.", bookId = 18),
        Verse(book = "Jòb", chapter = 17, verseNumber = 12, text = "Yo pretann lannwit se lajounen. Lè fènwa, yo di limyè a pa lwen.", bookId = 18),
        Verse(book = "Jòb", chapter = 17, verseNumber = 13, text = "Se lanmò m'ap tann. Se al kouche nan simityè ki sèl espwa m'.", bookId = 18),
        Verse(book = "Jòb", chapter = 17, verseNumber = 14, text = "Mwen di tonm lan ou se papa m'. Mwen di vèmen ki pral manje m' yo: nou se manman m' ak sè m'.", bookId = 18),
        Verse(book = "Jòb", chapter = 17, verseNumber = 15, text = "Kote ki gen espwa pou mwen ankò? Ki moun ki wè yon bon lavi pou mwen ankò?", bookId = 18),
        Verse(book = "Jòb", chapter = 17, verseNumber = 16, text = "Lè m'a mouri, lè m'a fin desann nan peyi kote mò yo ye a, èske m'a ka pote espwa m' yo ansanm avè m'?", bookId = 18),
        Verse(book = "Jòb", chapter = 18, verseNumber = 1, text = "Bildad, moun peyi Chwa a, pran lapawòl, li di konsa:", bookId = 18),
        Verse(book = "Jòb", chapter = 18, verseNumber = 2, text = "-Jòb monchè, ou pa ka pe bouch ou yon ti kadè? Si ou te fè yon ti sispann, nou ta pale avè ou!", bookId = 18),
        Verse(book = "Jòb", chapter = 18, verseNumber = 3, text = "Poukisa ou pran nou pou moun san konprann? Poukisa ou pran nou pou zannimo?", bookId = 18),
        Verse(book = "Jòb", chapter = 18, verseNumber = 4, text = "Si ou ankòlè, se pwòp tèt ou ase w'ap fè mal. Atò, poutèt ou, se pou tout moun sou latè te mouri? Se pou Bondye te deplase mòn yo pou fè ou plezi?", bookId = 18),
        Verse(book = "Jòb", chapter = 18, verseNumber = 5, text = "Wi, y'ap touye limyè mechan an, flanm dife l' la p'ap klere ankò.", bookId = 18),
        Verse(book = "Jòb", chapter = 18, verseNumber = 6, text = "Lanp lakay li ap mouri, limyè lakay li ap tenyen.", bookId = 18),
        Verse(book = "Jòb", chapter = 18, verseNumber = 7, text = "Li te konn mache byen enganm, koulye a se ti pa ti pa, l'ap bite. Se plan li t'ap fè yo ki lakòz sa rive l'.", bookId = 18),
        Verse(book = "Jòb", chapter = 18, verseNumber = 8, text = "Li pile yon pèlen, pye l' pran ladan l'.", bookId = 18),
        Verse(book = "Jòb", chapter = 18, verseNumber = 9, text = "Kòd la mare nan je pye l', l'ap sere l' byen sere.", bookId = 18),
        Verse(book = "Jòb", chapter = 18, verseNumber = 10, text = "Yo kache yon chita tann pou li anba tè. Yo moute yon pèlen sou wout li.", bookId = 18),
        Verse(book = "Jòb", chapter = 18, verseNumber = 11, text = "Kote l' vire, malè ap tann li. Kote l' pase, yo la dèyè l'.", bookId = 18),
        Verse(book = "Jòb", chapter = 18, verseNumber = 12, text = "Grangou nan kò l' fini ak kouraj li. Malè kanpe la bò kote l' ap tann li.", bookId = 18),
        Verse(book = "Jòb", chapter = 18, verseNumber = 13, text = "Yon sèl maladi po pete sou tout kò l'. L'ap manje tout janm li ak tout bra li yo. Se tè ki pou geri l'.", bookId = 18),
        Verse(book = "Jòb", chapter = 18, verseNumber = 14, text = "Yo rale l' mete deyò anba tant kote li te al kache a. Yo trennen l' devan jeneral Lanmò.", bookId = 18),
        Verse(book = "Jòb", chapter = 18, verseNumber = 15, text = "Koulye a, nenpòt moun gen dwa pran kay li a pou yo. Y'ap dezenfèkte l' nèt ak souf.", bookId = 18),
        Verse(book = "Jòb", chapter = 18, verseNumber = 16, text = "Anba tè, rasin li yo ap mouri. Anwo tè, branch li yo ap fennen.", bookId = 18),
        Verse(book = "Jòb", chapter = 18, verseNumber = 17, text = "p'ap gen pesonn k'ap chonje l' ankò sou latè. Y'ap bliye l' nèt nan tout peyi a.", bookId = 18),
        Verse(book = "Jòb", chapter = 18, verseNumber = 18, text = "Y'ap pouse l' soti nan limyè ale nan fènwa. Y'ap depòte l' byen lwen nan peyi san chapo.", bookId = 18),
        Verse(book = "Jòb", chapter = 18, verseNumber = 19, text = "Li p'ap kite ni pitit, ni ankenn lòt fanmi nan mitan pèp la. Yo tout ap mouri anvan l'.", bookId = 18),
        Verse(book = "Jòb", chapter = 18, verseNumber = 20, text = "Depi solèy leve jouk solèy kouche, tout moun pral sezi wè jan li fini.", bookId = 18),
        Verse(book = "Jòb", chapter = 18, verseNumber = 21, text = "Wi, men sa k'ap tann lakou moun k'ap fè mechanste yo, fanmi moun ki pa respekte Bondye yo.", bookId = 18),
        Verse(book = "Jòb", chapter = 19, verseNumber = 1, text = "Jòb pran lapawòl, li di konsa:", bookId = 18),
        Verse(book = "Jòb", chapter = 19, verseNumber = 2, text = "-Manyè sispann vire lòlòj mwen non! Manyè sispann kraze kouraj mwen ak tout pawòl sa yo?", bookId = 18),
        Verse(book = "Jòb", chapter = 19, verseNumber = 3, text = "Tout tan n'ap plede joure m', n'ap trennen m' nan labou. Nou pa wont jan n'ap malmennen m' la a?", bookId = 18),
        Verse(book = "Jòb", chapter = 19, verseNumber = 4, text = "Menm si mwen ta fè sa m' pa t' dwe fè, ki jan pou sa ta ka fè nou mal?", bookId = 18),
        Verse(book = "Jòb", chapter = 19, verseNumber = 5, text = "Nou konprann nou pi bon pase m'. Nou di se paske mwen antò kifè m'ap pase tray sa a.", bookId = 18),
        Verse(book = "Jòb", chapter = 19, verseNumber = 6, text = "Nou pa wè se Bondye k'ap manyen avè m'. Se li menm ki pran m' nan pèlen.", bookId = 18),
        Verse(book = "Jòb", chapter = 19, verseNumber = 7, text = "Si m' rele anmwe ansasen, pesonn p'ap reponn. Si m' mande jistis, pesonn p'ap kanpe pou defann mwen.", bookId = 18),
        Verse(book = "Jòb", chapter = 19, verseNumber = 8, text = "Bondye bare tout chemen devan mwen. M' pa ka pase. Li fè m' wè tou nwa devan mwen.", bookId = 18),
        Verse(book = "Jòb", chapter = 19, verseNumber = 9, text = "Li fè yo ban m' move non. Li fè m' pèdi tout byen m'.", bookId = 18),
        Verse(book = "Jòb", chapter = 19, verseNumber = 10, text = "Li minen m' tout jan. M'ap deperi. Li wete tout espwa m'. Mwen tankou yon pyebwa yo derasinen.", bookId = 18),
        Verse(book = "Jòb", chapter = 19, verseNumber = 11, text = "Bondye ankòlè nèt sou mwen. Li konsidere m' tankou yon lènmi.", bookId = 18),
        Verse(book = "Jòb", chapter = 19, verseNumber = 12, text = "Li voye yon bann malè sou mwen yon grenn kou, tankou yon lame k'ap atake m'. Yo rive sou mwen san m' pa wè sa. Yo sènen m' anndan lakay mwen.", bookId = 18),
        Verse(book = "Jòb", chapter = 19, verseNumber = 13, text = "Bondye fè frè m' yo renka kò yo sou mwen. Zanmi m' yo kouri pou mwen.", bookId = 18),
        Verse(book = "Jòb", chapter = 19, verseNumber = 14, text = "Tout fanmi mwen yo, tout bon zanmi m' yo disparèt. Moun mwen te konn resevwa lakay mwen bliye m'.", bookId = 18),
        Verse(book = "Jòb", chapter = 19, verseNumber = 15, text = "Ata sèvant lakay mwen pa rekonèt mwen. Pou yo, yo pa janm konnen m'.", bookId = 18),
        Verse(book = "Jòb", chapter = 19, verseNumber = 16, text = "Si mwen rele yon domestik, li pa reponn mwen. Mwen te mèt lapriyè nan pye l', li pa okipe m'.", bookId = 18),
        Verse(book = "Jòb", chapter = 19, verseNumber = 17, text = "Madanm mwen pa ka pran sant mwen. Ata pwòp pitit mwen yo pè pwoche bò kote m'.", bookId = 18),
        Verse(book = "Jòb", chapter = 19, verseNumber = 18, text = "Tout timoun ap pase m' nan betiz. Si m' fè yon ti kanpe, yo pase m' nan tenten.", bookId = 18),
        Verse(book = "Jòb", chapter = 19, verseNumber = 19, text = "Pi bon zanmi m' yo ap gade m' ak degoutans. Sa m' pi renmen yo ap pale sou do m'.", bookId = 18),
        Verse(book = "Jòb", chapter = 19, verseNumber = 20, text = "Mwen tounen zo ak po. Sa ki rete pou m' mouri a pa anyen.", bookId = 18),
        Verse(book = "Jòb", chapter = 19, verseNumber = 21, text = "Nou se zanmi m'. Pitye pou mwen! Pitye! Se Bondye menm ki leve men sou mwen.", bookId = 18),
        Verse(book = "Jòb", chapter = 19, verseNumber = 22, text = "Poukisa pou nou leve dèyè m' tou menm jan ak Bondye? Koulye a, nou pa pèsekite m' kont nou?", bookId = 18),
        Verse(book = "Jòb", chapter = 19, verseNumber = 23, text = "Si sèlman te gen yon moun pou kouche pawòl mwen yo, pou ekri yo sou papye,", bookId = 18),
        Verse(book = "Jòb", chapter = 19, verseNumber = 24, text = "pou grave yo ak sizo sou wòch plat, pou yo toujou rete make!", bookId = 18),
        Verse(book = "Jòb", chapter = 19, verseNumber = 25, text = "Mwen menm, mwen konnen moun ki gen pou vin pran defans mwen an byen vivan. Se li menm an dènye k'ap kanpe sou latè pou pale pou mwen.", bookId = 18),
        Verse(book = "Jòb", chapter = 19, verseNumber = 26, text = "Apre m' fin mouri, l'ap mete m' kanpe bò kote l'. M'a wè Bondye ak pwòp je m'.", bookId = 18),
        Verse(book = "Jòb", chapter = 19, verseNumber = 27, text = "Se mwen menm menm k'ap wè l'. Se p'ap yon lòt moun! Kè m' ap fann,", bookId = 18),
        Verse(book = "Jòb", chapter = 19, verseNumber = 28, text = "paske n'ap mande ki jan pou n' fè m' pase mizè ankò? Ki rezon n'ap jwenn nan mwen pou nou atake m'?", bookId = 18),
        Verse(book = "Jòb", chapter = 19, verseNumber = 29, text = "Men, atansyon pou se pa sou nou nepe a tonbe, lè Bondye va soti pou pini moun ki antò yo. Lè sa a, n'a konnen gen yon moun k'ap jije tout bon.", bookId = 18),
        Verse(book = "Jòb", chapter = 20, verseNumber = 1, text = "Lè sa a, Sofa, moun lavil Naama a, pran lapawòl, li di konsa:", bookId = 18),
        Verse(book = "Jòb", chapter = 20, verseNumber = 2, text = "-Mwen gen yon bann lide k'ap travay nan tèt mwen. Mwen pa ka tann ankò. Se pou m' reponn ou.", bookId = 18),
        Verse(book = "Jòb", chapter = 20, verseNumber = 3, text = "Tou sa ou di la a vekse m'. Men, mwen konnen jan pou m' reponn ou.", bookId = 18),
        Verse(book = "Jòb", chapter = 20, verseNumber = 4, text = "Ou konnen, depi nan tan lontan, depi premye moun Bondye te mete sou tè a,", bookId = 18),
        Verse(book = "Jòb", chapter = 20, verseNumber = 5, text = "mechan yo pa janm gen kè kontan pou lontan. Plezi moun k'ap fè mal yo se pou yon ti tan.", bookId = 18),
        Verse(book = "Jòb", chapter = 20, verseNumber = 6, text = "Yo te mèt grandi jouk pou yo rive wotè syèl la, jouk pou tèt yo ta rive nan nwaj yo,", bookId = 18),
        Verse(book = "Jòb", chapter = 20, verseNumber = 7, text = "y'ap rete konsa, y'ap disparèt tankou yon pil fatra yo boule. Moun ki te konnen yo va mande kote yo pase.", bookId = 18),
        Verse(book = "Jòb", chapter = 20, verseNumber = 8, text = "Moun bliye yo tankou yon rèv yo fè yo pa ka chonje, tankou yon vizyon yo fè lannwit, yo p'ap janm wè ankò.", bookId = 18),
        Verse(book = "Jòb", chapter = 20, verseNumber = 9, text = "Moun ki te konn wè yo p'ap wè yo ankò. Menm moun lakay yo p'ap konnen kote yo pase.", bookId = 18),
        Verse(book = "Jòb", chapter = 20, verseNumber = 10, text = "Pitit yo va peye pòv yo pou tou sa yo te fè yo. Se pwòp pitit yo ak men yo ki va renmèt pòv yo sa yo te pran pa fòs.", bookId = 18),
        Verse(book = "Jòb", chapter = 20, verseNumber = 11, text = "Mechan yo te gen tout fòs jenn gason yo sou yo toujou. Men koulye a, tou sa pral tounen pousyè ansanm ak yo.", bookId = 18),
        Verse(book = "Jòb", chapter = 20, verseNumber = 12, text = "Lè l' t'ap fè sa ki mal sa te sitèlman gou nan bouch li, li te kenbe ti gout anba lang li.", bookId = 18),
        Verse(book = "Jòb", chapter = 20, verseNumber = 13, text = "Li pa t' kite l' fin twò vit nan bouch li, pou l' te ka jwi gou a pandan lontan.", bookId = 18),
        Verse(book = "Jòb", chapter = 20, verseNumber = 14, text = "Men, rive manje a rive nan lestonmak li, li vin anmè kou fyèl. Anndan vant li pran boule l' tankou si li te vale pwazon.", bookId = 18),
        Verse(book = "Jòb", chapter = 20, verseNumber = 15, text = "Mechan an gen pou l' vonmi tout richès li te vòlò yo, paske Bondye ap foure dwèt nan gòj li.", bookId = 18),
        Verse(book = "Jòb", chapter = 20, verseNumber = 16, text = "Tou sa li te vale tounen pwazon pou li. L'ap mouri tankou si se yon sèpan laspik ki mòde l'.", bookId = 18),
        Verse(book = "Jòb", chapter = 20, verseNumber = 17, text = "Li p'ap viv pou l' wè lwil koule tankou dlo larivyè, ni siwo myèl ak lèt koule tankou lavalas.", bookId = 18),
        Verse(book = "Jòb", chapter = 20, verseNumber = 18, text = "L'ap blije bay tou sa li te travay fè. Li p'ap gen chans jwi richès li yo.", bookId = 18),
        Verse(book = "Jòb", chapter = 20, verseNumber = 19, text = "Paske li te piye kay pòv malere yo, li te pito vòlò kay moun pase pou l' bati.", bookId = 18),
        Verse(book = "Jòb", chapter = 20, verseNumber = 20, text = "Li pa t' janm gen kont li. Men, richès li p'ap ka delivre l'.", bookId = 18),
        Verse(book = "Jòb", chapter = 20, verseNumber = 21, text = "Pesonn pa t' ka chape anba men l' sitèlman li te akrèk. Non. Tout richès li yo pa la pou lontan.", bookId = 18),
        Verse(book = "Jòb", chapter = 20, verseNumber = 22, text = "Atout li gen tout richès sa yo, li pral gen kè sere. Tout kalite mizè pral tonbe sou li.", bookId = 18),
        Verse(book = "Jòb", chapter = 20, verseNumber = 23, text = "Pandan l'ap manje plen vant li, Bondye pral move kont move sou li. Malè pral tonbe dri sou li.", bookId = 18),
        Verse(book = "Jòb", chapter = 20, verseNumber = 24, text = "Lè l'ap chache kouri pou yon nepe fèt an fè, yon flèch an kwiv pral pèse l' pak an pak.", bookId = 18),
        Verse(book = "Jòb", chapter = 20, verseNumber = 25, text = "Yon flèch ap pèse kò l'. San li ap degoute konsa nan pwent flèch la. Kè l' sere, li wè lanmò anfas.", bookId = 18),
        Verse(book = "Jòb", chapter = 20, verseNumber = 26, text = "Li pèdi tou sa li te sere. Yon dife pesonn pa limen ap boule l'. L'ap devore tou sa ki lakay li.", bookId = 18),
        Verse(book = "Jòb", chapter = 20, verseNumber = 27, text = "Syèl la fè konnen tou sa li te fè ki mal. Latè kanpe pou denonse l'.", bookId = 18),
        Verse(book = "Jòb", chapter = 20, verseNumber = 28, text = "Yon sèl dlo desann va pote kay li ale, jou Bondye va fè kolè sa a sou li.", bookId = 18),
        Verse(book = "Jòb", chapter = 20, verseNumber = 29, text = "Wi, se sa Bondye sere pou mechan yo. Se sa mechan yo pral resevwa nan men Bondye.", bookId = 18),
        Verse(book = "Jòb", chapter = 21, verseNumber = 1, text = "Lè sa a, Jòb pran lapawòl ankò, li di konsa:", bookId = 18),
        Verse(book = "Jòb", chapter = 21, verseNumber = 2, text = "-Manyè tande sa m' pral di nou la a, non! Tanpri, charite m' ti ankourajman sa a!", bookId = 18),
        Verse(book = "Jòb", chapter = 21, verseNumber = 3, text = "Ban m' yon ti chans pou m' pale. Lè m'a fini, nou mèt pase m' nan betiz kont nou!", bookId = 18),
        Verse(book = "Jòb", chapter = 21, verseNumber = 4, text = "Se pa avèk yon moun mwen annafè. Mwen gen rezon si m' pa ka tann ankò!", bookId = 18),
        Verse(book = "Jòb", chapter = 21, verseNumber = 5, text = "Voye je nou gade m' byen. N'a sezi. N'a mete men nan bouch.", bookId = 18),
        Verse(book = "Jòb", chapter = 21, verseNumber = 6, text = "Mwen menm, lè m' chonje sa ki rive m', m' pè. Tout kò m' pran tranble.", bookId = 18),
        Verse(book = "Jòb", chapter = 21, verseNumber = 7, text = "Poukisa Bondye kite mechan yo ap viv? Li kite yo rive vye granmoun, epi tout zafè yo mache byen?", bookId = 18),
        Verse(book = "Jòb", chapter = 21, verseNumber = 8, text = "Yo gen pitit ak pitit pitit. Yo wè yo ap grandi devan je yo.", bookId = 18),
        Verse(book = "Jòb", chapter = 21, verseNumber = 9, text = "Bondye pa voye malè sou yo pou pini yo. Y'ap viv alèz lakay yo san ankenn danje.", bookId = 18),
        Verse(book = "Jòb", chapter = 21, verseNumber = 10, text = "Wi, bèf yo kwaze san mank, yo fè pitit san pèdi pòte.", bookId = 18),
        Verse(book = "Jòb", chapter = 21, verseNumber = 11, text = "Timoun yo ap kouri tankou ti mouton nan savann. Y'ap jwe, y'ap sote tankou ti kabrit.", bookId = 18),
        Verse(book = "Jòb", chapter = 21, verseNumber = 12, text = "Y'ap chante, y'ap jwe gita, y'ap bat tanbou, y'ap danse pandan moun ap jwe fif pou yo.", bookId = 18),
        Verse(book = "Jòb", chapter = 21, verseNumber = 13, text = "Jouk jou yo mouri, kè yo kontan. Yo desann nan peyi kote mò yo ye a ak kè poze.", bookId = 18),
        Verse(book = "Jòb", chapter = 21, verseNumber = 14, text = "Se yo menm k'ap plede di Bondye: Kite n' an repo! Nou pa bezwen konnen jan ou vle pou moun viv la.", bookId = 18),
        Verse(book = "Jòb", chapter = 21, verseNumber = 15, text = "Kisa Bondye ki gen tout pouvwa a ye menm pou nou sèvi l' la? Kisa sa ap rapòte nou lè nou lapriyè l'?", bookId = 18),
        Verse(book = "Jòb", chapter = 21, verseNumber = 16, text = "Yo pretann tou sa yo genyen se kouraj yo ki ba yo l'. Yo pa t' janm mete Bondye nan koze yo. Mwen pa dakò ak jan y'ap pale a, non.", bookId = 18),
        Verse(book = "Jòb", chapter = 21, verseNumber = 17, text = "Ou janm wè limyè mechan an mouri? Ou janm tande malè rive yo? On jan wè Bondye fè kolè pou l' pini malveyan yo,", bookId = 18),
        Verse(book = "Jòb", chapter = 21, verseNumber = 18, text = "pou van bwote yo ale tankou zèb chèch, pou van tanpèt chase yo tankou pay pitimi?", bookId = 18),
        Verse(book = "Jòb", chapter = 21, verseNumber = 19, text = "Yo pretann di Bondye va pini pitit pou peche papa yo! Poukisa se pa papa yo menm li pini pou yo ka pran leson?", bookId = 18),
        Verse(book = "Jòb", chapter = 21, verseNumber = 20, text = "Se pou mechan yo te wè chatiman yo. Se yo menm ki te pou santi kòlè Bondye ki gen tout pouvwa a pa dous.", bookId = 18),
        Verse(book = "Jòb", chapter = 21, verseNumber = 21, text = "Ki mele yo sa ki rive pitit yo, lè yo fin ale, lè yo fin viv tan pou yo te viv la?", bookId = 18),
        Verse(book = "Jòb", chapter = 21, verseNumber = 22, text = "Men, Bondye ki jije ata zanj ki nan syèl la, ki moun ki ka moutre l' sa pou li fè?", bookId = 18),
        Verse(book = "Jòb", chapter = 21, verseNumber = 23, text = "Gen moun ki pa janm malad jouk yo mouri. Jouk jou yo antre anba tè, yo kontan, yo pa gen tèt chaje.", bookId = 18),
        Verse(book = "Jòb", chapter = 21, verseNumber = 24, text = "Yo gra nan tout kò yo, tout zo yo plen ak mwèl.", bookId = 18),
        Verse(book = "Jòb", chapter = 21, verseNumber = 25, text = "Yon lòt menm pa janm konnen sa ki rele kè kontan. Li pase tout lavi l' nan nesesite, li mouri nan mizè.", bookId = 18),
        Verse(book = "Jòb", chapter = 21, verseNumber = 26, text = "Men, lè tou de mouri, yo antere yo, vèmen kouvri kadav yo menm jan.", bookId = 18),
        Verse(book = "Jòb", chapter = 21, verseNumber = 27, text = "Men wi, mwen konnen sa ki nan tèt nou. Mwen konnen ki move lide n'ap fè sou mwen koulye a.", bookId = 18),
        Verse(book = "Jòb", chapter = 21, verseNumber = 28, text = "N'ap mande kote kay gwo zotobre a. Sa ki rive kay nèg ki te konn fè sa ki mal la.", bookId = 18),
        Verse(book = "Jòb", chapter = 21, verseNumber = 29, text = "Kouman? Nou pa pale ak moun ki vwayaje? Nou pa konn ki nouvèl y'ap bay?", bookId = 18),
        Verse(book = "Jòb", chapter = 21, verseNumber = 30, text = "Jou Bondye ankòlè, lè l'ap pini an, se toujou mechan yo ki resi chape kò yo!", bookId = 18),
        Verse(book = "Jòb", chapter = 21, verseNumber = 31, text = "Men, ki moun ki ka kanpe devan yo pou akize yo? Ki moun ki ka fè yo peye sa yo fè a?", bookId = 18),
        Verse(book = "Jòb", chapter = 21, verseNumber = 32, text = "Yo fè bèl lantèman pou yo. Yo mete moun veye tonm yo.", bookId = 18),
        Verse(book = "Jòb", chapter = 21, verseNumber = 33, text = "Foul moun ap swiv sèkèy yo, yon pati moun devan, yon pati moun dèyè. Menm tè a chita dous sou kadav yo.", bookId = 18),
        Verse(book = "Jòb", chapter = 21, verseNumber = 34, text = "Lèfini, n'ap chache konsole m' ak yon bann pawòl san sans. Tou sa n'ap reponn mwen la a se manti.", bookId = 18)
    )

    private val part2 = listOf(
        Verse(book = "Jòb", chapter = 22, verseNumber = 1, text = "Lè sa a, Elifaz, moun lavil Teman an, pran lapawòl. Li di konsa:", bookId = 18),
        Verse(book = "Jòb", chapter = 22, verseNumber = 2, text = "-Eske yon moun ka itil Bondye? Non! Ata moun ki gen bon konprann yo, se tèt yo ase yo itil.", bookId = 18),
        Verse(book = "Jòb", chapter = 22, verseNumber = 3, text = "Lè ou fè sa ki byen, ki enterè Bondye ki gen tout pouvwa a jwenn nan sa? Sa sa rapòte l' lè ou mennen bak ou dwat?", bookId = 18),
        Verse(book = "Jòb", chapter = 22, verseNumber = 4, text = "Eske se paske ou gen krentif pou Bondye kifè l'ap rale zòrèy ou konsa, kifè l'ap trennen ou nan tribinal li?", bookId = 18),
        Verse(book = "Jòb", chapter = 22, verseNumber = 5, text = "Non. Se paske ou fè anpil peche. Se paske ou te san limit nan fè mechanste.", bookId = 18),
        Verse(book = "Jòb", chapter = 22, verseNumber = 6, text = "Ou fè frè ou ba ou garanti pou lajan li pa t' dwe ou. Ou pran ata rad ki sou li, ou kite l' toutouni.", bookId = 18),
        Verse(book = "Jòb", chapter = 22, verseNumber = 7, text = "Ou refize bay moun ki te swaf yo ti gout dlo. Ou refize bay moun ki te grangou yo moso pen.", bookId = 18),
        Verse(book = "Jòb", chapter = 22, verseNumber = 8, text = "Ou pwofite fòs ou ak pozisyon ou pou pran tout peyi a pou ou.", bookId = 18),
        Verse(book = "Jòb", chapter = 22, verseNumber = 9, text = "Ou refize lonje men ou bay vèv yo. Ou maltrete timoun ki san papa yo.", bookId = 18),
        Verse(book = "Jòb", chapter = 22, verseNumber = 10, text = "Se poutèt sa, kote ou rive se pèlen yo pare pou ou. Ou rete konsa, kè ou kase.", bookId = 18),
        Verse(book = "Jòb", chapter = 22, verseNumber = 11, text = "Sitèlman fè nwa, ou pa ka wè. Ou nan dlo jouk nan kou!", bookId = 18),
        Verse(book = "Jòb", chapter = 22, verseNumber = 12, text = "Eske se pa anwo nèt nan syèl la Bondye rete? Se anba pou li voye je l' pou l' ka wè zetwal yo.", bookId = 18),
        Verse(book = "Jòb", chapter = 22, verseNumber = 13, text = "Ou konn sa, epi w'ap di: Sa Bondye ka konnen? Li kache dèyè nwaj yo, ki jan pou l' jije sa k'ap pase sou latè?", bookId = 18),
        Verse(book = "Jòb", chapter = 22, verseNumber = 14, text = "Nwaj yo twò pwès, li pa ka wè. Se sou fetay syèl la l'ap mache.", bookId = 18),
        Verse(book = "Jòb", chapter = 22, verseNumber = 15, text = "Ou vle mache pye pou pye dèyè mechan yo, nan move chemen yo te toujou pran depi lontan an!", bookId = 18),
        Verse(book = "Jòb", chapter = 22, verseNumber = 16, text = "Yo mouri anvan lè yo tou. Yo tankou lavalas: anvan ou bat je ou, yo pase.", bookId = 18),
        Verse(book = "Jòb", chapter = 22, verseNumber = 17, text = "Yo menm tou yo t'ap di Bondye: Wete kò ou sou nou! Kisa Bondye ki gen tout pouvwa a ka fè nou?", bookId = 18),
        Verse(book = "Jòb", chapter = 22, verseNumber = 18, text = "Atò, se Bondye menm ki te plen kay yo ak richès. Mwen pa janm konprann ki jan mechan yo ka fè di sa.", bookId = 18),
        Verse(book = "Jòb", chapter = 22, verseNumber = 19, text = "Men, lè y'ap pini mechan yo, moun ki mache dwat yo va kontan, inonsan yo va pase yo nan rizib.", bookId = 18),
        Verse(book = "Jòb", chapter = 22, verseNumber = 20, text = "Gade jan grannèg yo fini non! Dife boule tou sa yo te genyen.", bookId = 18),
        Verse(book = "Jòb", chapter = 22, verseNumber = 21, text = "Jòb monchè, byen ak Bondye ankò, tande! Sispann chache l' kont!", bookId = 18),
        Verse(book = "Jòb", chapter = 22, verseNumber = 22, text = "Koute pawòl li t'ap di ou yo. Kenbe yo nan kè ou.", bookId = 18),
        Verse(book = "Jòb", chapter = 22, verseNumber = 23, text = "Wi, tounen vin jwenn li, san lògèy nan kè ou. Sispann fè sa ki mal lakay ou.", bookId = 18),
        Verse(book = "Jòb", chapter = 22, verseNumber = 24, text = "Voye tout lò ou jete nan fatra. Pi bon pyès lò ou yo, jete yo nan galèt larivyè.", bookId = 18),
        Verse(book = "Jòb", chapter = 22, verseNumber = 25, text = "Se Bondye ki gen tout pouvwa a ki va tout lò ou. Se li menm ki va gwo pil lajan byen wo pou ou.", bookId = 18),
        Verse(book = "Jòb", chapter = 22, verseNumber = 26, text = "Paske, lè sa a, se nan Bondye ki gen tout pouvwa a w'a jwenn tout plezi ou. Se sou Bondye w'a toujou gade.", bookId = 18),
        Verse(book = "Jòb", chapter = 22, verseNumber = 27, text = "Lè w'a lapriyè nan pye l', l'a reponn ou. W'a kenbe tout pwomès ou fè l' yo.", bookId = 18),
        Verse(book = "Jòb", chapter = 22, verseNumber = 28, text = "Tout zafè ou va mache byen. Limyè va klere byen bèl sou tout wout ou.", bookId = 18),
        Verse(book = "Jòb", chapter = 22, verseNumber = 29, text = "Bondye kraze lògèy moun awogan. Men, li sove moun ki bese tèt devan li.", bookId = 18),
        Verse(book = "Jòb", chapter = 22, verseNumber = 30, text = "L'ap delivre ou si ou inonsan. L'a sove ou, si ou pa janm sal men ou nan anyen.", bookId = 18),
        Verse(book = "Jòb", chapter = 23, verseNumber = 1, text = "Lè sa a, Jòb pran lapawòl, li di konsa:", bookId = 18),
        Verse(book = "Jòb", chapter = 23, verseNumber = 2, text = "-Fwa sa a ankò, m'ap kenbe tèt ak Bondye, m'ap plenyen nan pye l'. Se plenn m'ap plenn pou sa m'ap pase anba men l'.", bookId = 18),
        Verse(book = "Jòb", chapter = 23, verseNumber = 3, text = "Si m' te ka konnen kote pou m' jwenn li, mwen ta rive kote l' ye a.", bookId = 18),
        Verse(book = "Jòb", chapter = 23, verseNumber = 4, text = "M' ta defann kòz mwen devan li. M' ta di l' dènye sa ki nan lide m' pou defann tèt mwen.", bookId = 18),
        Verse(book = "Jòb", chapter = 23, verseNumber = 5, text = "M' ta konnen jan l'ap reponn mwen, m' ta tande sa l'ap di m'.", bookId = 18),
        Verse(book = "Jòb", chapter = 23, verseNumber = 6, text = "Eske Bondye tapral sèvi ak tout fòs li pou diskite avè m'? Non. Li ta rete koute m' ase.", bookId = 18),
        Verse(book = "Jòb", chapter = 23, verseNumber = 7, text = "Li ta wè moun k'ap pale avè l' la se yon moun ki toujou mache dwat. Li menm k'ap jije m' lan, li ta rekonèt mwen inonsan.", bookId = 18),
        Verse(book = "Jòb", chapter = 23, verseNumber = 8, text = "M' ale bò solèy leve, Bondye pa la. M' ale bò solèy kouche, mwen pa wè l' tou.", bookId = 18),
        Verse(book = "Jòb", chapter = 23, verseNumber = 9, text = "Mwen moute nan nò al chache l', m' pa wè l'. Mwen desann nan sid, bichi!", bookId = 18),
        Verse(book = "Jòb", chapter = 23, verseNumber = 10, text = "Men, Bondye konnen tout ti vire tounen mwen. Si li sonde m', l'a wè m' bon tankou bon lò ki pase nan dife.", bookId = 18),
        Verse(book = "Jòb", chapter = 23, verseNumber = 11, text = "M' mache pye pou pye dèyè l'. M' swiv chemen li mete devan m' lan. M' pa janm devire ni adwat ni agoch.", bookId = 18),
        Verse(book = "Jòb", chapter = 23, verseNumber = 12, text = "Mwen toujou fè tou sa li bay lòd fè. Mwen te fè volonte l', mwen pa fè sa m' te gen nan tèt mwen.", bookId = 18),
        Verse(book = "Jòb", chapter = 23, verseNumber = 13, text = "Men, lè Bondye fin deside yon bagay, ki moun ki ka fè l' chanje lide? Ki moun ki ka enpoze l' fè sa li vle fè a?", bookId = 18),
        Verse(book = "Jòb", chapter = 23, verseNumber = 14, text = "L'ap toujou fè m' sa li vle fè m' lan. Sa se yonn nan tout bagay li deside fè yo.", bookId = 18),
        Verse(book = "Jòb", chapter = 23, verseNumber = 15, text = "Se poutèt sa, m'ap tranble devan l'. Lè m' chonje sa, mwen soti pè l'.", bookId = 18),
        Verse(book = "Jòb", chapter = 23, verseNumber = 16, text = "Men wi, se Bondye k'ap kraze kouraj mwen. Se Bondye menm mwen soti pè. Se pa fènwa a.", bookId = 18),
        Verse(book = "Jòb", chapter = 23, verseNumber = 17, text = "Fènwa a kache Bondye pou m' pa wè l'. L' enpoze m' santi prezans li. Se tout!", bookId = 18),
        Verse(book = "Jòb", chapter = 24, verseNumber = 1, text = "Poukisa Bondye ki gen tout pouvwa a pa fikse yon dat pou li jije tout moun, yon jou pou li rann tout moun k'ap sèvi l' yo jistis?", bookId = 18),
        Verse(book = "Jòb", chapter = 24, verseNumber = 2, text = "Mechan yo deplase bòn tè moun. Yo vòlò mouton lòt moun, mete ansanm avèk bann mouton pa yo.", bookId = 18),
        Verse(book = "Jòb", chapter = 24, verseNumber = 3, text = "Yo pran bourik ki pou timoun san papa yo. Yo sezi bèf vèv la jouk li resi peye dèt li.", bookId = 18),
        Verse(book = "Jòb", chapter = 24, verseNumber = 4, text = "Yo enpoze pòv yo jwenn sa ki vin pou yo. Yo fòse tout pòv malere kouri al kache.", bookId = 18),
        Verse(book = "Jòb", chapter = 24, verseNumber = 5, text = "Tankou bourik mawon, pòv yo soti al nan dezè a, y' al chache lavi pou pitit yo ki grangou. Pa gen lòt kote yo ka ale.", bookId = 18),
        Verse(book = "Jòb", chapter = 24, verseNumber = 6, text = "Y'ap ranmase rekòt pou lòt moun. Y'ap keyi rezen nan jaden pou mechan yo.", bookId = 18),
        Verse(book = "Jòb", chapter = 24, verseNumber = 7, text = "Lè yo toutouni, yo pa gen rad pou mete sou yo. Lannwit, yo pa gen anyen pou chofe kò yo lè yo frèt.", bookId = 18),
        Verse(book = "Jòb", chapter = 24, verseNumber = 8, text = "Lapli k'ap tonbe sou mòn yo mouye yo jouk nan zo. Yo kwoupi kò yo dèyè wòch pou pare lapli.", bookId = 18),
        Verse(book = "Jòb", chapter = 24, verseNumber = 9, text = "Mechan yo wete timoun san papa yo nan men manman yo pou fè yo tounen esklav. Yo pran rad pòv malere yo pou garanti dèt yo.", bookId = 18),
        Verse(book = "Jòb", chapter = 24, verseNumber = 10, text = "Pòv yo menm ap mache yon men devan yon men dèyè, san rad pou mete sou yo. Y'ap mache ranmase rekòt nan jaden, men y'ap mouri grangou.", bookId = 18),
        Verse(book = "Jòb", chapter = 24, verseNumber = 11, text = "Nan lakou mechan yo y'ap moulen grenn oliv fè lwil. Y'ap kraze rezen fè diven. Men y'ap mouri swaf dlo.", bookId = 18),
        Verse(book = "Jòb", chapter = 24, verseNumber = 12, text = "Nan lavil yo, ou tande moun k'ap mouri yo ap plenn. Ou tande moun ki blese yo ap rele anmwe. Men, Bondye fè tankou li pa tande yo.", bookId = 18),
        Verse(book = "Jòb", chapter = 24, verseNumber = 13, text = "Se moun sa yo ki pa vle wè limyè a. Yo derefize konprann limyè a. Yo pa vle pran chemen limyè a nan tou sa y'ap fè.", bookId = 18),
        Verse(book = "Jòb", chapter = 24, verseNumber = 14, text = "Anvan bajou kase, ansasen an gen tan leve, pou li al touye pòv malere yo. Lannwit, se vòlò l'ap mache vòlò.", bookId = 18),
        Verse(book = "Jòb", chapter = 24, verseNumber = 15, text = "Mouche marye k'ap fè adiltè a ap tann solèy kouche konsa. Li bouche figi l' pou pesonn pa wè l'.", bookId = 18),
        Verse(book = "Jòb", chapter = 24, verseNumber = 16, text = "Lannwit, vòlè ap kraze kay moun. Lajounen yo kache, y'ap kouri pou solèy.", bookId = 18),
        Verse(book = "Jòb", chapter = 24, verseNumber = 17, text = "Yo pè limyè lajounen an. Men, pa gen anyen ki pou fè yo pè nan fènwa a.", bookId = 18),
        Verse(book = "Jòb", chapter = 24, verseNumber = 18, text = "Lè sa a, Sofa di konsa: -Men dlo desann pote mechan yo ale. Madichon Bondye tonbe sou tout tè ki pou yo. Yo pa soti al travay nan jaden rezen yo.", bookId = 18),
        Verse(book = "Jòb", chapter = 24, verseNumber = 19, text = "Menm jan chalè fonn lanèj, lèfini tè sèk bwè dlo a, se konsa moun k'ap fè peche yo ap disparèt ale nan peyi kote mò yo ye a.", bookId = 18),
        Verse(book = "Jòb", chapter = 24, verseNumber = 20, text = "Tout moun bliye yo. Ata manman ki fè yo pa chonje yo. Se vè k'ap manje kadav yo. Yo fini tankou yon pyebwa yo koupe jete.", bookId = 18),
        Verse(book = "Jòb", chapter = 24, verseNumber = 21, text = "Tou sa rive konsa, paske li maltrete fanm ki pa ka fè pitit. Li san pitye pou vèv yo.", bookId = 18),
        Verse(book = "Jòb", chapter = 24, verseNumber = 22, text = "Lè sa a, Bondye detwi gwo chèf yo ak fòs ponyèt li. Li annik parèt, mechan an konnen li mouri.", bookId = 18),
        Verse(book = "Jòb", chapter = 24, verseNumber = 23, text = "Bondye kite l' viv alèz san pwoblèm, men, se toutan l'ap veye tou sa l'ap fè.", bookId = 18),
        Verse(book = "Jòb", chapter = 24, verseNumber = 24, text = "Zafè mechan yo mache byen pou yon tan. Men, apre sa, yo fennen tankou zèb savann, tankou tèt ble yo koupe.", bookId = 18),
        Verse(book = "Jòb", chapter = 24, verseNumber = 25, text = "Si se pa konsa sa ye, ki moun ki ka demanti sa m' di la a? Ki moun ki ka fè wè pawòl mwen yo pa vo anyen?", bookId = 18),
        Verse(book = "Jòb", chapter = 25, verseNumber = 1, text = "Bildad, moun lavil Chwa a, pran lapawòl, li di konsa:", bookId = 18),
        Verse(book = "Jòb", chapter = 25, verseNumber = 2, text = "-Bondye se chèf. Li fè tout moun respekte l'. Li fè tout moun nan peyi ki nan syèl la viv ak kè poze.", bookId = 18),
        Verse(book = "Jòb", chapter = 25, verseNumber = 3, text = "Ki moun ki ka konte kantite zanj k'ap sèvi l'? Pa gen kote limyè Bondye a pa klere.", bookId = 18),
        Verse(book = "Jòb", chapter = 25, verseNumber = 4, text = "Atò, moun ka konprann yo gen rezon devan Bondye? Pitit fanm pouse met atè ka san repwòch devan li?", bookId = 18),
        Verse(book = "Jòb", chapter = 25, verseNumber = 5, text = "Nan je Bondye, menm lalin lan pa klere ase. Pa gen yonn nan zetwal yo ki bon nèt pou li.", bookId = 18),
        Verse(book = "Jòb", chapter = 25, verseNumber = 6, text = "Ale wè pou moun, yon vètè, yon ti krebete! Kisa yo vo nan je Bondye?", bookId = 18),
        Verse(book = "Jòb", chapter = 26, verseNumber = 1, text = "Jòb pran lapawòl ankò, li di l' konsa:", bookId = 18),
        Verse(book = "Jòb", chapter = 26, verseNumber = 2, text = "-Ou gen tan konn konsole moun ki nan lafliksyon! Ou gen tan konn lonje men bay moun ki san fòs!", bookId = 18),
        Verse(book = "Jòb", chapter = 26, verseNumber = 3, text = "Ala bon konsèy ou bay moun ki san konprann lan! Ou gen tan gen anpil konesans nan ou!", bookId = 18),
        Verse(book = "Jòb", chapter = 26, verseNumber = 4, text = "Men, pou ki moun tout bèl diskou sa yo? Ki moun ki mete pawòl sa yo nan bouch ou?", bookId = 18),
        Verse(book = "Jòb", chapter = 26, verseNumber = 5, text = "Bildad pran lapawòl ankò li di: -Nanm moun mouri k'ap viv nan fon lanmè a ap tranble anba tè a.", bookId = 18),
        Verse(book = "Jòb", chapter = 26, verseNumber = 6, text = "Peyi kote mò yo ye a louvri aklè devan je Bondye. Pa gen anyen ki pou anpeche Bondye wè sa k'ap pase ladan l'.", bookId = 18),
        Verse(book = "Jòb", chapter = 26, verseNumber = 7, text = "Se li menm ki louvri syèl ki sou bò nò a anlè, san anyen pou soutni l'. Li pandye tè a ankò san anyen pou kenbe l'.", bookId = 18),
        Verse(book = "Jòb", chapter = 26, verseNumber = 8, text = "Se li menm ki plen nwaj yo dlo. Se li menm ki pa kite pèz dlo a pete nwaj yo.", bookId = 18),
        Verse(book = "Jòb", chapter = 26, verseNumber = 9, text = "Se li menm ki kache lalin plenn lan dèyè yon nwaj.", bookId = 18),
        Verse(book = "Jòb", chapter = 26, verseNumber = 10, text = "Se li menm ki trase yon wonn sou lanmè a, li separe limyè ak fènwa.", bookId = 18),
        Verse(book = "Jòb", chapter = 26, verseNumber = 11, text = "Lè li bay poto ki soutni syèl la yon prigad, yo sezi, yo pran tranble sitèlman yo pè.", bookId = 18),
        Verse(book = "Jòb", chapter = 26, verseNumber = 12, text = "Avèk fòs ponyèt li, li fè lanmè a vin dou devan li. Avèk ladrès li, li kraze Raab, gwo bèt lèd la.", bookId = 18),
        Verse(book = "Jòb", chapter = 26, verseNumber = 13, text = "Avèk souf li, li fè syèl la vin klè. Avèk men li, li touye gwo koulèv ki t'ap kouri chape a.", bookId = 18),
        Verse(book = "Jòb", chapter = 26, verseNumber = 14, text = "Sa se yon ti kal nan tou sa li fè. Se sa ase ki resi rive nan zòrèy nou! Men, ki moun ki ka konnen tou sa Bondye fè?", bookId = 18),
        Verse(book = "Jòb", chapter = 27, verseNumber = 1, text = "Jòb pran lapawòl ankò pou l' bay rès repons li a. Li di konsa:", bookId = 18),
        Verse(book = "Jòb", chapter = 27, verseNumber = 2, text = "-Mwen fè sèman, mwen pran Bondye vivan an pou temwen, Bondye ki gen tout pouvwa a, li menm ki refize rann mwen jistis la, li menm ki ban m' degoutans ak lavi a,", bookId = 18),
        Verse(book = "Jòb", chapter = 27, verseNumber = 3, text = "toutotan mwen poko mouri, toutotan Bondye ban m' yon ti souf toujou,", bookId = 18),
        Verse(book = "Jòb", chapter = 27, verseNumber = 4, text = "mwen p'ap janm kite ankenn move pawòl soti nan bouch mwen, ni m' p'ap janm bay ankenn manti.", bookId = 18),
        Verse(book = "Jòb", chapter = 27, verseNumber = 5, text = "Pa janm konprann m'ap ban nou rezon! M'ap kenbe ak nou mwen inonsan jouk mwen rann dènye souf mwen.", bookId = 18),
        Verse(book = "Jòb", chapter = 27, verseNumber = 6, text = "Mwen soti pou m' defann kòz mwen. Mwen p'ap fè bak. Konsyans mwen pa repwoche m' anyen. M' pa gen anyen ki pou fè m' wont.", bookId = 18),
        Verse(book = "Jòb", chapter = 27, verseNumber = 7, text = "Se pou tout moun ki pa vle wè m' yo sibi menm sò ak mechan yo. Se pou lènmi m' yo gen menm sò ak moun ki pa mache dwat yo.", bookId = 18),
        Verse(book = "Jòb", chapter = 27, verseNumber = 8, text = "Ki espwa ki gen pou mechan an lè Bondye rele l', lè li pral pran nanm li?", bookId = 18),
        Verse(book = "Jòb", chapter = 27, verseNumber = 9, text = "Lè malè ap tonbe sou mechan an, èske Bondye ap tande rèl li yo?", bookId = 18),
        Verse(book = "Jòb", chapter = 27, verseNumber = 10, text = "Li pa t' janm pran plezi l' nan fè volonte Bondye. Li pa t' lapriyè Bondye tout tan.", bookId = 18),
        Verse(book = "Jòb", chapter = 27, verseNumber = 11, text = "Kite m' moutre nou jan Bondye konnen sa l'ap fè. Mwen p'ap kache di nou sa ki nan tèt Bondye ki gen tout pouvwa a.", bookId = 18),
        Verse(book = "Jòb", chapter = 27, verseNumber = 12, text = "Sa m'ap di la a? Nou wè tou sa ak je nou byen pwòp tou. Poukisa atò tout pale anpil sa a ki pa vle di anyen?", bookId = 18),
        Verse(book = "Jòb", chapter = 27, verseNumber = 13, text = "Lè sa a, Sofa, moun lavil Naama a, pran lapawòl. Epi li di: -Men kisa Bondye pare pou mechan yo. Men sa li sere pou chèf k'ap peze pèp la.", bookId = 18),
        Verse(book = "Jòb", chapter = 27, verseNumber = 14, text = "Yo te mèt gen anpil pitit gason, yo tout ap mouri nan lagè. Pitit yo p'ap janm gen kont manje pou yo manje.", bookId = 18),
        Verse(book = "Jòb", chapter = 27, verseNumber = 15, text = "Sa ki chape nan lagè, move maladi ap pote yo ale. Ata vèv yo p'ap ka rele pou yo jou lanmò yo.", bookId = 18),
        Verse(book = "Jòb", chapter = 27, verseNumber = 16, text = "Mechan an te mèt anpile lajan kou l' pa konnen, li te mèt gen rad depase sa l' bezwen,", bookId = 18),
        Verse(book = "Jòb", chapter = 27, verseNumber = 17, text = "se moun dwat yo ki va mete rad yo, se pou moun inonsan yo lajan an va rete.", bookId = 18),
        Verse(book = "Jòb", chapter = 27, verseNumber = 18, text = "Kay li bati tankou twal anasi, tankou yon ti kay jaden.", bookId = 18),
        Verse(book = "Jòb", chapter = 27, verseNumber = 19, text = "Nan aswè, li moute kabann li rich. Lè li leve, li pa jwenn anyen.", bookId = 18),
        Verse(book = "Jòb", chapter = 27, verseNumber = 20, text = "Malè tonbe sou li tankou lavalas k'ap desann. Yon sèl nwit lan, yon gwo van pote l' ale.", bookId = 18),
        Verse(book = "Jòb", chapter = 27, verseNumber = 21, text = "Yon van lès leve, li pote l' ale. Li rache l' nan kay kote l' ye a.", bookId = 18),
        Verse(book = "Jòb", chapter = 27, verseNumber = 22, text = "Van an ap vante sou li san pitye. Li menm l'ap fè sa li kapab pou l' chape anba l'.", bookId = 18),
        Verse(book = "Jòb", chapter = 27, verseNumber = 23, text = "Moun kontan wè jan li fini. Kote l' pase, y'ap rele chalbari dèyè l'.", bookId = 18),
        Verse(book = "Jòb", chapter = 28, verseNumber = 1, text = "Gen mi n anba tè kote yo jwenn ajan. Gen kote se la yo netwaye lò.", bookId = 18),
        Verse(book = "Jòb", chapter = 28, verseNumber = 2, text = "Yo fouye tè pou jwenn fè. Yo fonn wòch pou jwenn kwiv.", bookId = 18),
        Verse(book = "Jòb", chapter = 28, verseNumber = 3, text = "Yo desann ak limyè anba tè, kote ki fè nwa anpil, yo fouye byen fon nan vant latè, mezi yo kapab. Y' al chache wòch ki kache kote ki fè nwa anpil la.", bookId = 18),
        Verse(book = "Jòb", chapter = 28, verseNumber = 4, text = "Byen lwen, kote moun pa ka rete, kote moun pa janm mete pye yo, moun ap fouye gwo koridò anba tè. Y'ap travay pou kont yo, ak yon kòd pase nan ren yo, y'ap balanse nan twou yo.", bookId = 18),
        Verse(book = "Jòb", chapter = 28, verseNumber = 5, text = "Manje soti nan tè. Men, nan zantray latè a dife fin debòde.", bookId = 18),
        Verse(book = "Jòb", chapter = 28, verseNumber = 6, text = "Wòch latè a gen bèl pyè safi ladan l'. Nan pousyè a yo jwenn ti grenn lò.", bookId = 18),
        Verse(book = "Jòb", chapter = 28, verseNumber = 7, text = "Koukou pa janm konnen chemen pou ale la. Karanklou pa janm wè kote sa a ak je l'.", bookId = 18),
        Verse(book = "Jòb", chapter = 28, verseNumber = 8, text = "Ni lyon, ni ankenn lòt bèt nan bwa, pa janm mete pye yo la.", bookId = 18),
        Verse(book = "Jòb", chapter = 28, verseNumber = 9, text = "Yo fouye nan wòch dife. Yo fè gwo twou byen fon nan pye mòn yo.", bookId = 18),
        Verse(book = "Jòb", chapter = 28, verseNumber = 10, text = "Yo fè gwo koridò byen long nan wòch yo. Yo jwenn tout kalite bèl pyè bijou ki koute chè.", bookId = 18),
        Verse(book = "Jòb", chapter = 28, verseNumber = 11, text = "Yo fouye nan sous tèt dlo yo tou. Yo mete deyò tou sa ki te kache.", bookId = 18),
        Verse(book = "Jòb", chapter = 28, verseNumber = 12, text = "Men, kote nou ka jwenn konesans lan? Kote bon konprann lan ye menm?", bookId = 18),
        Verse(book = "Jòb", chapter = 28, verseNumber = 13, text = "Lèzòm pa konnen sa pou yo fè pou yo mete men sou li. Yo pa jwenn li ankenn kote sou latè.", bookId = 18),
        Verse(book = "Jòb", chapter = 28, verseNumber = 14, text = "Fon lanmè a deklare li pa gen bagay konsa. Lanmè a deklare bon konprann pa lakay li.", bookId = 18),
        Verse(book = "Jòb", chapter = 28, verseNumber = 15, text = "Ou te mèt gen lò, ou pa ka achte l'. Ou pa ka bay lajan pou ou genyen l'.", bookId = 18),
        Verse(book = "Jòb", chapter = 28, verseNumber = 16, text = "Li gen plis valè pase lò peyi Ofi a. Bèl pyè oniks ak safi pa ka parèt la.", bookId = 18),
        Verse(book = "Jòb", chapter = 28, verseNumber = 17, text = "Yo pa ka konpare l' ni ak lò ni ak bèl kristal. Yo pa ka boukante l' pou yon bèl veso fèt an lò.", bookId = 18),
        Verse(book = "Jòb", chapter = 28, verseNumber = 18, text = "Pou grenn koray ak wòch kristal menm, yo pa ka parèt la. Pito ou al dèyè bon konprann pase ou ale dèyè bèl pyè lanbi.", bookId = 18),
        Verse(book = "Jòb", chapter = 28, verseNumber = 19, text = "Topaz peyi Letiopi pa vo anyen devan l'. Pi bon lò a pa ka konpare ak bon konprann.", bookId = 18),
        Verse(book = "Jòb", chapter = 28, verseNumber = 20, text = "Men, kote nou ka jwenn konesans lan? Kote bon konprann lan ye menm?", bookId = 18),
        Verse(book = "Jòb", chapter = 28, verseNumber = 21, text = "Pa gen moun, pa gen bèt ki ka wè l', pa menm zwazo k'ap vole nan syèl la.", bookId = 18),
        Verse(book = "Jòb", chapter = 28, verseNumber = 22, text = "Ata lanmò ak simityè di se tande yo tande nonmen non l'.", bookId = 18),
        Verse(book = "Jòb", chapter = 28, verseNumber = 23, text = "Se Bondye ase ki konn chemen an. Se li ase ki konnen kote li rete.", bookId = 18),
        Verse(book = "Jòb", chapter = 28, verseNumber = 24, text = "Paske Bondye wè dènye bout latè. Li voye je l', li gade tou sa ki anba syèl la.", bookId = 18),
        Verse(book = "Jòb", chapter = 28, verseNumber = 25, text = "Lè Bondye t'ap bay van yo pèz yo, lè li t'ap bay dlo lanmè a mezi kote pou l' rive a,", bookId = 18),
        Verse(book = "Jòb", chapter = 28, verseNumber = 26, text = "lè li t'ap bay lòd kote pou lapli tonbe ak chemen pou loraj yo pran lè y'ap gwonde,", bookId = 18),
        Verse(book = "Jòb", chapter = 28, verseNumber = 27, text = "se lè sa a li te wè bon konprann, li wè sa li vo. Li egzaminen l' byen egzaminen, li sonde l' byen sonde.", bookId = 18),
        Verse(book = "Jòb", chapter = 28, verseNumber = 28, text = "Apre sa, Bondye di moun konsa: -Gen krentif pou Bondye, se sa ki rele bon konprann. Vire do bay sa ki mal, men sa ki rele gen lespri.", bookId = 18),
        Verse(book = "Jòb", chapter = 29, verseNumber = 1, text = "Jòb tanmen pale ankò, li di:", bookId = 18),
        Verse(book = "Jòb", chapter = 29, verseNumber = 2, text = "-Ki moun ki va fè m' viv tan lontan an, lè Bondye t'ap voye je sou mwen an?", bookId = 18),
        Verse(book = "Jòb", chapter = 29, verseNumber = 3, text = "Lè sa a, Bondye te toujou la avèk mwen. Limyè li te klere anwo tèt mwen, li t'ap moutre m' kote pou m' mete pye m' nan fènwa a.", bookId = 18),
        Verse(book = "Jòb", chapter = 29, verseNumber = 4, text = "Nan tan sa a, tout zafè m' t'ap mache byen. Bondye te zanmi m'. Li t'ap pwoteje kay mwen.", bookId = 18),
        Verse(book = "Jòb", chapter = 29, verseNumber = 5, text = "Bondye ki gen tout pouvwa a te toujou la avèk mwen. Mwen t'ap viv nan mitan tout pitit gason m' yo.", bookId = 18),
        Verse(book = "Jòb", chapter = 29, verseNumber = 6, text = "Bèf ak kabrit mwen yo te konn bay anpil lèt. Pye oliv mwen yo te donnen menm nan tè wòch.", bookId = 18),
        Verse(book = "Jòb", chapter = 29, verseNumber = 7, text = "Lè mwen parèt pòtay lavil la, lè mwen pran plas mwen nan mitan chèf fanmi yo,", bookId = 18),
        Verse(book = "Jòb", chapter = 29, verseNumber = 8, text = "wè yo wè m', jenn gason yo mete kò yo sou kote, granmoun yo leve kanpe pa respè pou mwen.", bookId = 18),
        Verse(book = "Jòb", chapter = 29, verseNumber = 9, text = "Notab yo sispann pale, yo fèmen bouch yo.", bookId = 18),
        Verse(book = "Jòb", chapter = 29, verseNumber = 10, text = "Ata chèf yo pa ka pale ankò! Lang yo vin lou nan bouch yo.", bookId = 18),
        Verse(book = "Jòb", chapter = 29, verseNumber = 11, text = "Tout moun ki te wè m' t'ap mache fè lwanj mwen, tout moun ki te tande m' te kontan avè m'.", bookId = 18),
        Verse(book = "Jòb", chapter = 29, verseNumber = 12, text = "Mwen lonje men bay pòv malere ki nan ka ansanm ak timoun san papa ki san sekou.", bookId = 18),
        Verse(book = "Jòb", chapter = 29, verseNumber = 13, text = "Moun ki te nan pi gwo mizè t'ap fè lwanj mwen. Mwen te fè kè vèv yo kontan.", bookId = 18),
        Verse(book = "Jòb", chapter = 29, verseNumber = 14, text = "Mwen te toujou fè sa ki dwat. Mwen pa t' janm nan patipri.", bookId = 18),
        Verse(book = "Jòb", chapter = 29, verseNumber = 15, text = "Se mwen ki te wè pou avèg yo. Se mwen ki te mache pou kokobe yo.", bookId = 18),
        Verse(book = "Jòb", chapter = 29, verseNumber = 16, text = "Mwen te yon papa pou pòv malere yo. Mwen te kanpe pou defann kòz etranje yo.", bookId = 18),
        Verse(book = "Jòb", chapter = 29, verseNumber = 17, text = "Mwen te kraze pouvwa malveyan yo. Mwen sove moun ki te anba men yo.", bookId = 18),
        Verse(book = "Jòb", chapter = 29, verseNumber = 18, text = "Mwen t'ap di nan kè m': M'a viv kont viv mwen. M'a mouri sou kabann mwen ak kè poze.", bookId = 18),
        Verse(book = "Jòb", chapter = 29, verseNumber = 19, text = "Mwen te tankou yon pyebwa plante bò larivyè. Sou tout branch li yo se lawouze.", bookId = 18),
        Verse(book = "Jòb", chapter = 29, verseNumber = 20, text = "Moun pa ta janm sispann fè lwanj mwen. Mwen t'ap toujou gen tout fòs mwen sou mwen.", bookId = 18),
        Verse(book = "Jòb", chapter = 29, verseNumber = 21, text = "Lè m'ap pale, tout moun fèmen bouch yo. Yo louvri zòrèy yo, y'ap tann konsa konsèy m'ap bay.", bookId = 18),
        Verse(book = "Jòb", chapter = 29, verseNumber = 22, text = "Pawòl mwen tonbe nan kè yo tankou grenn lapli. Lè m' fin pale, pesonn pa gen anyen pou di ankò.", bookId = 18),
        Verse(book = "Jòb", chapter = 29, verseNumber = 23, text = "Yo t'ap tann mwen pale tankou tè sèk k'ap tann lapli. Yo rete bouch louvri pou ranmase sa m'ap di.", bookId = 18),
        Verse(book = "Jòb", chapter = 29, verseNumber = 24, text = "Lè yo dekouraje, mwen fè yon ti ri ak yo. Sa te kont pou remoute kouraj yo.", bookId = 18),
        Verse(book = "Jòb", chapter = 29, verseNumber = 25, text = "Mwen te kanpe alatèt yo. Mwen mennen yo tankou yon wa k'ap mennen sòlda li yo. Mwen di yo sa pou yo fè. Mwen te ba yo kouraj lè yo nan lafliksyon.", bookId = 18),
        Verse(book = "Jòb", chapter = 30, verseNumber = 1, text = "Men koulye a, moun ki pi jenn pase m' yo ap pase m' nan rizib. Papa yo se moun mwen pa t' pran pou anyen, moun mwen pa ta menm mete ak chen m' pou gade mouton.", bookId = 18),
        Verse(book = "Jòb", chapter = 30, verseNumber = 2, text = "Epitou, yo te twò fèb pou fè anyen pou mwen. Se te yon bann gason san kouraj.", bookId = 18),
        Verse(book = "Jòb", chapter = 30, verseNumber = 3, text = "Mizè ak grangou te fini ak yo. Lannwit se grenn bwa yo te konn al souse nan savann kote moun pa rete.", bookId = 18),
        Verse(book = "Jòb", chapter = 30, verseNumber = 4, text = "Yo pran fèy raje pou yo manje. Ata rasin bayawonn pase.", bookId = 18),
        Verse(book = "Jòb", chapter = 30, verseNumber = 5, text = "Kote yo pase moun mete yo deyò, yo rele bare dèyè yo tankou vòlè.", bookId = 18),
        Verse(book = "Jòb", chapter = 30, verseNumber = 6, text = "Yo te blije al rete nan twou wòch, nan twou tè sou bò ravin yo.", bookId = 18),
        Verse(book = "Jòb", chapter = 30, verseNumber = 7, text = "Y'ap rele tankou bèt mawon nan raje a. Yo fè pil sou pil nan savann lan.", bookId = 18),
        Verse(book = "Jòb", chapter = 30, verseNumber = 8, text = "Se te yon bann sanzave ki pa t' menm gen non. Yo te mete yo deyò nan peyi a.", bookId = 18),
        Verse(book = "Jòb", chapter = 30, verseNumber = 9, text = "Koulye a, y'ap fè chante sou mwen. Y'ap bay istwa sou do m'.", bookId = 18),
        Verse(book = "Jòb", chapter = 30, verseNumber = 10, text = "Yo pè pwoche bò kote m' pou m' pa sal yo. Yo menm krache nan figi m'.", bookId = 18),
        Verse(book = "Jòb", chapter = 30, verseNumber = 11, text = "Paske Bondye kraze kouraj mwen, li lage m' atè, kifè, mapou tonbe, kabrit manje fèy li.", bookId = 18),
        Verse(book = "Jòb", chapter = 30, verseNumber = 12, text = "Bann moun sa yo leve dèyè m', y'ap fè m' kouri. Yo lage dèyè m' pou yo pran m'.", bookId = 18),
        Verse(book = "Jòb", chapter = 30, verseNumber = 13, text = "Yo sènen m' toupatou pou yo ka fini avè m'. Pa gen pesonn pou di yo pa fè sa.", bookId = 18),
        Verse(book = "Jòb", chapter = 30, verseNumber = 14, text = "Yo pase nan fant barikad, yo tonbe sou mwen. Yo pilonnen m' anba pye yo.", bookId = 18),
        Verse(book = "Jòb", chapter = 30, verseNumber = 15, text = "Yon sèl latranblad pran mwen. Tankou yon kout van li kraze kouraj mwen. Tankou yon nwaj k'ap pase, tout byen m' yo disparèt.", bookId = 18),
        Verse(book = "Jòb", chapter = 30, verseNumber = 16, text = "Koulye a, mwen prèt pou m' mouri. Lafliksyon ap fini avè m'.", bookId = 18),
        Verse(book = "Jòb", chapter = 30, verseNumber = 17, text = "Lannwit, tout zo nan kò m' ap fè m' mal. Doulè ap manje m' anndan san rete.", bookId = 18),
        Verse(book = "Jòb", chapter = 30, verseNumber = 18, text = "Bondye ponyen m' nan kòlèt, l'ap chifonnen tout rad sou mwen.", bookId = 18),
        Verse(book = "Jòb", chapter = 30, verseNumber = 19, text = "Li voye m' jete nan labou. Mwen pa pi bon pase pousyè tè ak sann dife.", bookId = 18),
        Verse(book = "Jòb", chapter = 30, verseNumber = 20, text = "Mwen rele nan pye ou, Bondye! Ou pa reponn mwen. Mwen kanpe devan ou, ou pa okipe m' menm.", bookId = 18),
        Verse(book = "Jòb", chapter = 30, verseNumber = 21, text = "Ou pa menm moun lan ankò. W'ap malmennen m'. Ou soti pou pèsekite m' ak tout fòs ou.", bookId = 18),
        Verse(book = "Jòb", chapter = 30, verseNumber = 22, text = "Ou fè van pote m' ale. M'ap vole tankou pay. Ou voye yon van tanpèt boulvèse m'.", bookId = 18),
        Verse(book = "Jòb", chapter = 30, verseNumber = 23, text = "Wi, mwen konnen byen pwòp w'ap mennen m' pou m' al mouri, pou m' al sibi sò k'ap tann tout moun lan.", bookId = 18),
        Verse(book = "Jòb", chapter = 30, verseNumber = 24, text = "Poukisa w'ap atake yon moun ki tou fin mouri, yon moun ki pa ka fè anyen ankò pase mande padon?", bookId = 18),
        Verse(book = "Jòb", chapter = 30, verseNumber = 25, text = "Eske mwen pa t' nan lapenn ansanm ak moun ki te nan mizè? Eske kè m' pa t' fè m' mal pou moun ki pa t' gen anyen menm yo?", bookId = 18),
        Verse(book = "Jòb", chapter = 30, verseNumber = 26, text = "Mwen t'ap tann kontantman, se malè ki vini. Mwen t'ap tann limyè, se fènwa ki kouvri m'.", bookId = 18),
        Verse(book = "Jòb", chapter = 30, verseNumber = 27, text = "Tout zantray mwen ap bouyi san rete. Chak jou m'ap soufri pi rèd.", bookId = 18),
        Verse(book = "Jòb", chapter = 30, verseNumber = 28, text = "M'ap mache kagou, san pesonn pou konsole m'. Mwen kanpe nan mitan tout moun, m'ap mande sekou.", bookId = 18),
        Verse(book = "Jòb", chapter = 30, verseNumber = 29, text = "Vwa mwen tankou vwa koukou. Mwen rele tankou frize.", bookId = 18),
        Verse(book = "Jòb", chapter = 30, verseNumber = 30, text = "Po m' vin tou nwa, l'ap dekale. Lafyèb ap manje m' nan zo.", bookId = 18),
        Verse(book = "Jòb", chapter = 30, verseNumber = 31, text = "Lontan se mizik gita ak fif ase ki te nan zòrèy mwen. Men, koulye a, se plenn, se kriye ase m'ap tande.", bookId = 18),
        Verse(book = "Jòb", chapter = 31, verseNumber = 1, text = "Mwen te fè sèman pou m' pa janm gade yon jenn fi avèk move lide.", bookId = 18),
        Verse(book = "Jòb", chapter = 31, verseNumber = 2, text = "Kisa Bondye ki anwo a ap fè nou konsa? Kisa Bondye ki gen tout pouvwa a sere pou nou?", bookId = 18),
        Verse(book = "Jòb", chapter = 31, verseNumber = 3, text = "Li voye malè pou moun ki pa mache dwat. Li voye tribilasyon pou moun k'ap fè mechanste.", bookId = 18),
        Verse(book = "Jòb", chapter = 31, verseNumber = 4, text = "Eske Bondye pa konnen tou sa n'ap fè? Eske li pa wè tout vire tounen m'?", bookId = 18),
        Verse(book = "Jòb", chapter = 31, verseNumber = 5, text = "Eske mwen janm nan bay manti? Eske mwen janm chache twonpe moun?", bookId = 18),
        Verse(book = "Jòb", chapter = 31, verseNumber = 6, text = "Se pou Bondye peze m' nan bon balans li a. Se pou Bondye wè jan m' toujou mache dwat.", bookId = 18),
        Verse(book = "Jòb", chapter = 31, verseNumber = 7, text = "Si mwen janm pran chemen kwochi pou mwen, si mwen te kite lanvi anvayi kè m', si mwen janm mete men m' nan sa ki mal,", bookId = 18),
        Verse(book = "Jòb", chapter = 31, verseNumber = 8, text = "se pou lòt moun rekòlte sa mwen plante. Se pou yo rache tout ti plant k'ap pouse nan jaden m'.", bookId = 18),
        Verse(book = "Jòb", chapter = 31, verseNumber = 9, text = "Si mwen te kite yon lòt fanm pran tèt mwen, pou m' al kache devan pòt yon frè mwen ap veye,", bookId = 18),
        Verse(book = "Jòb", chapter = 31, verseNumber = 10, text = "se pou madanm mwen fè manje pou yon lòt gason. Se pou lòt gason kouche avè l'.", bookId = 18),
        Verse(book = "Jòb", chapter = 31, verseNumber = 11, text = "Se yon gwo bagay sal mwen ta fè la a. Se bagay pou yo ta touye m'.", bookId = 18),
        Verse(book = "Jòb", chapter = 31, verseNumber = 12, text = "Se ta tankou yon gwo dife mwen limen pou fini avè m' nèt. Li ta boule dènye sa m' genyen.", bookId = 18),
        Verse(book = "Jòb", chapter = 31, verseNumber = 13, text = "Lè domestik mwen osinon sèvant mwen gen kont avè m', si mwen ta refize mete rezon an kote l' ye a,", bookId = 18),
        Verse(book = "Jòb", chapter = 31, verseNumber = 14, text = "kisa mwen ta fè, lè Bondye parèt devan m'? Lè l'a mande m' kont, kisa m'a reponn li?", bookId = 18),
        Verse(book = "Jòb", chapter = 31, verseNumber = 15, text = "Menm Bondye ki fè m' nan vant manman m' lan, se li menm tou ki fè yo nan vant manman pa yo. Se li menm ki kreye nou tout.", bookId = 18),
        Verse(book = "Jòb", chapter = 31, verseNumber = 16, text = "Mwen pa janm refize ede yon pòv. Ni mwen pa janm kite vèv yo nan nesesite.", bookId = 18),
        Verse(book = "Jòb", chapter = 31, verseNumber = 17, text = "Mwen pa janm kite timoun san papa yo rete grangou pou m'ap manje manje m' pou kont mwen.", bookId = 18),
        Verse(book = "Jòb", chapter = 31, verseNumber = 18, text = "Okontrè, depi m' fèt, m' sèvi ak timoun sa yo tankou papa ak pitit. Depi m' soti nan vant manman m', m'ap pran swen vèv yo.", bookId = 18),
        Verse(book = "Jòb", chapter = 31, verseNumber = 19, text = "Lè m' jwenn yon malere toutouni osinon yon pòv endijan san yon bout dra,", bookId = 18),
        Verse(book = "Jòb", chapter = 31, verseNumber = 20, text = "mwen ba yo rad pou mete sou yo, mwen pran lenn sou do mouton m' pou m' ba yo chofe.", bookId = 18),
        Verse(book = "Jòb", chapter = 31, verseNumber = 21, text = "Si m' te janm aji mal ak yon timoun san papa paske mwen konnen y'a toujou ban m' rezon nan tribinal,", bookId = 18),
        Verse(book = "Jòb", chapter = 31, verseNumber = 22, text = "enben, se pou zepòl mwen dejwente, se pou de bra m' kase.", bookId = 18),
        Verse(book = "Jòb", chapter = 31, verseNumber = 23, text = "Paske, mwen pè jijman Bondye. Mwen pa ka kanpe devan l'.", bookId = 18),
        Verse(book = "Jòb", chapter = 31, verseNumber = 24, text = "Mwen pa janm mete konfyans mwen nan lò pou m' ta di se sa k'ap pwoteje m'.", bookId = 18),
        Verse(book = "Jòb", chapter = 31, verseNumber = 25, text = "Mwen pa janm vante tèt mwen dèske mwen gen anpil byen, dèske mwen fè anpil lajan ak men mwen.", bookId = 18),
        Verse(book = "Jòb", chapter = 31, verseNumber = 26, text = "Mwen pa janm adore solèy ak lalin lè yo klere byen bèl nan syèl la.", bookId = 18),
        Verse(book = "Jòb", chapter = 31, verseNumber = 27, text = "Mwen pa janm pèdi tèt mwen pou m' sèvi yo an kachèt.", bookId = 18),
        Verse(book = "Jòb", chapter = 31, verseNumber = 28, text = "Sa a tou, yo ta mèt touye m' si m' ta fè l', paske mwen ta nye Bondye ki gen tout pouvwa a.", bookId = 18),
        Verse(book = "Jòb", chapter = 31, verseNumber = 29, text = "Mwen pa janm kontan lè lènmi m' ap soufri. Mwen pa janm fè fèt lè malè tonbe sou yo.", bookId = 18),
        Verse(book = "Jòb", chapter = 31, verseNumber = 30, text = "Mwen pa janm kite bouch mwen chape pou m' ta ba yo madichon, pou m' ta rive mande lanmò pou yo.", bookId = 18),
        Verse(book = "Jòb", chapter = 31, verseNumber = 31, text = "Tout moun k'ap viv nan kay avè m' konnen mwen toujou byen resevwa tout moun lakay mwen.", bookId = 18),
        Verse(book = "Jòb", chapter = 31, verseNumber = 32, text = "Vwayajè pa janm dòmi deyò nan lari. Pòt kay mwen toujou louvri pou yo.", bookId = 18),
        Verse(book = "Jòb", chapter = 31, verseNumber = 33, text = "Mwen pa janm kache peche m' pou pesonn. Ni mwen pa janm fè sa ki mal an kachèt.", bookId = 18),
        Verse(book = "Jòb", chapter = 31, verseNumber = 34, text = "Mwen pa janm pè sa moun ap di. Mwen pa janm pè louvri bouch mwen ni pè mete pwent tèt mwen deyò, paske mwen ta pè pou moun pa lonje dwèt sou mwen.", bookId = 18),
        Verse(book = "Jòb", chapter = 31, verseNumber = 35, text = "Pa gen pesonn pou koute sa m'ap di la a? Mwen fin di sa pou m' di a. Koulye a, se Bondye ki pou reponn mwen. Si moun ki pa vle wè m' lan ta voye papye nan tribinal pou mwen,", bookId = 18),
        Verse(book = "Jòb", chapter = 31, verseNumber = 36, text = "mwen ta pote papye sa a sou zepòl mwen san ankenn wont. Mwen ta mare l' sou tèt mwen, tankou yon kouwòn.", bookId = 18),
        Verse(book = "Jòb", chapter = 31, verseNumber = 37, text = "Mwen ta di Bondye dènye sa mwen fè. Mwen ta kenbe tèt mwen dwat devan l'.", bookId = 18),
        Verse(book = "Jòb", chapter = 31, verseNumber = 38, text = "Si se vòlò mwen te vòlò tè m'ap travay la kifè koulye a tè a ap mande m' kont,", bookId = 18),
        Verse(book = "Jòb", chapter = 31, verseNumber = 39, text = "si mwen te manje rekòt jaden an san peye travayè yo kifè koulye a y'ap pote plent pou mwen,", bookId = 18),
        Verse(book = "Jòb", chapter = 31, verseNumber = 40, text = "enben, se pikan ak chadwon ki pou leve nan jaden m' kote ble ak lòj te konn pouse. Se konsa Jòb te fin pale.", bookId = 18),
        Verse(book = "Jòb", chapter = 32, verseNumber = 1, text = "Jòb te sitèlman sèten li te inonsan, twa mesye yo kite sa, yo pa chache reponn li ankò.", bookId = 18),
        Verse(book = "Jòb", chapter = 32, verseNumber = 2, text = "Men, Eliyou ki te kanpe la fè yon sèl kòlè. Eliyou sa a, se pitit Barakèl, moun fanmi Bouz, nan branch fanmi Ranm lan. Li fè yon sèl kòlè sou Jòb, paske Jòb t'ap bay tèt li rezon, li t'ap bay Bondye tò.", bookId = 18),
        Verse(book = "Jòb", chapter = 32, verseNumber = 3, text = "Li te ankòlè sou twa zanmi Jòb yo tou. Yo pa t' jwenn anyen pou yo reponn Jòb. Konsa, yo menm tou, se Bondye yo te bay tout tò a.", bookId = 18),
        Verse(book = "Jòb", chapter = 32, verseNumber = 4, text = "Antan yo twa a t'ap pale, Eliyou te rete la san di anyen, paske yo te pi gran pase l'.", bookId = 18),
        Verse(book = "Jòb", chapter = 32, verseNumber = 5, text = "Lè li wè mesye yo pa t' jwenn anyen ankò pou reponn Jòb, li fè yon sèl kòlè.", bookId = 18),
        Verse(book = "Jòb", chapter = 32, verseNumber = 6, text = "Li pran lapawòl, li di konsa: -Mwen menm, se jenn gason mwen ye. Nou menm, se granmoun nou ye. Se poutèt sa mwen te yon ti jan wont. Mwen te pè antre nan koze a.", bookId = 18),
        Verse(book = "Jòb", chapter = 32, verseNumber = 7, text = "Mwen t'ap di nan kè m': Kite granmoun pale! Kite sa ki gen laj sou tèt yo mete bon konprann yo deyò.", bookId = 18),
        Verse(book = "Jòb", chapter = 32, verseNumber = 8, text = "Men, pou di vre, se lespri Bondye ki gen tout pouvwa a sèl ki pou antre nan tèt yon moun pou ba li bon konprann!", bookId = 18),
        Verse(book = "Jòb", chapter = 32, verseNumber = 9, text = "Se pa laj ki bay moun bon konprann. Se pa cheve blan ki fè moun konnen sa ki dwat.", bookId = 18),
        Verse(book = "Jòb", chapter = 32, verseNumber = 10, text = "Koulye a, mwen ta renmen nou koute m'. Kite m' di nou sa m' konnen sou koze a.", bookId = 18),
        Verse(book = "Jòb", chapter = 32, verseNumber = 11, text = "Mwen tande byen tande tou sa nou di. Mwen te louvri zòrèy mwen gran louvri pou m' pa manke anyen nan pawòl nou yo, pandan n'ap chache mo pou nou di.", bookId = 18),
        Verse(book = "Jòb", chapter = 32, verseNumber = 12, text = "Mwen t'ap swiv sa n'ap di. Men, yonn nan nou pa rive fè Jòb fèmen bouch li. Nou yonn pa rive demanti msye.", bookId = 18),
        Verse(book = "Jòb", chapter = 32, verseNumber = 13, text = "Pa vin di m' nou konprann koulye a se Bondye ki pou reponn. Lèzòm pa kapab.", bookId = 18),
        Verse(book = "Jòb", chapter = 32, verseNumber = 14, text = "Se avè nou Jòb t'ap pale. Se pa avè m'. Konsa, mwen pral reponn msye yon lòt jan.", bookId = 18),
        Verse(book = "Jòb", chapter = 32, verseNumber = 15, text = "Jòb, ou wè mesye yo pa konn sa pou yo di ou. Yo pa jwenn anyen pou reponn ou ankò.", bookId = 18),
        Verse(book = "Jòb", chapter = 32, verseNumber = 16, text = "Mwen t'ap tann yo. Men, koulye a yo fèmen bouch yo. Yo sispann pale, yo pa reponn ou.", bookId = 18),
        Verse(book = "Jòb", chapter = 32, verseNumber = 17, text = "Atòkile, se mwen ki pral pale, mwen pral di ou sa m' konnen nan koze a.", bookId = 18),
        Verse(book = "Jòb", chapter = 32, verseNumber = 18, text = "Mwen plen pawòl nan bouch mwen. Si m' pa pale m'a toufe.", bookId = 18),
        Verse(book = "Jòb", chapter = 32, verseNumber = 19, text = "Pawòl ki nan tèt mwen, ou ta di yon diven k'ap fèmante. Li prèt pou pete veso kote l' ye a.", bookId = 18),
        Verse(book = "Jòb", chapter = 32, verseNumber = 20, text = "Se pou m' pale pou m' ka soulaje konsyans mwen. Se pou m' louvri bouch mwen reponn ou.", bookId = 18),
        Verse(book = "Jòb", chapter = 32, verseNumber = 21, text = "Mwen p'ap pran defans pyès moun. Mwen pa pral achte figi nou yonn la a.", bookId = 18),
        Verse(book = "Jòb", chapter = 32, verseNumber = 22, text = "Mwen pa konn flate moun. Lèfini, si m' ta fè sa, Bondye ki kreye m' lan ta disparèt mwen lapoula.", bookId = 18),
        Verse(book = "Jòb", chapter = 33, verseNumber = 1, text = "Atòkile, Jòb, tanpri, koute sa m'ap di ou. Louvri zòrèy ou byen pou ou tande m'.", bookId = 18),
        Verse(book = "Jòb", chapter = 33, verseNumber = 2, text = "M' pare pou m' di dènye sa ki vin nan bouch mwen.", bookId = 18),
        Verse(book = "Jòb", chapter = 33, verseNumber = 3, text = "M' pral di tou sa ki nan kè m'. Se verite a tou senp mwen pral pale.", bookId = 18),
        Verse(book = "Jòb", chapter = 33, verseNumber = 4, text = "Se lespri Bondye a ki fè m'. Se souf Bondye ki gen tout pouvwa a ki ban m' lavi.", bookId = 18),
        Verse(book = "Jòb", chapter = 33, verseNumber = 5, text = "Si ou kapab, w'a reponn mwen. Pare kò ou. Pran pozisyon batay ou avè m'.", bookId = 18),
        Verse(book = "Jòb", chapter = 33, verseNumber = 6, text = "Ou menm avè m', devan Bondye nou tout se menm. Nou tou de, se ak labou li fè nou.", bookId = 18),
        Verse(book = "Jòb", chapter = 33, verseNumber = 7, text = "Ou wè! Ou pa bezwen pè m'! Mwen pa ka fè ou anyen!", bookId = 18),
        Verse(book = "Jòb", chapter = 33, verseNumber = 8, text = "Mwen te tande ou ak de zòrèy mwen. Ki jan ou fè ka di:", bookId = 18),
        Verse(book = "Jòb", chapter = 33, verseNumber = 9, text = "Mwen menm, mwen inonsan. M' pa fè ankenn peche! M' pa gen anyen sou konsyans mwen.", bookId = 18),
        Verse(book = "Jòb", chapter = 33, verseNumber = 10, text = "Men, se Bondye ki pretann mwen ba l' jwen pou l' atake m'. Se li menm k'ap aji avè m' tankou si mwen te lènmi l'.", bookId = 18),
        Verse(book = "Jòb", chapter = 33, verseNumber = 11, text = "Li mete de pye m' nan sèp. L'ap veye tou sa m'ap fè.", bookId = 18),
        Verse(book = "Jòb", chapter = 33, verseNumber = 12, text = "La, Jòb monchè, m'ap reponn ou: ou antò. Paske Bondye pa kanmarad moun.", bookId = 18),
        Verse(book = "Jòb", chapter = 33, verseNumber = 13, text = "Poukisa w'ap chache Bondye kont konsa? Se paske li pa reponn lè w'ap plenyen nan pye l'?", bookId = 18),
        Verse(book = "Jòb", chapter = 33, verseNumber = 14, text = "Bondye pale divès jan. Men, pesonn pa okipe sa l'ap di.", bookId = 18),
        Verse(book = "Jòb", chapter = 33, verseNumber = 15, text = "Lè moun kouche nan kabann yo, lè yo fon nan dòmi lannwit, Bondye pale ak yo nan rèv, nan vizyon.", bookId = 18),
        Verse(book = "Jòb", chapter = 33, verseNumber = 16, text = "Li fè yo konnen sa li gen pou l' di yo. Li ba yo avètisman pou yo mache sou piga yo.", bookId = 18),
        Verse(book = "Jòb", chapter = 33, verseNumber = 17, text = "Li vle pou yo kite move chemen y'ap swiv la, pou yo pa kite lògèy vire tèt yo.", bookId = 18),
        Verse(book = "Jòb", chapter = 33, verseNumber = 18, text = "Konsa, yo p'ap mouri. Y'a sove lavi yo.", bookId = 18),
        Verse(book = "Jòb", chapter = 33, verseNumber = 19, text = "Bondye avèti moun tou lè li voye maladi sou yo. Li ba yo doulè nan tout kò yo.", bookId = 18),
        Verse(book = "Jòb", chapter = 33, verseNumber = 20, text = "Li bay yo degoutans manje. Yo pèdi anvi manje menm lò manje a gou.", bookId = 18),
        Verse(book = "Jòb", chapter = 33, verseNumber = 21, text = "Y'ap depafini, tout moun wè jan y'ap vin mèg. Tout zo nan kò yo griyen.", bookId = 18),
        Verse(book = "Jòb", chapter = 33, verseNumber = 22, text = "Sa ki rete pou yo mouri a, pou y' ale nan peyi san chapo a pa anyen.", bookId = 18),
        Verse(book = "Jòb", chapter = 33, verseNumber = 23, text = "Lè sa a, yon zanj Bondye ka vin bò kote l', yonn nan milyonven zanj Bondye yo ki la pou fè moun chonje devwa yo.", bookId = 18),
        Verse(book = "Jòb", chapter = 33, verseNumber = 24, text = "Zanj lan va gen pitye pou li. L'a di Bondye: -Tanpri, pa kite l' mouri. M'ap peye pou sove lavi li.", bookId = 18),
        Verse(book = "Jòb", chapter = 33, verseNumber = 25, text = "Kò li va refè, l'a vin fre tankou lè l' te jenn.", bookId = 18),
        Verse(book = "Jòb", chapter = 33, verseNumber = 26, text = "Li lapriyè Bondye, Bondye reponn li. li al adore Bondye ak kè kontan. Bondye padonnen l' devan tout moun.", bookId = 18),
        Verse(book = "Jòb", chapter = 33, verseNumber = 27, text = "L'ap mache bay Bondye lwanj toupatou. L'ap di: -Mwen te peche, mwen te fè sa ki mal. Men, Bondye pa fè m' peye pou sa m' te fè a.", bookId = 18),
        Verse(book = "Jòb", chapter = 33, verseNumber = 28, text = "Li egzante m' lanmò. Li ban m' lavi ankò.", bookId = 18),
        Verse(book = "Jòb", chapter = 33, verseNumber = 29, text = "Men tou sa Bondye ap fè, de fwa, twa fwa pou lèzòm,", bookId = 18),
        Verse(book = "Jòb", chapter = 33, verseNumber = 30, text = "pou l' pa kite yo mouri, pou l' ba yo lavi ak kè kontan.", bookId = 18),
        Verse(book = "Jòb", chapter = 33, verseNumber = 31, text = "Koulye a, Jòb, louvri zòrèy ou! Koute byen sa m'ap di! Pe bouch ou la! Kite m' fin pale!", bookId = 18),
        Verse(book = "Jòb", chapter = 33, verseNumber = 32, text = "Men, si ou gen kichòy ou vle di, pale; m'ap koute ou. Paske mwen ta vle ba ou rezon.", bookId = 18),
        Verse(book = "Jòb", chapter = 33, verseNumber = 33, text = "Osinon, pe bouch ou, koute m' pito! Kite m' moutre ou sa ki rele gen bon konprann.", bookId = 18),
        Verse(book = "Jòb", chapter = 34, verseNumber = 1, text = "Eliyou pran lapawòl ankò. Li di konsa:", bookId = 18),
        Verse(book = "Jòb", chapter = 34, verseNumber = 2, text = "-Nou menm moun lespri yo, koute sa m'ap di nou! Nèg save yo, louvri zòrèy nou!", bookId = 18),
        Verse(book = "Jòb", chapter = 34, verseNumber = 3, text = "Zòrèy konnen lè pawòl bèl menm jan bouch konnen lè manje gou.", bookId = 18),
        Verse(book = "Jòb", chapter = 34, verseNumber = 4, text = "Annou wè kote jistis la ye. Ann mete rezon an kote pou l' ye a.", bookId = 18),
        Verse(book = "Jòb", chapter = 34, verseNumber = 5, text = "Jòb pretann li nan dwa li, se Bondye ki derefize rann li jistis.", bookId = 18),
        Verse(book = "Jòb", chapter = 34, verseNumber = 6, text = "Li di: Si m' di m' antò, se manti m'ap bay. Mwen malad pou m' mouri. Men, m' pa fè anyen ki mal.", bookId = 18),
        Verse(book = "Jòb", chapter = 34, verseNumber = 7, text = "Ou janm jwenn yon moun tankou Jòb? L'ap pase verite Bondye a nan betiz alèz tankou si se dlo l'ap bwè.", bookId = 18),
        Verse(book = "Jòb", chapter = 34, verseNumber = 8, text = "Li fè bann ak moun k'ap fè mechanste yo. L'ap pwonmennen ansanm ak malveyan yo.", bookId = 18),
        Verse(book = "Jòb", chapter = 34, verseNumber = 9, text = "Se li menm menm ki di ak bouch li: Sa pa rapòte anyen, lè yon moun ap chache fè volonte Bondye.", bookId = 18),
        Verse(book = "Jòb", chapter = 34, verseNumber = 10, text = "Nou menm ki gen lespri, koute sa m'ap di. Bondye pa ka fè mechanste. Bondye ki gen tout pouvwa a pa ka nan patipri.", bookId = 18),
        Verse(book = "Jòb", chapter = 34, verseNumber = 11, text = "Li bay chak moun sa yo merite dapre sa yo fè. Li aji ak yo dapre jan yo mennen bak yo.", bookId = 18),
        Verse(book = "Jòb", chapter = 34, verseNumber = 12, text = "Non! Bondye pa janm fè sa ki mal. Bondye ki gen tout pouvwa a pa nan paspouki.", bookId = 18),
        Verse(book = "Jòb", chapter = 34, verseNumber = 13, text = "Se pa yon lòt moun ki te bay Bondye pouvwa pou l' gouvènen latè, ni se pa yon lòt moun ki te mete tou sa ki egziste sou kont li.", bookId = 18),
        Verse(book = "Jòb", chapter = 34, verseNumber = 14, text = "-(we vèsè pwochen)", bookId = 18),
        Verse(book = "Jòb", chapter = 34, verseNumber = 15, text = "Si Bondye te kenbe souf ki bay lavi a pou tèt li, yon sèl kou a, bèt kou moun ta mouri. Yo ta tounen pousyè tè ankò.", bookId = 18),
        Verse(book = "Jòb", chapter = 34, verseNumber = 16, text = "Si nou gen bon konprann, koute sa byen. Louvri zòrèy nou pou nou tande sa m'ap di.", bookId = 18),
        Verse(book = "Jòb", chapter = 34, verseNumber = 17, text = "Eske n'ap kondannen Bondye ki gen tout pouvwa a, epi k'ap rann jistis la? Eske yon moun ki pa vle wè jistis ka gouvènen?", bookId = 18),
        Verse(book = "Jòb", chapter = 34, verseNumber = 18, text = "Bondye pini wa yo lè yo fè sa ki mal. Li pini gwo chèf yo lè yo fè mechanste.", bookId = 18),
        Verse(book = "Jòb", chapter = 34, verseNumber = 19, text = "Li pa nan achte figi chèf yo. Ou te mèt pòv, ou te mèt rich, pa gen diferans pou li, paske se li menm ki fè yo tout.", bookId = 18),
        Verse(book = "Jòb", chapter = 34, verseNumber = 20, text = "Yo rete konsa yo mouri, yo ale nan mitan lannwit. Pèp la annik souke kò l', yo disparèt. Bondye touye gwo chèf yo san li pa leve ti dwèt li.", bookId = 18),
        Verse(book = "Jòb", chapter = 34, verseNumber = 21, text = "L'ap veye tout vire tounen lèzòm. L'ap gade tout kote y'ap mete pye yo.", bookId = 18),
        Verse(book = "Jòb", chapter = 34, verseNumber = 22, text = "Pa gen ankenn fènwa, ni ankenn lonbray ki ka anpeche l' wè sa mechan yo ap fè.", bookId = 18),
        Verse(book = "Jòb", chapter = 34, verseNumber = 23, text = "Li pa bezwen voye manda bay moun pou yo prezante devan l' pou l' jije yo.", bookId = 18),
        Verse(book = "Jòb", chapter = 34, verseNumber = 24, text = "Li pa bezwen nan chache konnen pou l' kraze chèf yo, lèfini pou l' mete lòt moun nan plas yo.", bookId = 18),
        Verse(book = "Jòb", chapter = 34, verseNumber = 25, text = "Paske li konnen dènye sa yo fè. Yon jou lannwit konsa, li desann yo li pilonnen yo anba pye l'.", bookId = 18),
        Verse(book = "Jòb", chapter = 34, verseNumber = 26, text = "Li souflete yo tankou malfektè nan mitan lari pou tout moun ka wè.", bookId = 18),
        Verse(book = "Jòb", chapter = 34, verseNumber = 27, text = "Paske yo te vire do ba li, yo te fè tankou yo pa konnen lòd li bay yo.", bookId = 18),
        Verse(book = "Jòb", chapter = 34, verseNumber = 28, text = "Yo fè, yo fè jouk pòv yo rele mande Bondye sekou, jouk Bondye tande jan piti yo ap rele anba men yo.", bookId = 18),
        Verse(book = "Jòb", chapter = 34, verseNumber = 29, text = "Men, si Bondye rete san l' pa fè anyen, ki moun ki ka di l' kichòy? Si li kache kò li, ki moun ki ka wè l'! Men, pa pè! L'ap veye sou tout moun nan tout peyi.", bookId = 18),
        Verse(book = "Jòb", chapter = 34, verseNumber = 30, text = "Li p'ap kite move chèf gouvènen yo, li p'ap kite yo tann pèlen pou pèp la.", bookId = 18),
        Verse(book = "Jòb", chapter = 34, verseNumber = 31, text = "Men, si yon mechan pale ak Bondye, si li di l': -Wi, mwen te fè sa ki mal. Mwen p'ap fè sa ankò.", bookId = 18),
        Verse(book = "Jòb", chapter = 34, verseNumber = 32, text = "Tanpri. Louvri je m'. Fe m' wè sa m' fè a. Si mwen te aji ak mechanste, mwen p'ap rekonmanse ankò.", bookId = 18),
        Verse(book = "Jòb", chapter = 34, verseNumber = 33, text = "Dapre ou, Jòb, èske se pou Bondye pini l'? Mwen mande ou sa paske m' konnen ou pa dakò ak sa Bondye fè a. Men, se ou menm ki pou deside. Pa mwen menm. Manyè di m' sa ki nan kè ou.", bookId = 18),
        Verse(book = "Jòb", chapter = 34, verseNumber = 34, text = "Moun lespri ansanm ak moun bon konprann k'ap koute m' yo va di m' konsa:", bookId = 18),
        Verse(book = "Jòb", chapter = 34, verseNumber = 35, text = "Jòb ap pale anpil, men li pa konn sa l'ap di. Tou sa l'ap di yo pa gen ni pye ni tèt.", bookId = 18),
        Verse(book = "Jòb", chapter = 34, verseNumber = 36, text = "Egzaminen byen tou sa Jòb di la a. N'a wè li pale tankou yon moun ki mechan nan kè l'.", bookId = 18),
        Verse(book = "Jòb", chapter = 34, verseNumber = 37, text = "Li fin fè kont peche l', koulye a l'ap kenbe tèt ak Bondye. L'ap seye fè nou konprann li pa antò. L'ap plede fè Bondye remontrans.", bookId = 18),
        Verse(book = "Jòb", chapter = 35, verseNumber = 1, text = "Eliyou pran lapawòl ankò, li di:", bookId = 18),
        Verse(book = "Jòb", chapter = 35, verseNumber = 2, text = "-Pa konprann ou gen rezon lè w'ap di ou inonsan devan Bondye,", bookId = 18),
        Verse(book = "Jòb", chapter = 35, verseNumber = 3, text = "lè w'ap di Bondye: Ki mele ou sa? M' te mèt peche, sa pa fè ou anyen.", bookId = 18),
        Verse(book = "Jòb", chapter = 35, verseNumber = 4, text = "Enben. Mwen pral reponn ou, ni ou ni zanmi ou yo.", bookId = 18),
        Verse(book = "Jòb", chapter = 35, verseNumber = 5, text = "Gade syèl la! Ou wè jan nwaj yo wo anwo tèt ou!", bookId = 18),
        Verse(book = "Jòb", chapter = 35, verseNumber = 6, text = "Si ou fè peche, sa pa fè Bondye anyen! Ou te mèt fè peche sou peche, sa pa di l' anyen?", bookId = 18),
        Verse(book = "Jòb", chapter = 35, verseNumber = 7, text = "Si ou mache dwat, ki avantaj Bondye jwenn nan sa? Kisa ou ba li la a?", bookId = 18),
        Verse(book = "Jòb", chapter = 35, verseNumber = 8, text = "Se moun parèy ou ki soufri lè ou fè sa ki mal. Se yo ki pwofite tou lè ou fè sa ki dwat.", bookId = 18),
        Verse(book = "Jòb", chapter = 35, verseNumber = 9, text = "Lè moun ap sibi anba ponyèt lòt moun, yo plenyen. Lè se chèf k'ap peze yo, yo rele.", bookId = 18),
        Verse(book = "Jòb", chapter = 35, verseNumber = 10, text = "Men, yo pa vire kote Bondye ki kreye yo a. Yo te mèt nan nenpòt gwo lapenn, se li menm k'ap ba yo kouraj.", bookId = 18),
        Verse(book = "Jòb", chapter = 35, verseNumber = 11, text = "Yo pa vire kote Bondye ki ba yo plis lespri pase bèt nan bwa, plis bon konprann pase zwezo nan syèl la.", bookId = 18),
        Verse(book = "Jòb", chapter = 35, verseNumber = 12, text = "Yo rele kont rele yo, Bondye pa reponn yo, paske mechan yo gen lògèy.", bookId = 18),
        Verse(book = "Jòb", chapter = 35, verseNumber = 13, text = "Se pou gremesi y'ap plede rele konsa. Bondye pa tande, li pa wè.", bookId = 18),
        Verse(book = "Jòb", chapter = 35, verseNumber = 14, text = "Jòb monchè, ou di ou pa ka wè Bondye. Men, ou mete ka ou devan li.", bookId = 18),
        Verse(book = "Jòb", chapter = 35, verseNumber = 15, text = "Ou di ankò: Bondye pa nan pini. Mwen te mèt peche, sa pa di l' anyen.", bookId = 18),
        Verse(book = "Jòb", chapter = 35, verseNumber = 16, text = "Jòb monchè, w'ap louvri bouch ou pou ou pa di anyen. W'ap fè tout pale anpil sa a paske ou pa konn sa w'ap di.", bookId = 18),
        Verse(book = "Jòb", chapter = 36, verseNumber = 1, text = "Eliyou pran pale ankò, li di konsa:", bookId = 18),
        Verse(book = "Jòb", chapter = 36, verseNumber = 2, text = "-Pran yon ti pasyans. Kite m' fè yon ti pale ankò, paske m' poko fin di sa m' gen pou m' di pou pran defans Bondye.", bookId = 18),
        Verse(book = "Jòb", chapter = 36, verseNumber = 3, text = "Mwen pral sèvi ak tou sa mwen konnen pou m' moutre ou se Bondye ki kreye m' lan ki gen rezon.", bookId = 18),
        Verse(book = "Jòb", chapter = 36, verseNumber = 4, text = "Mwen p'ap bay manti nan sa m'ap di la a. Se yon nonm ki gen anpil konesans k'ap pale avè ou la a.", bookId = 18),
        Verse(book = "Jòb", chapter = 36, verseNumber = 5, text = "Bondye gen pouvwa. Li pa meprize pesonn. Pa gen anyen li pa konprann.", bookId = 18),
        Verse(book = "Jòb", chapter = 36, verseNumber = 6, text = "Li p'ap kite mechan yo viv lontan. Li toujou aji ak pòv yo san patipri.", bookId = 18),
        Verse(book = "Jòb", chapter = 36, verseNumber = 7, text = "Li defann kòz moun ki mache dwat yo. Li mete yo chèf pou yo gouvènen tankou wa. Toutan tout moun ap pale byen pou yo.", bookId = 18),
        Verse(book = "Jòb", chapter = 36, verseNumber = 8, text = "Men, si Bondye mete yo nan chenn, si lafliksyon makònen nan tout kò yo,", bookId = 18),
        Verse(book = "Jòb", chapter = 36, verseNumber = 9, text = "Bondye va louvri je yo pou yo ka wè tou sa y'ap fè a. Li moutre yo se lògèy k'ap fè yo fè peche.", bookId = 18),
        Verse(book = "Jòb", chapter = 36, verseNumber = 10, text = "Li pale nan zòrèy yo pou avèti yo. Li mande yo pou yo sispann fè sa ki mal.", bookId = 18),
        Verse(book = "Jòb", chapter = 36, verseNumber = 11, text = "Si yo koute Bondye, si yo soumèt devan li, y'a viv rès lavi yo nan kè kontan ak nan plezi.", bookId = 18),
        Verse(book = "Jòb", chapter = 36, verseNumber = 12, text = "Si se pa sa, y'ap rete konsa y'ap mouri. Y'ap desann kote mò yo ye a san yo pa konnen.", bookId = 18),
        Verse(book = "Jòb", chapter = 36, verseNumber = 13, text = "Men, mechan yo ap fè tèt di. Yo fache pi rèd. Yo te mèt anba kou, yo p'ap mande sekou.", bookId = 18),
        Verse(book = "Jòb", chapter = 36, verseNumber = 14, text = "Yo jenn gason toujou, yo gen tan mouri. Yo t'ap mennen yon lavi dezòd.", bookId = 18),
        Verse(book = "Jòb", chapter = 36, verseNumber = 15, text = "Men, Bondye pran soufrans lan, li sèvi avè l' pou li moutre lèzòm anpil bagay. Se lè yo anba tray, li louvri lespri yo.", bookId = 18),
        Verse(book = "Jòb", chapter = 36, verseNumber = 16, text = "Ou menm tou, Bondye vle wete ou nan gwo lapenn sa a, pou ou ka rive gen jwisans san moun pa chache ou kont. Te gen yon lè tab ou te chaje ak bon manje.", bookId = 18),
        Verse(book = "Jòb", chapter = 36, verseNumber = 17, text = "Lè sa a, ou te fè menm lide ak mechan yo. Koulye a, yo pral pini ou jan ou merite l' la.", bookId = 18),
        Verse(book = "Jòb", chapter = 36, verseNumber = 18, text = "Veye zo ou! Pa kite richès vire tèt ou ankò! Pa kite yo achte ou ak lajan osinon ak gwo kado!", bookId = 18),
        Verse(book = "Jòb", chapter = 36, verseNumber = 19, text = "Se pou ou jije tout moun, rich kou pòv, gwonèg la tankou nèg fèb la.", bookId = 18),
        Verse(book = "Jòb", chapter = 36, verseNumber = 20, text = "Pa kraze moun ki pa anyen pou ou pou mete fanmi ou nan plas yo.", bookId = 18),
        Verse(book = "Jòb", chapter = 36, verseNumber = 21, text = "Atansyon pou ou pa fè sa ki mal. Se pou sa menm w'ap soufri konsa.", bookId = 18),
        Verse(book = "Jòb", chapter = 36, verseNumber = 22, text = "Gade jan Bondye gen anpil pouvwa. Pa gen pi gran mèt pase l'.", bookId = 18),
        Verse(book = "Jòb", chapter = 36, verseNumber = 23, text = "Pesonn pa ka di Bondye sa pou l' fè. Pesonn pa ka di l' sa l' fè a mal.", bookId = 18),
        Verse(book = "Jòb", chapter = 36, verseNumber = 24, text = "Se pou ou fè lwanj travay li pito, tankou tout moun toujou fè l' la.", bookId = 18),
        Verse(book = "Jòb", chapter = 36, verseNumber = 25, text = "Se bèl bagay pou tout moun wè. Yo rete byen lwen, y'ap gade.", bookId = 18),
        Verse(book = "Jòb", chapter = 36, verseNumber = 26, text = "Wi. Nou p'ap janm ka fin konprann jan Bondye gen pouvwa! Nou p'ap janm ka fin konnen depi kilè Bondye la.", bookId = 18),
        Verse(book = "Jòb", chapter = 36, verseNumber = 27, text = "Se li menm ki rale dlo sou latè, ki fè l' tounen vapè nan nwaj yo pou bay lapli.", bookId = 18),
        Verse(book = "Jòb", chapter = 36, verseNumber = 28, text = "Lèfini, li kite lapli soti nan syèl la tonbe sou tout moun sou latè.", bookId = 18),
        Verse(book = "Jòb", chapter = 36, verseNumber = 29, text = "Pesonn pa konnen ki jan nwaj yo fè deplase, ki jan loraj fè gwonde nan syèl kote Bondye rete a.", bookId = 18),
        Verse(book = "Jòb", chapter = 36, verseNumber = 30, text = "Li kouvri syèl la ak nwaj yo. Li kouvri tout tèt mòn yo.", bookId = 18),
        Verse(book = "Jòb", chapter = 36, verseNumber = 31, text = "Se konsa li bay pèp la manje. Li ba yo manje an kantite.", bookId = 18),
        Verse(book = "Jòb", chapter = 36, verseNumber = 32, text = "Li kenbe zèklè yo nan pla men li. Li bay lòd pou loraj tonbe kote li menm li vize a.", bookId = 18),
        Verse(book = "Jòb", chapter = 36, verseNumber = 33, text = "Loraj la anonse move tan. Ata bèt yo santi move tan an ap vini.", bookId = 18),
        Verse(book = "Jòb", chapter = 37, verseNumber = 1, text = "Lè konsa, kè m' ap bat. M' santi l'ap rache.", bookId = 18),
        Verse(book = "Jòb", chapter = 37, verseNumber = 2, text = "Nou tout, koute vwa Bondye! Koute jan l'ap gwonde!", bookId = 18),
        Verse(book = "Jòb", chapter = 37, verseNumber = 3, text = "Zèklè a kouri nan tout syèl la. Li klere dènye bout latè.", bookId = 18),
        Verse(book = "Jòb", chapter = 37, verseNumber = 4, text = "Apre sa, yo tande vwa li ap gwonde. Loraj la gwonde avèk fòs. Lè konsa, zèklè fè mikalaw.", bookId = 18),
        Verse(book = "Jòb", chapter = 37, verseNumber = 5, text = "Lè Bondye ap pale konsa, li fè bèl bagay, bagay nou pa ka konprann.", bookId = 18),
        Verse(book = "Jòb", chapter = 37, verseNumber = 6, text = "Li bay lanèj lòd kouvri latè. Li bay gwo lapli lòd tonbe.", bookId = 18),
        Verse(book = "Jòb", chapter = 37, verseNumber = 7, text = "Li fè tout moun sispann travay. Li fè yo wè sa se travay pa l'.", bookId = 18),
        Verse(book = "Jòb", chapter = 37, verseNumber = 8, text = "Tout bèt antre nan twou. Y' al kache kò yo nan nich.", bookId = 18),
        Verse(book = "Jòb", chapter = 37, verseNumber = 9, text = "Van tanpèt soti nan sid. Van frèt soti nan nò.", bookId = 18),
        Verse(book = "Jòb", chapter = 37, verseNumber = 10, text = "Souf Bondye fè dlo tounen glas. Konsa, tout dlo tounen glas.", bookId = 18),
        Verse(book = "Jòb", chapter = 37, verseNumber = 11, text = "Zèklè yo ap fè yan nan nwaj yo. Nwaj yo klere byen lwen.", bookId = 18),
        Verse(book = "Jòb", chapter = 37, verseNumber = 12, text = "Bondye fè yo vire nan syèl la jan li vle. Yo fè tou sa li ba yo lòd fè toupatou sou latè.", bookId = 18),
        Verse(book = "Jòb", chapter = 37, verseNumber = 13, text = "Bondye voye lapli pou wouze latè. Li voye l' pou pini moun, li voye l' pou beni yo tou.", bookId = 18),
        Verse(book = "Jòb", chapter = 37, verseNumber = 14, text = "Louvri zòrèy ou, Jòb, pou ou tande sa m' pral di la a. Pran tèt ou, egzaminen bèl travay Bondye yo byen.", bookId = 18),
        Verse(book = "Jòb", chapter = 37, verseNumber = 15, text = "Eske ou konnen ki jan Bondye ba yo lòd, ki jan li fè zèklè yo klere nan nwaj yo?", bookId = 18),
        Verse(book = "Jòb", chapter = 37, verseNumber = 16, text = "Eske ou konnen ki jan nwaj yo fè flote nan syèl la? Sa se yon bèl bagay. Pou ou fè l' fòk ou gen anpil ladrès.", bookId = 18),
        Verse(book = "Jòb", chapter = 37, verseNumber = 17, text = "Lè van cho ki soti nan sid la ap kwit tè a, ou santi rad sou ou ap boule tout kò ou.", bookId = 18),
        Verse(book = "Jòb", chapter = 37, verseNumber = 18, text = "Eske ou ka ede Bondye louvri nwaj yo nan syèl la, pou fè yo di tankou bout fè?", bookId = 18),
        Verse(book = "Jòb", chapter = 37, verseNumber = 19, text = "Fè m' konnen sa pou nou di Bondye. Lespri nou vid. Nou pa gen anyen pou nou di l'.", bookId = 18),
        Verse(book = "Jòb", chapter = 37, verseNumber = 20, text = "Mwen pa mande pou m' pale ak Bondye. Poukisa pou m' ba li okazyon pou li touye m'?", bookId = 18),
        Verse(book = "Jòb", chapter = 37, verseNumber = 21, text = "Ou rete konsa ou pa wè solèy la. Li kache anba nwaj yo. Yon van leve, li fè solèy la klere ankò.", bookId = 18),
        Verse(book = "Jòb", chapter = 37, verseNumber = 22, text = "Yon bèl klète, klere kou lò, parèt sou bò nò. Nou wè Bondye kanpe nan mitan yon bèl limyè ki fè nou pè.", bookId = 18),
        Verse(book = "Jòb", chapter = 37, verseNumber = 23, text = "Nou pa ka pwoche bò kote Bondye ki gen tout pouvwa a. Li sèl gwo chèf, li sèl jij, li pa nan patipri. Li p'ap kondannen yon moun ki inonsan.", bookId = 18),
        Verse(book = "Jòb", chapter = 37, verseNumber = 24, text = "Se poutèt sa, tout moun fèt pou gen krentif pou li. Li p'ap okipe moun ki pretann yo gen bon konprann.", bookId = 18),
        Verse(book = "Jòb", chapter = 38, verseNumber = 1, text = "Lè sa a, nan yon gwo van tanpèt, Seyè a pale ak Jòb. Li di l' konsa:", bookId = 18),
        Verse(book = "Jòb", chapter = 38, verseNumber = 2, text = "-Kisa ou ye menm pou w'ap poze keksyon sou plan travay mwen ak yon bann diskou ki pa vle di anyen?", bookId = 18),
        Verse(book = "Jòb", chapter = 38, verseNumber = 3, text = "Mete gason sou ou! M' pral poze ou keksyon. Pare kò ou pou ou reponn mwen.", bookId = 18),
        Verse(book = "Jòb", chapter = 38, verseNumber = 4, text = "Kote ou te ye lè m' t'ap fè latè? Se pou ou reponn mwen si ou konn tout bagay!", bookId = 18),
        Verse(book = "Jòb", chapter = 38, verseNumber = 5, text = "Ki moun ki te deside lajè l'ap genyen? Ki moun ki te pran mezi l'? Eske ou konn sa?", bookId = 18),
        Verse(book = "Jòb", chapter = 38, verseNumber = 6, text = "Sou kisa fondasyon latè chita? Ki moun ki te poze wòch ki kenbe l' la?", bookId = 18),
        Verse(book = "Jòb", chapter = 38, verseNumber = 7, text = "Jou maten sa a, tout zetwal yo t'ap chante, tout sèvitè Bondye yo t'ap bat bravo.", bookId = 18),
        Verse(book = "Jòb", chapter = 38, verseNumber = 8, text = "Ki moun ki fèmen pòtay pou bare lanmè a, lè li pete soti nan vant latè a?", bookId = 18),
        Verse(book = "Jòb", chapter = 38, verseNumber = 9, text = "Lè mwen kouvri lanmè a ak nwaj, lè mwen vlope l' nan gwo nwaj nwa yo,", bookId = 18),
        Verse(book = "Jòb", chapter = 38, verseNumber = 10, text = "mwen bay lanmè a bòn li. Mwen mete pòt avèk kle pou kenbe l' nan plas li.", bookId = 18),
        Verse(book = "Jòb", chapter = 38, verseNumber = 11, text = "Mwen di l': Men limit ou. Pa depase l'. Se la m'ap kraze fòs lanm ou yo.", bookId = 18),
        Verse(book = "Jòb", chapter = 38, verseNumber = 12, text = "Jòb, èske yon sèl fwa ou janm bay lòd pou maten rive? Ou janm bay lè pou bajou kase?", bookId = 18),
        Verse(book = "Jòb", chapter = 38, verseNumber = 13, text = "Eske ou janm bay devanjou l' lòd pou l' klere sou tout latè, l' pou l' fè mechan yo soti nan twou yo?", bookId = 18),
        Verse(book = "Jòb", chapter = 38, verseNumber = 14, text = "Lè sa a, tout mòn yo ak tout fon yo parèt aklè, tankou mak pye bèt nan labou. Yo pran koulè yo, ou ta di yon rad latè mete sou li.", bookId = 18),
        Verse(book = "Jòb", chapter = 38, verseNumber = 15, text = "Limyè solèy la antrave mechan yo nan travay yo. Yo blije kite mechanste yo te pare pou fè a.", bookId = 18),
        Verse(book = "Jòb", chapter = 38, verseNumber = 16, text = "Eske ou te desann jouk kote sous lanmè a pete a? Eske ou te mache nan fon lanmè a?", bookId = 18),
        Verse(book = "Jòb", chapter = 38, verseNumber = 17, text = "Eske yo te janm moutre ou pòtay peyi lanmò a? Eske ou te janm wè pòt ki louvri sou gwo twou san fon an?", bookId = 18),
        Verse(book = "Jòb", chapter = 38, verseNumber = 18, text = "Eske ou gen lide ki lajè latè a genyen? Reponn mwen non, si ou konnen!", bookId = 18),
        Verse(book = "Jòb", chapter = 38, verseNumber = 19, text = "Eske ou konnen ki bò limyè soti, ki bò fènwa rete,", bookId = 18),
        Verse(book = "Jòb", chapter = 38, verseNumber = 20, text = "pou ou ka moutre yo jouk ki bò pou yo ale, osinon pou ou voye yo tounen lakay yo?", bookId = 18),
        Verse(book = "Jòb", chapter = 38, verseNumber = 21, text = "Si ou konn sa, enben, ou te fèt deja lè mwen t'ap kreye yo a. Ou pa manke gen laj sou tèt ou!", bookId = 18),
        Verse(book = "Jòb", chapter = 38, verseNumber = 22, text = "Eske ou janm rive kote yo fè depo lanèj lan? Ou janm wè depo lagrèl la?", bookId = 18),
        Verse(book = "Jòb", chapter = 38, verseNumber = 23, text = "Ou konnen depo kote m' sere yo pou lè gen move tan, pou lè batay ak lagè ap fèt?", bookId = 18),
        Verse(book = "Jòb", chapter = 38, verseNumber = 24, text = "Ou konnen ki bò solèy la leve, ki bò van lès la soti pou l' soufle sou latè?", bookId = 18),
        Verse(book = "Jòb", chapter = 38, verseNumber = 25, text = "Ou konnen ki moun ki fè wout bay lapli tonbe, ki moun ki fè chemen pou loraj la,", bookId = 18),
        Verse(book = "Jòb", chapter = 38, verseNumber = 26, text = "pou lapli tonbe sou dezè a kote moun pa rete,", bookId = 18),
        Verse(book = "Jòb", chapter = 38, verseNumber = 27, text = "pou wouze tè sèk k'ap fann nan solèy, pou fè zèb pouse nan savann?", bookId = 18),
        Verse(book = "Jòb", chapter = 38, verseNumber = 28, text = "Eske lapli a gen papa? Ki moun ki fè lawouze?", bookId = 18),
        Verse(book = "Jòb", chapter = 38, verseNumber = 29, text = "Ki bò moso glas yo soti? Lagrèl ki soti nan syèl la, ki moun ki manman l'?", bookId = 18),
        Verse(book = "Jòb", chapter = 38, verseNumber = 30, text = "Se yo menm ki fè dlo vin di kou wòch, ki fè tout dlo anwo lanmè a di kou wòch?", bookId = 18),
        Verse(book = "Jòb", chapter = 38, verseNumber = 31, text = "Ou ka mare zetwal Lapousiyè yo ansanm? Ou ka lage kòd ki kenbe zetwal Oryon yo ansanm?", bookId = 18),
        Verse(book = "Jòb", chapter = 38, verseNumber = 32, text = "Ou ka mennen zetwal yo soti lè lè yo rive? Ou ka bay Gwo Kabwèt la ak Ti Kabwèt la direksyon pou yo pran?", bookId = 18),
        Verse(book = "Jòb", chapter = 38, verseNumber = 33, text = "Ou konnen lwa k'ap gouvènen tout bagay nan syèl la? Eske ou ka sèvi ak lwa sa yo pou gouvènen sa k'ap pase sou latè?", bookId = 18),
        Verse(book = "Jòb", chapter = 38, verseNumber = 34, text = "Eske ou ka bay nwaj yo lòd pou yo voye gwo lapli sou ou?", bookId = 18),
        Verse(book = "Jòb", chapter = 38, verseNumber = 35, text = "Si ou bay zèklè yo lòd pou yo pati, èske y'ap reponn ou: Wi, men nou?", bookId = 18),
        Verse(book = "Jòb", chapter = 38, verseNumber = 36, text = "Ki moun ki penmèt krabye konprann lè pou li anonse dlo pral desann fè inondasyon? Ki moun ki fè gwo zwezo sa a konnen lè lapli pral tonbe?", bookId = 18),
        Verse(book = "Jòb", chapter = 38, verseNumber = 37, text = "Ki moun ki ka konte kantite nwaj ki genyen, san manke yonn? Ki moun ki ka panche yo pou vide dlo lapli,", bookId = 18),
        Verse(book = "Jòb", chapter = 38, verseNumber = 38, text = "pou pousyè tè a tounen labou, pou boul tè yo kole ansanm?", bookId = 18),
        Verse(book = "Jòb", chapter = 38, verseNumber = 39, text = "Eske se ou ki jwenn manje pou bay lyon yo manje? Eske ou bay ti lyon yo manje plen vant yo,", bookId = 18),
        Verse(book = "Jòb", chapter = 38, verseNumber = 40, text = "kote yo kache nan twou yo a, osinon kote yo kouche ap tann nan nich yo a?", bookId = 18),
        Verse(book = "Jòb", chapter = 38, verseNumber = 41, text = "Ki moun ki pare manje pou kònèy yo, lè grangou fè yo soti nan nich yo, lè pitit yo ap rele nan pye m' pou m' ba yo manje?", bookId = 18),
        Verse(book = "Jòb", chapter = 39, verseNumber = 1, text = "Eske ou konnen lè kabrit mawon yo ap fè pitit? Eske ou janm wè kote fenmèl yo ap miba?", bookId = 18),
        Verse(book = "Jòb", chapter = 39, verseNumber = 2, text = "Eske ou konnen konbe mwa yo pote yon pitit nan vant yo? Kilè pitit yo rive dat pou yo fèt?", bookId = 18),
        Verse(book = "Jòb", chapter = 39, verseNumber = 3, text = "Eske ou konnen lè yo pral kwoupi pou miba, lè y'ap fè pitit yo nan mitan dezè a?", bookId = 18),
        Verse(book = "Jòb", chapter = 39, verseNumber = 4, text = "Pitit yo grandi, yo pran fòs, yo kite manman yo, y' ale, yo pa tounen.", bookId = 18),
        Verse(book = "Jòb", chapter = 39, verseNumber = 5, text = "Ki moun ki bay bourik mawon libète yo? Ki moun ki lage yo nan savann?", bookId = 18),
        Verse(book = "Jòb", chapter = 39, verseNumber = 6, text = "Mwen ba yo dezè pou kay yo. Mwen kite yo viv nan savann tè sale a.", bookId = 18),
        Verse(book = "Jòb", chapter = 39, verseNumber = 7, text = "Tout bri k'ap fèt nan lavil yo pa di yo anyen. Pesonn pa ka donte yo pou fè yo travay.", bookId = 18),
        Verse(book = "Jòb", chapter = 39, verseNumber = 8, text = "Yo mache nan tout mòn yo dèyè manje. Y'ap chache fèy vèt pou yo mete anba dan yo.", bookId = 18),
        Verse(book = "Jòb", chapter = 39, verseNumber = 9, text = "Eske ou ka fè bèf mawon travay pou ou? Eske l'ap rete pase nwit mare nan lakou kay ou?", bookId = 18),
        Verse(book = "Jòb", chapter = 39, verseNumber = 10, text = "Eske ou ka pase kòd nan kou yonn pou fè l' raboure tè a pou ou? Eske ou ka fè l' rale chari pou woule tè jaden ou yo?", bookId = 18),
        Verse(book = "Jòb", chapter = 39, verseNumber = 11, text = "Eske ou ka konte sou gwo fòs kouraj li pou fè li travay di pou ou?", bookId = 18),
        Verse(book = "Jòb", chapter = 39, verseNumber = 12, text = "Eske ou kwè l'ap asepte pote rekòt ou soti nan jaden? Eske l'ap asepte ranmase grenn ou yo sou glasi?", bookId = 18),
        Verse(book = "Jòb", chapter = 39, verseNumber = 13, text = "Otrich alèz lè l'ap bat zèl li, men, li pa ka vole tankou sigòy.", bookId = 18),
        Verse(book = "Jòb", chapter = 39, verseNumber = 14, text = "Otrich la ponn ze l' yo atè konsa. Se chalè tè a ki fè yo kale.", bookId = 18),
        Verse(book = "Jòb", chapter = 39, verseNumber = 15, text = "Li pa konnen nenpòt moun k'ap pase ka pile yo, nenpòt bèt nan raje ka kraze yo anba pye.", bookId = 18),
        Verse(book = "Jòb", chapter = 39, verseNumber = 16, text = "Li fè tankou ze yo pa pou li. Sa pa di l' anyen si li bay tèt li tout lapenn ponn ze yo pou gremesi,", bookId = 18),
        Verse(book = "Jòb", chapter = 39, verseNumber = 17, text = "Se mwen menm, Bondye, ki fè l' sòt konsa, ki pa ba li lespri menm.", bookId = 18),
        Verse(book = "Jòb", chapter = 39, verseNumber = 18, text = "Men, lè l' pran kouri, nanpwen kavalye sou chwal ki ka pran devan l'.", bookId = 18),
        Verse(book = "Jòb", chapter = 39, verseNumber = 19, text = "Eske se ou menm ki bay chwal yo fòs, ki mete bèl krenyen sou kou yo?", bookId = 18),
        Verse(book = "Jòb", chapter = 39, verseNumber = 20, text = "Eske se ou ki fè yo sote ponpe tankou kabrit, ki fè yo ranni pou fè moun pè?", bookId = 18),
        Verse(book = "Jòb", chapter = 39, verseNumber = 21, text = "Y'ap pyafe konsa nan ti fon yo, y'ap bat tè a ak zago yo. Yo kouri ak tout fòs yo lè yo nan lagè.", bookId = 18),
        Verse(book = "Jòb", chapter = 39, verseNumber = 22, text = "Se brave danje yo ye. Yo pa janm pè anyen. Pa gen zam ki pou fè yo fè bak.", bookId = 18),
        Verse(book = "Jòb", chapter = 39, verseNumber = 23, text = "Lè konsa, ti sak flèch ki nan do kavalye yo ap fè bri. Lans ak frenn ki nan men yo ap fè zèklè.", bookId = 18),
        Verse(book = "Jòb", chapter = 39, verseNumber = 24, text = "Yo eksite, yo pa ka tann. Y'ap kouri sou lènmi an. Lè yo tande twonpèt la soufle, yo pa ka rete an plas.", bookId = 18),
        Verse(book = "Jòb", chapter = 39, verseNumber = 25, text = "Chak fwa twonpèt la soufle, yo fè han! Yo gen tan pran sant batay la byen lwen. Yo tande chèf yo k'ap pase lòd byen fò.", bookId = 18),
        Verse(book = "Jòb", chapter = 39, verseNumber = 26, text = "Eske se ou ki moutre grigri jan pou l' vole lè li louvri zèl li yo vole ale nan sid?", bookId = 18),
        Verse(book = "Jòb", chapter = 39, verseNumber = 27, text = "Eske se ou ki bay malfini lòd pou li fè nich li byen wo sou tèt mòn yo?", bookId = 18),
        Verse(book = "Jòb", chapter = 39, verseNumber = 28, text = "Li rete sou tèt gwo wòch yo. Se la li pase nwit. Kote l' ye a, moun pa ka vin pran l'.", bookId = 18),
        Verse(book = "Jòb", chapter = 39, verseNumber = 29, text = "Se la li rete, l'ap veye bèt pou l' trape manje. Li te mèt byen lwen, l'ap wè yo ak je li.", bookId = 18),
        Verse(book = "Jòb", chapter = 39, verseNumber = 30, text = "Se san bèt ti malfini yo bwè. Kote ki gen kadav, se la yo ye.", bookId = 18),
        Verse(book = "Jòb", chapter = 40, verseNumber = 1, text = "Seyè a pale ak Jòb. Li di l' konsa:", bookId = 18),
        Verse(book = "Jòb", chapter = 40, verseNumber = 2, text = "-Jòb monchè, ou menm ki t'ap kenbe tèt ak Bondye ki gen tout pouvwa a, ou p'ap kite pou li? Ou menm ki t'ap kritike Bondye a, ou vle reponn li koulye a?", bookId = 18),
        Verse(book = "Jòb", chapter = 40, verseNumber = 3, text = "Jòb reponn Seyè a, li di l' konsa:", bookId = 18),
        Verse(book = "Jòb", chapter = 40, verseNumber = 4, text = "-Mwen pa t' konn sa m' t'ap di. Kisa pou m' reponn ou? Se fèmen pou m' fèmen bouch mwen.", bookId = 18),
        Verse(book = "Jòb", chapter = 40, verseNumber = 5, text = "Mwen pale twòp deja. Mwen pa gen anyen pou m' di ankò.", bookId = 18),
        Verse(book = "Jòb", chapter = 40, verseNumber = 6, text = "Seyè a rete nan van tanpèt la, li pale ak Jòb ankò. Li di l':", bookId = 18),
        Verse(book = "Jòb", chapter = 40, verseNumber = 7, text = "-Koulye a, kanpe! Mete gason sou ou! Mwen pral poze ou keksyon, se pou ou reponn mwen.", bookId = 18),
        Verse(book = "Jòb", chapter = 40, verseNumber = 8, text = "Eske ou soti vre pou moutre se lenjistis m'ap fè ou? Se mwen menm ki antò, ou menm ou gen rezon?", bookId = 18),
        Verse(book = "Jòb", chapter = 40, verseNumber = 9, text = "Eske ou gen menm fòs avè m'? Eske vwa ou ka gwonde tankou vwa pa m'?", bookId = 18),
        Verse(book = "Jòb", chapter = 40, verseNumber = 10, text = "Si se konsa, kanpe non! Kenbe tèt ou byen dwat! Gade tout moun nan je! Mete chèf sou ou! Fè wè pouvwa ou!", bookId = 18),
        Verse(book = "Jòb", chapter = 40, verseNumber = 11, text = "Gade moun k'ap gonfle lestonmak yo nan je. Move sou yo! Kraze kouraj yo!", bookId = 18),
        Verse(book = "Jòb", chapter = 40, verseNumber = 12, text = "Wi. Gade yo nan je. Fè yo bese tèt yo! Kraze mechan yo la kote yo ye a!", bookId = 18),
        Verse(book = "Jòb", chapter = 40, verseNumber = 13, text = "Mete yo tout anba tè. Mare bouch yo tout nan twou kote mò yo ye a.", bookId = 18),
        Verse(book = "Jòb", chapter = 40, verseNumber = 14, text = "Lè sa a, mwen menm, m'a fè lwanj ou, dèske avèk pwòp fòs ou ou te rive kraze yo.", bookId = 18),
        Verse(book = "Jòb", chapter = 40, verseNumber = 15, text = "Gade gwo bèt lèd yo rele Beyemòt la. Se mwen ki fè l', menm jan se mwen ki fè ou. Se zèb li manje tankou bèf.", bookId = 18),
        Verse(book = "Jòb", chapter = 40, verseNumber = 16, text = "Tout fòs li, se nan ren l'. Tout kouraj li, se nan venn vant li.", bookId = 18),
        Verse(book = "Jòb", chapter = 40, verseNumber = 17, text = "Ke l' kanpe tankou yon pye sèd. Venn janm li yo fè boul.", bookId = 18),
        Verse(book = "Jòb", chapter = 40, verseNumber = 18, text = "Zo l' yo di tankou fè tiyo. Janm li yo tankou de bout fè.", bookId = 18),
        Verse(book = "Jòb", chapter = 40, verseNumber = 19, text = "Nan tout bèt mwen fè, se li ki pote premye pri. Se mwen ki kreye l' la sèlman ki ka fè l' bat ba.", bookId = 18),
        Verse(book = "Jòb", chapter = 40, verseNumber = 20, text = "Li manje zèb ki pouse sou mòn kote lòt bèt nan bwa ap pran plezi yo.", bookId = 18),
        Verse(book = "Jòb", chapter = 40, verseNumber = 21, text = "Li kouche anba raje. Li kache nan mitan wozo marekay yo.", bookId = 18),
        Verse(book = "Jòb", chapter = 40, verseNumber = 22, text = "Raje yo fè lonbray pou li. Pye sikren bò larivyè yo ap pwoteje l'.", bookId = 18),
        Verse(book = "Jòb", chapter = 40, verseNumber = 23, text = "Larivyè ap desann, sa pa di l' anyen. Larivyè Jouden gonfle rive wotè bouch li, li kè pòpòz.", bookId = 18),
        Verse(book = "Jòb", chapter = 40, verseNumber = 24, text = "Ki moun ki ka pete je l' pou mete men sou li? Ki moun ki ka pèse bwa nen l' ak yon fwenn bwa.", bookId = 18),
        Verse(book = "Jòb", chapter = 41, verseNumber = 1, text = "Eske ou ka pran levyatan an nan zen? Eske ou ka mare lang li ak yon kòd?", bookId = 18),
        Verse(book = "Jòb", chapter = 41, verseNumber = 2, text = "Eske ou ka pase yon bwa wozo nan nen l'? Eske ou ka pèse machwè l' ak yon gwo zen?", bookId = 18),
        Verse(book = "Jòb", chapter = 41, verseNumber = 3, text = "Eske li pral mande ou: Tanpri souple, kite m' ale? Eske l'ap pale dous avè ou?", bookId = 18),
        Verse(book = "Jòb", chapter = 41, verseNumber = 4, text = "Eske l'ap pase kontra avè ou pou l' sèvi ou pou tout tan?", bookId = 18),
        Verse(book = "Jòb", chapter = 41, verseNumber = 5, text = "Eske ou ka mare l' tankou yon ti zwezo pou pitit fi ou yo ka jwe avè l'?", bookId = 18),
        Verse(book = "Jòb", chapter = 41, verseNumber = 6, text = "Eske moun k'ap fè lapèch yo pral fè lajan avè l'? Eske machann yo pral koupe l' an moso pou yo vann?", bookId = 18),
        Verse(book = "Jòb", chapter = 41, verseNumber = 7, text = "Eske ou ka pike tout po kò l' ak fwenn? Eske ou ka pèse tèt li ak yon fwenn?", bookId = 18),
        Verse(book = "Jòb", chapter = 41, verseNumber = 8, text = "Seye mete men ou sou li yon grenn fwa, ou p'ap janm fè sa ankò, lè w'a chonje sa l'a fè ou!", bookId = 18),
        Verse(book = "Jòb", chapter = 41, verseNumber = 9, text = "Depi ou wè levyatan an, ou pèdi tout kouraj ou. Ou annik wè l', ou tonbe atè.", bookId = 18),
        Verse(book = "Jòb", chapter = 41, verseNumber = 10, text = "Si yo leve l' nan dòmi, li move. Pa gen moun ki ka kanpe devan l'.", bookId = 18),
        Verse(book = "Jòb", chapter = 41, verseNumber = 11, text = "Ki moun ki ka atake l' san anyen pa rive l'? Pa gen moun sou latè ki ka fè sa.", bookId = 18),
        Verse(book = "Jòb", chapter = 41, verseNumber = 12, text = "Mwen pa bezwen di ou anyen sou pa t' janm li yo. Men, m'a fè ou konnen pa gen bèt ki gen fòs pase l'.", bookId = 18),
        Verse(book = "Jòb", chapter = 41, verseNumber = 13, text = "Pesonn pa janm rive dechire premye po li. Ni pesonn pa janm rive pèse karapas li.", bookId = 18),
        Verse(book = "Jòb", chapter = 41, verseNumber = 14, text = "Ki moun ki janm fòse l' louvri bouch li? Dan nan bouch li, se bagay ki pou fè moun kouri.", bookId = 18),
        Verse(book = "Jòb", chapter = 41, verseNumber = 15, text = "Tout do l', se yon seri gwo kal mare yonn ak lòt. Yo di kou wòch.", bookId = 18),
        Verse(book = "Jòb", chapter = 41, verseNumber = 16, text = "Yo kole yonn ak lòt, yo fè yon sèl. Pa gen yon ti fant nan mitan yo pou lè pase.", bookId = 18),
        Verse(book = "Jòb", chapter = 41, verseNumber = 17, text = "Yo sitèlman byen kole yonn ak lòt anyen pa ka separe yo.", bookId = 18),
        Verse(book = "Jòb", chapter = 41, verseNumber = 18, text = "Lè l' estènen, limyè fè yan-yan. Je l' klere tankou solèy lè l'ap leve.", bookId = 18),
        Verse(book = "Jòb", chapter = 41, verseNumber = 19, text = "Flanm dife ap soti nan bouch li. Tensèl dife ap vole soti ladan l'.", bookId = 18),
        Verse(book = "Jòb", chapter = 41, verseNumber = 20, text = "Lafimen ap soti nan tout twou nen l' tankou nan yon chodyè k'ap bouyi sou dife.", bookId = 18),
        Verse(book = "Jòb", chapter = 41, verseNumber = 21, text = "Souf li ta ka limen bwa dife. Flanm dife ap soti nan bouch li.", bookId = 18),
        Verse(book = "Jòb", chapter = 41, verseNumber = 22, text = "Se nan kou li tout fòs li ye. Depi moun wè l', kè yo kase.", bookId = 18),
        Verse(book = "Jòb", chapter = 41, verseNumber = 23, text = "Po li fè kal kal sou tout kò li. Yo kole yonn ak lòt. Yo di kou wòch.", bookId = 18),
        Verse(book = "Jòb", chapter = 41, verseNumber = 24, text = "Kè li di kou wòch, li pa pè anyen. Li fèm kou wòl moulen.", bookId = 18),
        Verse(book = "Jòb", chapter = 41, verseNumber = 25, text = "Lè li leve kanpe, ata gwonèg yo pè. Yo kouri san gad dèyè.", bookId = 18),
        Verse(book = "Jòb", chapter = 41, verseNumber = 26, text = "Pa gen nepe ki ka blese l'. Ni fwenn, ni lans, ni flèch pa ka fè l' anyen.", bookId = 18),
        Verse(book = "Jòb", chapter = 41, verseNumber = 27, text = "Pou li, nenpòt bout fè lejè kou pay, nenpòt bout asye mou tankou bannann mi.", bookId = 18),
        Verse(book = "Jòb", chapter = 41, verseNumber = 28, text = "Pa gen kout flèch ki pou fè l' kouri. Wòch fistibal, se boul koton pou li.", bookId = 18),
        Verse(book = "Jòb", chapter = 41, verseNumber = 29, text = "Yon baton fè se yon bwa mayi pou li. Li ri lè yo voye lans sou li.", bookId = 18),
        Verse(book = "Jòb", chapter = 41, verseNumber = 30, text = "Anba vant li graj graj tankou moso kannari kraze. Kote li pase nan labou a, li make l' tankou machin k'ap kraze boul tè nan jaden.", bookId = 18),
        Verse(book = "Jòb", chapter = 41, verseNumber = 31, text = "Lè l' plonje, li boulvèse fon lanmè a, se tankou dlo nan chodyè k'ap bouyi sou dife. Li fè l' bouyi tankou dlo nan veso y'ap boule odè.", bookId = 18),
        Verse(book = "Jòb", chapter = 41, verseNumber = 32, text = "Lè l'ap naje, li kite nan dlo a yon chemen ki klere nan solèy la. Li fè tout lanmè a kimen.", bookId = 18),
        Verse(book = "Jòb", chapter = 41, verseNumber = 33, text = "Pa gen bèt tankou l' sou latè. Bondye kreye l' pou l' pa janm pè anyen.", bookId = 18),
        Verse(book = "Jòb", chapter = 41, verseNumber = 34, text = "Li gade bèt ki pi fewòs yo nan je. Se li ki wa tout bèt sovaj yo.", bookId = 18),
        Verse(book = "Jòb", chapter = 42, verseNumber = 1, text = "Men sa Jòb reponn Seyè a:", bookId = 18),
        Verse(book = "Jòb", chapter = 42, verseNumber = 2, text = "-Mwen konnen, Seyè, ou gen tout pouvwa. W'ap fè tou sa ou mete nan tèt ou pou ou fè.", bookId = 18),
        Verse(book = "Jòb", chapter = 42, verseNumber = 3, text = "Ou mande kisa mwen ye menm pou m'ap poze keksyon sou plan travay ou, ak yon bann diskou ki pa vle di anyen. Mwen te louvri bouch mwen pale sou sa m' pa konprann, sou bèl bagay ki twò fò pou mwen.", bookId = 18),
        Verse(book = "Jòb", chapter = 42, verseNumber = 4, text = "Ou te mande m' pou m' koute sa w'ap di m', pou m' pare pou m' reponn ou.", bookId = 18),
        Verse(book = "Jòb", chapter = 42, verseNumber = 5, text = "Sa m' te konn sou ou a, se sa lòt moun te di m' ase. Koulye a, mwen wè ou ak je mwen.", bookId = 18),
        Verse(book = "Jòb", chapter = 42, verseNumber = 6, text = "Se konsa, mwen wete tou sa mwen te di. Mwen kouche sou sann ak nan pousyè, m'ap mande padon.", bookId = 18),
        Verse(book = "Jòb", chapter = 42, verseNumber = 7, text = "Lè Seyè a fin pale konsa ak Jòb, li pale ak Elifaz, moun lavil Teman an. Li di l' konsa: -Mwen te fache sou ou ak sou de zanmi ou yo, paske sa nou di sou mwen an pa vre menm. Nou pa t' pale tankou Jòb, sèvitè m' lan.", bookId = 18),
        Verse(book = "Jòb", chapter = 42, verseNumber = 8, text = "Atòkile, men sa pou nou fè: Pran sèt towo bèf ak sèt belye mouton. Al jwenn Jòb ak yo. N'a ofri yo pou nou, n'a boule yo nèt. Jòb li menm va lapriyè pou nou. M'a reponn li. Konsa, m'a fè pa nou. Mwen p'ap pini nou deske nou pa t' pale byen sou mwen, jan Jòb, sèvitè m' lan, te fè l' la.", bookId = 18),
        Verse(book = "Jòb", chapter = 42, verseNumber = 9, text = "Elifaz, moun lavil Teman an, Bildad, moun lavil Chwa a, ak Sofa, moun lavil Naama a, al fè tou sa Seyè a te di yo fè a. Seyè a fè tou sa Jòb te mande l' nan lapriyè a.", bookId = 18),
        Verse(book = "Jòb", chapter = 42, verseNumber = 10, text = "Apre Jòb te fin lapriyè pou twa zanmi l' yo, Seyè a mete l' kanpe ankò. Tout zafè l' vin mache byen ankò. Lèfini, Seyè a ba li de fwa lavalè tou sa li te genyen anvan an.", bookId = 18),
        Verse(book = "Jòb", chapter = 42, verseNumber = 11, text = "Tout frè ak sè l' yo ansanm ak tout ansyen zanmi l' yo vin wè li. Yo fè fèt avè l' lakay li. Yo fè l' konnen jan sa te fè kè yo mal pou li pou tout malè sa yo Seyè a te voye sou li. Yo fè l' pran kouraj. Yo chak yo fè l' kado yon pyès ajan ak yon bag lò.", bookId = 18),
        Verse(book = "Jòb", chapter = 42, verseNumber = 12, text = "Apre sa, Seyè a te beni Jòb plis pase jan li te fè l' anvan an. Jòb te vin genyen katòzmil (14.000) mouton, simil (6.000) chamo, demil (2.000) tèt bèf ak mil (1000) manman bourik.", bookId = 18),
        Verse(book = "Jòb", chapter = 42, verseNumber = 13, text = "Li fè sèt pitit gason ak twa pitit fi.", bookId = 18),
        Verse(book = "Jòb", chapter = 42, verseNumber = 14, text = "Li rele pi gran pitit fi a Jemina, dezyèm lan Kesya, twazyèm lan Kerèn apouk.", bookId = 18),
        Verse(book = "Jòb", chapter = 42, verseNumber = 15, text = "Nan tout peyi a pa t' gen pi bèl fanm pase twa pitit fi Jòb yo. Papa a te ba yo chak yon pòsyon nan byen l' yo ansanm ak frè yo.", bookId = 18),
        Verse(book = "Jòb", chapter = 42, verseNumber = 16, text = "Apre sa, Jòb viv jouk li rive gen sankarantan sou tèt li. Li wè pitit pitit li yo ak pitit pitit pitit li yo, jouk rive sou kat jenerasyon.", bookId = 18),
        Verse(book = "Jòb", chapter = 42, verseNumber = 17, text = "Lè li mouri, li te fin vye granmoun, li te viv kont li.", bookId = 18)
    )
}

